#!/usr/bin/env node
/* ============================================================================
 * 机甲指挥 · 网格大地图测试（作者 2026-10-10 拍板：换成战棋那套「网格 + 推进剂」）
 * ----------------------------------------------------------------------------
 * 任务书第 5 条点名要测的 8 件事，这里一件一件真的跑：
 *   [1] 地图生成的硬性条件：6×4 / 每格 78% 存在 / 连通格数 ≥15 / 最右 2 列 ≥2 格 /
 *       最右 2 列里最远的 BFS 距离 ≥5 —— **跑 20 个种子**，逐个检查并打印最小值。
 *   [2] 每层节点个数（★ 2026-10-11 节点改造：出口 = 尽头 / 小径两个互斥类型；休整第 1 层不放、隧道第 2 层起）。
 *   [3] 移动按 BFS：消耗 = 走过的格数、可以跳格（一次点远的格子）、推进剂不够就走不到。
 *   [4] 推进剂 0 → 触发追击战（战棋 30:34）；追击完下一层推进剂上限 −2（战棋 28:9）。
 *   [5] 7 种新节点各自的结算：黑市 / 瞭望站 / 隧道 / 遗迹 / 休整 / 出口守军 / 侵蚀源。
 *   [6] 终点通关：第 4 层出口守军打赢 → 走到出口 → 本局结束、结局 = 通关、结算屏上有「通关」。
 *   [7] 存档 → 读档：地图（逐格）/ 位置 / 推进剂 / 已走过 全都一致。
 *   [8] 同种子两次逐字相同（地图 JSON 一字不差）。
 *   ★ 2026-10-11 节点改造新增（作者拍板「全部照做」，逐条对 `协作/节点设计对比-黑流树海.md` §3）：
 *   [9] 出口两型 + 换希望 + 小径带推进剂到下一层（照抄「险路尽头 / 险路小径」）
 *   [10] 出口守军补奖励（希望 / 源碳 / 零件 —— 推翻改前的「打赢零收益」）
 *   [11] 黑市：刷新（4/8/12/16、上限 4 次、照抄原作诡意行商）+ 卖零件（照抄战棋 30:117-120）
 *   [12] 事件换成有代价的（战棋原版 5 个 + 黑流树海 3 个，每个都写出处；
 *        ★ 2026-10-12：「迷路的机师」按作者试玩后的拍板改成「花 4 源碳结晶 → 一张随机招募券」）
 *   [13] 瞭望站不再给希望（远眺 4 格 / 登高 12 格 +1 推进剂，照抄原作羽瞰点）
 *   [14] 遗迹三选一（2 作战耐久 / 8 源碳 / 离开）——「50% 送藏品」已删
 *   [15] 休整互斥三选一（耐久 +2 / 晋升 −1 希望 / 推进剂 +2），第 1 层不出现
 *   [16] 隧道代价（进入花 1 推进剂）+ 侵蚀源代价（硬闯 +15% / 花 8 源碳净化）
 *   [17] 总检：13 个节点逐个过一遍「收益 / 代价 / 有没有选择」，没有一个「零代价纯收益」
 *   [18] 节点新增状态进存档 v3 + 旧存档缺字段 / 坏值补默认值、不崩
 *   [19]/[20] 结果条（每条动作都给一句结果）/ 记录屏
 *   [21] 肉鸽战斗也出「本场战报」并写进 RUN.日志（三层反馈的结算那一层）
 *   [22] ★ 2026-10-12：「迷路的机师」不再是白送 —— 花 4 源碳结晶换一张随机招募券
 *        （源碳 3 选不了、源碳 4 才成交；来源 = 事件；同种子两遍逐字相同；没有 RUN / 坏数据不崩）
 *   [23] ★ 2026-10-12「记录导出」：**本局日志（`RUN.日志`）也能复制 / 下载** ——
 *        入口（记录屏 + 大地图）/ 导出文本（摘要字段 + 逐条原文照抄，抽 3 行）/ 三层反馈 /
 *        复制·下载的成功与失败两条路 / 没有 RUN·空日志·坏数据不崩 / 同种子两遍逐字相同（去掉「时间：」那行）
 *   [24] ★ 2026-10-13 修 bug「出口守军打输了却还是通关了」（作者试玩 + 对局录像日志第 280–300 条）：
 *        守军没清时**第 4 层不许通关、第 1–3 层不许换层** —— 包括「推进剂 0 → 追击战」那一条；
 *        被挡的那一趟记进 `RUN.待换层`（存档往返一致），守军一打赢**当场补上**；
 *        「在别处用光推进剂的追击战」照旧换层（第 [4] 段的断言没删没放宽）；同种子两遍逐字相同
 *   [25] ★ 2026-10-13 修「很多选项点不了」（界面线 `ea4418a`）：弹窗链路真弹窗返回 Promise /
 *        `肉鸽战斗类型` 初值 `'作战'` → `null` / 招募站那颗孤儿动作 `跳过` → `跳过节点`；
 *        ★ 这一节**全走 `界面.动作('弹窗:…')` 直调** —— 它没覆盖浏览器那条路（见 [26]）
 *   [26] ★ 2026-10-13 第二次修「遗迹三选一还是选不了」（作者：「有弹窗，但点了完全没反应」）：
 *        真因 = 事件委托先把 `data-act` 按 `:` 拆开（`动=弹窗 / 参=<值>`），而 `动作内()` 只认
 *        没拆过的整串 `'弹窗:<值>'` → `回答()` 从来没被调用过（弹窗不消失、状态一个字节不动）。
 *        修在 `80-界面.js` 的 `动作内()`（两段式那条也接住）。这一节**自己接一次 `#screen` 的 click 委托、
 *        真派发事件**（不再绕过 `接线()`），断言：遗迹三个选项各点一次都真的生效且互不相同 /
 *        同族节点（隧道·休整·瞭望站·侵蚀源·招募站）各点一次 / 两条路（Promise 与 `对话框钩子`）逐字相同 /
 *        同种子两遍逐字相同 / 没有弹窗·没有 RUN 时不崩
 *   [26] ⑧ ★ 2026-10-13 第三次修同一族（界面线报「调参室那一屏的选项点了行为不对」）：
 *        真因 = `接线()` 那句 `const [动, 参] = String(data-act).split(':')` —— **解构只取前两个元素**，
 *        含 **≥2 个 `:`** 的 `data-act`（`调参室:类型:精英`）第三段起全丢 → `动作()` 只收到
 *        `('调参室','类型')`、`调参室动作()` 再拆一次只剩空参数。⚠ **不是 Node / `split` 的 bug**
 *        （界面线报错过一次）：错的是解构只要两个。修在 `接线()`（保住第一个 `:` 之后的所有段）。
 *        ⑧ 是一段**清单式断言（随代码增长）**：把能画出来的屏全画一遍收齐 `data-act`，
 *        含 ≥2 个 `:` 的每一个都必须落在 8 条形状里；然后**逐一从屏上真按钮经委托点一次**，
 *        断言派发到的 `(动, 参)` 与该走的处理逻辑；外加「没有 `:` → 参恰好 null」「任意段数」「今天修的三处仍在」。
 *
 * 数值出处全部写在 `src/js/91-地图.js` / `src/js/90-肉鸽.js` 的注释里（标 `26-地图生成.js:行号`）。
 * 不依赖任何 npm 包：用 tests/lib/dom-stub.mjs 把 index.html 的内联脚本跑起来。
 * 用法：node tests/map.js
 * ========================================================================== */
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';
import { loadPage } from './lib/dom-stub.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, '..');

let fails = 0;
const errs = [];
const ok = m => console.log('  ✓ ' + m);
const bad = m => { fails++; errs.push(m); console.log('  ✗ ' + m); };
const info = m => console.log('    · ' + m);

const page = loadPage(join(ROOT, 'index.html'), { quiet: true });
if (page.errors.length) {
  page.errors.forEach(e => bad('内联脚本执行报错：' + e));
  console.log(`\nERRS [${errs.join(' | ')}]`);
  process.exit(1);
}
const G = page.sandbox.__game;
const 界面 = G.界面, 播放 = G.播放, 肉鸽 = G.肉鸽, 肉鸽界面 = G.肉鸽界面;
界面.手动播放 = true;
界面.设跳过动画(true);
console.log(`网格大地图测试：机甲指挥 ${G.version} · ${G.milestone}\n`);

/** 把当前这一场打完（和 tests/run.js 同一套：一回合一个回合地点开打 + tick） */
function 打完这一场() {
  let 轮 = 0;
  while (界面.屏 === '战斗' && 轮++ < 30) {
    界面.开打();
    let n = 0;
    while (界面.阶段 === '播放' && n++ < 100000) 播放.tick();
  }
}
const 屏文字 = () => String(page.byId.get('screen') && page.byId.get('screen').innerHTML || '');
/** ★ 2026-10-11 券系统：**肉鸽开局名册是空的**（分队不带机体；改前白送默认五人队）。
 *  这份测试测的是地图 / 节点，凡是「要摆几台出去打一场」的段落都得先**真的招人** ——
 *  走玩家那条路（开招募屏 → 选中一张对得上的券 → 招募），不往 `RUN.队伍` 里硬塞。
 *  ★ 2026-10-12 修真 bug：**没券就不能招** → 这里没有「不用券」那一步了（见函数里那句注释）。
 *  测试给足希望：要测的是流程，不是经济。 */
function 招几个(n = 3, 预算 = 60) {
  const R = 肉鸽.RUN;
  if (!R) return 0;
  const 一起 = () => {
    界面.开屏('招募');
    const 费 = k => G.肉鸽数值.招募费[G.tierOf(k)] || 0;
    let 招到 = 0;
    for (let 轮 = 0; R.队伍.length < n && 轮 < 20; 轮++) {
      const 已有 = new Set(R.队伍.map(m => m.键));
      const 人 = G.ALLY_T.map(t => t.mech).filter(k => !已有.has(k));
      let 成了 = false;
      for (let i = 0; i < (R.券 || []).length && !成了; i++) {
        const 合 = 人.filter(k => G.券合(R.券[i], k)).sort((a, b) => 费(a) - 费(b));
        for (const k of 合) {
          if (R.希望 < 费(k)) continue;
          界面.用券(i);
          const r = 肉鸽.招募(k, i);
          if (r && r.ok) { 招到++; 成了 = true; break; }
          肉鸽界面.选中的券 = null;
        }
      }
      if (成了) continue;
      /* ★ 2026-10-12 修真 bug：**没券就不能招**（`90-肉鸽.js` 的 `招募()` 没券直接拒绝），
         所以这里**没有「不用券」那一步了**；一张能用的券都没有时补一张同类券再试（测试的补券口子，
         招募那一步照旧走 `界面.用券` → `肉鸽.招募(键, 下标)`）。 */
      肉鸽界面.选中的券 = null;
      const 能付 = 人.filter(k => R.希望 >= 费(k)).sort((a, b) => 费(a) - 费(b))[0];
      if (能付 == null) break;
      R.券.push({ 类: '职业', 名: G.tplOf(能付).tags.战斗分类, 档: null, 来源: '测试' });
      const 补 = R.券.length - 1;
      界面.用券(补);
      const r2 = 肉鸽.招募(能付, 补);
      if (r2 && r2.ok) { 招到++; continue; }
      肉鸽界面.选中的券 = null;
      break;
    }
    if (界面.屏 !== '大地图') 界面.开屏('大地图');
    return 招到;
  };
  const 招到 = 一起();
  /* 希望不够时**再补预算重来**（测试给足希望：要测的是流程，不是经济）。
     先不补、招不够才补 —— 免得平白改掉后面「希望从 X 涨到 Y」那几条对照断言。 */
  if (R.队伍.length < n) { R.希望 += 预算; return 一起(); }
  return 招到;
}
/** 新开一局（走界面，和玩家一样）。
 *  ★ 2026-10-11 券系统：开完局**先招 3 台**（开新局现在停在招募屏）—— 这份测试后面凡是
 *  「点战斗格 → 编队 → 开战」的段落都要有名册可用；改前是开局白送的默认五人队。
 *  ★ 种子改成**开局时**就传给 `开新局:<种子>`（走 `界面.开新局(种子)` 那条路，和 run.js 一样）——
 *  这样「开局 3 张券」也是这个种子抽的（以前是开出局之后再改 `RUN.种子` 重铺层）。 */
function 开一局(种子) {
  界面.动作('回菜单'); 界面.动作('去分队'); 界面.动作('选分队', '无');
  界面.动作('开新局' + (种子 == null ? '' : ':' + String(种子 >>> 0)));
  招几个(3);
  return 肉鸽.RUN;
}
/** 格号 → 可读坐标 */
const 坐标 = k => `(${G.格列(k) + 1},${G.格行(k) + 1})`;
/** 地图 JSON（逐格，测试对账用） */
const 地图JSON = R => JSON.stringify(R.地图);
/** 这一层里第一个某种类型的格号 */
const 找格 = (R, 类型) => Object.keys(R.地图.格).map(Number).find(k => R.地图.格[k].类型 === 类型);

/* ============================ [1] 地图生成的硬性条件（20 个种子） ============================
 * ★ 2026-10-12 地图大改：这一段**整段按新规格重写**（旧断言 6×4 / 78% / ≥15 / 最右 2 列 ≥2 /
 *   最远 BFS ≥5 / 起点第 1 列 全部作废）。新规格与「旧 → 新 → 为什么」的逐条对照表在
 *   `协作/任务板.md` 的「地图大改」段；这里的每一条都是**真的跑 80 张图**统计出来的。 */
console.log('[1] 地图生成的硬性条件（正方形逐层 5×5/6×6/6×6/7×7 · 存在率 · 连通下限 · 最下排 · 收费站）—— 跑 20 个种子');
{
  const 种子们 = [];
  for (let i = 0; i < 20; i++) 种子们.push((20261010 + i * 7919) >>> 0);
  const 结果 = [];
  let 全好 = true;
  let 出口拉开差 = 0, 守军割点 = 0, 守军必经 = 0, 守军贴出口 = 0, 起点错 = 0, 出口行错 = 0;
  for (const 种子 of 种子们) {
    for (const 层 of [1, 2, 3, 4]) {
      const m = G.生成层(层, G.地图种子(种子, 层));
      const 形状 = G.形状(层);
      const L = m.列数;
      const 格们 = Object.keys(m.格).map(Number);
      const 距离 = G.BFS距离(m.起点, m.格, L);
      const 最下排 = 格们.filter(k => G.格行(k, L) === m.行数 - 1);
      const 越界 = 格们.filter(k => G.格列(k, L) < 0 || G.格列(k, L) >= L || G.格行(k, L) < 0 || G.格行(k, L) >= m.行数);
      const 中列 = (L - 1) >> 1;
      /* 两个出口在图上拉开 ≥3 步（调研 §5 A5） */
      const 出口距离 = G.BFS距离(m.出口尽头, m.格, L).get(m.出口小径);
      /* 守军 = 收费站：割点 / 必经点 / 贴着一个出口 */
      const 有 = new Set(格们);
      const 必尽 = G.必经点(有, m.起点, m.出口尽头, L);
      const 必径 = G.必经点(有, m.起点, m.出口小径, L);
      const 是必经 = 必尽.includes(m.守军) || 必径.includes(m.守军);
      const 是割点 = G.割点们(有, L).has(m.守军);
      const 贴出口 = G.邻居(m.守军, L).includes(m.出口尽头) || G.邻居(m.守军, L).includes(m.出口小径);
      const 好 = m.列数 === 形状.列数 && m.行数 === 形状.行数 && m.列数 === m.行数
        && 格们.length >= 形状.连通下限
        && 格们.every(k => 距离.has(k))                     // 全部连通
        && 越界.length === 0                                // 没有一个格跑到形状外面
        && 最下排.length >= 1                                // 出口那一排有格
        && 出口距离 >= 3                                    // 两个出口拉开 ≥3 步
        && 贴出口;                                          // 守军仍然守着出口
      if (G.格列(m.起点, L) !== 中列 || G.格行(m.起点, L) !== 0) 起点错++;
      if (G.格行(m.出口尽头, L) !== m.行数 - 1) 出口行错++;
      if (出口距离 < 3) 出口拉开差++;
      if (是割点) 守军割点++;
      if (是必经) 守军必经++;
      if (贴出口) 守军贴出口++;
      if (!好) {
        全好 = false;
        bad(`种子 ${种子} 第 ${层} 层不达标：${m.列数}×${m.行数}、格数 ${格们.length}（下限 ${形状.连通下限}）、最下排 ${最下排.length}、出口距离 ${出口距离}`);
      }
      结果.push({ 种子, 层, 格数: 格们.length, 最下排: 最下排.length, 出口距离, 越界: 越界.length });
    }
  }
  const 小 = (键) => Math.min(...结果.map(r => r[键]));
  const 大 = (键) => Math.max(...结果.map(r => r[键]));
  if (全好) {
    ok(`20 个种子 × 4 层 = ${结果.length} 张地图全部达标：正方形（列数 = 行数）、连通格数 ${小('格数')}–${大('格数')}、` +
       `最下排 ${小('最下排')}–${大('最下排')} 格、两个出口图上距离 ${小('出口距离')}–${大('出口距离')} 步（≥3）、形状外 ${大('越界')} 格`);
  } else {
    bad(`有地图不达标（上面逐条列了）`);
  }
  info(`逐层形状 / 存在率 / 连通下限：` + [1, 2, 3, 4].map(L => `第${L}层 ${G.形状(L).列数}×${G.形状(L).行数} p=${G.形状(L).存在率} 下限=${G.形状(L).连通下限}`).join(' · '));
  info(`起点 = 最上排中间格（错 ${起点错} 张）；出口尽头在最下排（错 ${出口行错} 张）；守军：割点 ${守军割点}/${结果.length} · 必经点 ${守军必经}/${结果.length} · 贴出口 ${守军贴出口}/${结果.length}`);
  /* 存在率：拿每层的**期望存在格数**对账（`形状表` 的曲线 0.78 / 0.72 / 0.66 / 0.62）。
     ⚠ 口径：生成时会给「起点→出口」补一条 L 形走廊（见 `91-地图.js` 的 `保证连通`），
     所以实测会**高于**曲线（第 4 层最明显：+2–5 格 ≈ +5 个百分点）。断言钉的是
     「**不低**于曲线（补格只会多不会少）」+「高不过曲线 + 0.08」+「逐层递减」三条。 */
  const 实测率 = {};
  for (const 层 of [1, 2, 3, 4]) {
    const 形状 = G.形状(层);
    const 格数们 = [];
    for (let i = 0; i < 200; i++) {
      const 种子 = (555000 + i * 104729) >>> 0;
      try { 格数们.push(Object.keys(G.生成层(层, 种子).格).length); } catch (e) { /* 生成失败不计 */ }
    }
    const 率 = 格数们.reduce((a, b) => a + b, 0) / 格数们.length / (形状.列数 * 形状.行数);
    实测率[层] = 率;
    if (率 >= 形状.存在率 && 率 - 形状.存在率 < 0.08) {
      ok(`第 ${层} 层每格存在概率 ${形状.存在率} → 实测 ${(率 * 100).toFixed(1)}%（补的走廊让它略高，上限 +8 个百分点）`);
    } else bad(`第 ${层} 层存在概率不对：实测 ${(率 * 100).toFixed(1)}%（曲线 ${形状.存在率}，允许高 8 个百分点以内）`);
  }
  const 率们 = [1, 2, 3, 4].map(层 => G.形状(层).存在率);
  if (率们.every((x, i) => i === 0 || x <= 率们[i - 1])) ok(`存在率逐层不升：${率们.join(' → ')}（层越高越稀，调研 §3.2 曲线）`);
  else bad(`存在率曲线不单调：${率们.join(' → ')}`);
  info(`实测存活率（含补的走廊）：${[1, 2, 3, 4].map(L => `第${L}层 ${(实测率[L] * 100).toFixed(1)}%`).join(' / ')}`);
  const 边们 = [1, 2, 3, 4].map(层 => G.形状(层).列数);
  if (边们.every((x, i) => i === 0 || x >= 边们[i - 1])) ok(`正方形边长逐层不降：${边们.join(' → ')}（作者第 ② 条要求：地图随层扩大）`);
  else bad(`边长曲线不单调：${边们.join(' → ')}`);
  /* 起点 / 出口 / 出口两型（拿一张图逐条看） */
  const m = G.生成层(1, G.地图种子(20261010, 1));
  const 中列 = (m.列数 - 1) >> 1;
  if (G.格列(m.起点, m.列数) === 中列 && G.格行(m.起点, m.列数) === 0) {
    ok(`起点 = **最上排的中间格** ${坐标(m.起点)}（列 ${中列 + 1} / ${m.列数}，作者 2026-10-12 拍板）`);
  } else bad(`起点位置不对：${坐标(m.起点)}`);
  if (G.格行(m.出口尽头, m.列数) === m.行数 - 1) ok(`出口尽头 = **最下排**离中间最近的连通格 ${坐标(m.出口尽头)}（BFS ${G.BFS距离(m.起点, m.格, m.列数).get(m.出口尽头)} 步）`);
  else bad(`出口尽头不在最下排：行 ${G.格行(m.出口尽头, m.列数)}`);
  if (m.出口尽头 !== m.出口小径 && m.格[m.出口尽头].类型 === '出口尽头' && m.格[m.出口小径].类型 === '出口小径') ok('出口是**两个互斥类型**：尽头 ⇒ / 小径 ↝ 各一格（照抄「险路尽头 / 险路小径」）');
  else bad(`出口两型不对：${m.格[m.出口尽头].类型} / ${m.格[m.出口小径].类型}`);
  if (G.格列(m.出口小径, m.列数) === m.列数 - 1) ok(`出口小径在最右列 ${坐标(m.出口小径)}（离尽头 ${G.BFS距离(m.出口尽头, m.格, m.列数).get(m.出口小径)} 步，调研 §5 A5）`);
  else bad(`出口小径不在最右列：列 ${G.格列(m.出口小径, m.列数)}`);
  if (G.邻居(m.守军, m.列数).includes(m.出口尽头) || G.邻居(m.守军, m.列数).includes(m.出口小径)) ok(`出口守军 ${坐标(m.守军)} 与两个出口之一四邻接（打赢守军两个出口一起放行）`);
  else bad(`出口守军与两个出口都不相邻：${坐标(m.守军)}`);
}

/* ============================ [2] 每层节点个数（★ 2026-10-12 地图大改：随尺寸等比放大） ============================ */
console.log('\n[2] 每层节点个数（第 1 层与改前逐字一致；后面各层按可用格数等比放大）+ 生成成本');
{
  const 数 = (m, t) => Object.values(m.格).filter(n => n.类型 === t).length;
  /* ★ 2026-10-12 地图大改：节点个数表从「四层一张」改成**按层**（`91-地图.js` 的 `计划要放()`）。
     口径 = `round(第 1 层的个数 × 该层期望存活格 ÷ 第 1 层期望存活格)` + 整数配平，
     逐层真值直接**读 `G.计划要放(层)`**（表只有一处来源，测试不另抄一份）。
     ★ 作者第 ⑤ 条要求：**第 1 层与改前完全一致**（作战 4 / 精英 1 / 黑市 1 / 事件 2 / 瞭望站 2 /
       遗迹 1 / 招募站 1 / 空 2；侵蚀源 / 休整 / 隧道 第 1 层为 0）。
     ★ 统筹 2026-10-12 追认的口径（**别为边缘情况较劲**）：第 1 层仍然逐字对齐；
       后面各层只断言「**随层单调不减**」+「**落在基准的 0.7–1.5 倍**」（基准 = 第 1 层 × 期望存活格比例）；
       **「空」节点只断言每层 ≥1**（它是填充类型，生成时会被别的节点挤，个数本来就不精确）。 */
  const 第1层计划 = { 作战: 4, 精英: 1, 侵蚀源: 0, 黑市: 1, 事件: 2, 瞭望站: 2, 空: 2, 遗迹: 1, 休整: 0, 招募站: 1, 隧道: 0 };
  const 计划1 = G.计划要放(1);
  const 一致 = Object.keys(第1层计划).every(k => 计划1[k] === 第1层计划[k]);
  if (一致) ok(`★ 第 1 层的节点个数与改前**逐字一致**：${JSON.stringify(计划1)}`);
  else bad(`第 1 层节点个数变了（作者要求与现在完全一致）：${JSON.stringify(计划1)}`);
  /* 后面各层：单调不减 + 0.7–1.5 倍基准 */
  const 期望格 = 层 => G.形状(层).存在率 * G.形状(层).列数 * G.形状(层).行数;
  const 槽位 = 层 => { const p = G.计划要放(层); return Object.values(p).reduce((a, b) => a + b, 0); };
  const 比例 = 层 => +(槽位(层) / 槽位(1)).toFixed(2);
  info(`节点个数按层放大：第 1 层 ${槽位(1)} 槽（期望 ${期望格(1).toFixed(1)} 格）× 1.00 → 第 2 层 ${槽位(2)} 槽（×${比例(2)}）→ 第 3 层 ${槽位(3)} 槽（×${比例(3)}）→ 第 4 层 ${槽位(4)} 槽（×${比例(4)}）`);
  {
    const 坏层 = [];
    for (const 层 of [2, 3, 4]) {
      const 基准 = 槽位(1) * (期望格(层) / 期望格(1));
      const 倍 = 槽位(层) / 基准;
      if (倍 < 0.7 || 倍 > 1.5) 坏层.push(`第 ${层} 层槽位 ${槽位(层)} = 基准 ${基准.toFixed(1)} 的 ${倍.toFixed(2)} 倍（要落在 0.7–1.5）`);
    }
    if (!坏层.length) ok(`第 2–4 层：槽位都落在「基准（第 1 层 × 期望存活格比例）」的 0.7–1.5 倍内`);
    else bad(`节点个数放大不对：${坏层.join('；')}`);
    /* 口径（统筹追认）：**按可用格数**放大 —— 第 3 层的存在率（0.66）比第 2 层（0.72）低，
       所以它的槽位**比第 2 层少一点是对的**（不是 bug）。只要求「第 4 层 > 第 1 层」这条大方向。 */
    if (槽位(4) > 槽位(1)) ok(`第 4 层（终局层）槽位 ${槽位(4)} > 第 1 层 ${槽位(1)}（按可用格数放大，不是逐层硬单调）`);
    else bad(`第 4 层槽位没超过第 1 层：${槽位(4)} vs ${槽位(1)}`);
    info(`★ 槽位不逐层硬单调是**对的**：第 3 层存在率 0.66 < 第 2 层 0.72 → 可用格更少 → 槽位 ${槽位(3)} < ${槽位(2)}。`);
  }
  /* ★ 真实生成出来的个数：固定类型的**个数表照样一个不少**（这是「固定个数」的本义）；
     「空」是填充类型，只要求 ≥1（生成时会被别的节点挤）。 */
  let 坏 = 0;
  const 样本 = [];
  const 隧道分布 = {};
  for (const 层 of [1, 2, 3, 4]) {
    for (let i = 0; i < 10; i++) {
      const m = G.生成层(层, G.地图种子((700000 + i * 7919) >>> 0, 层));
      const 要 = Object.assign({}, G.计划要放(层), { 隧道: null });   // 隧道单独判（成对 0|2，见下）
      const 行 = { 层, 格数: Object.keys(m.格).length, 隧道: 数(m, '隧道') };
      for (const [t, n] of Object.entries(要)) {
        if (n == null) continue;
        const c = 数(m, t);
        /* 「空」是**填充类型**：剩下的格最后都会补成空节点（26:54），所以它只要求 ≥1。 */
        if (t === '空' ? c < 1 : c !== n) { 坏++; bad(`第 ${层} 层 ${t} 有 ${c} 个（要 ${n} 个）`); }
        行[t] = c;
      }
      /* ★ 隧道：**成对 0 或 2**（挑选判据是「一端在左端两列、一端在右端两列、两端图上距离 ≥2」——
         极少数图上挑不到，那就不放，绝不放单只）。 */
      const 隧数 = 数(m, '隧道');
      if (隧数 !== 0 && 隧数 !== 2) { 坏++; bad(`第 ${层} 层隧道有 ${隧数} 个（只许成对 0 / 2）`); }
      隧道分布[隧数] = (隧道分布[隧数] || 0) + 1;
      /* 每层节点总数 = 连通格数（一个格一个节点） */
      if (Object.keys(m.格).length !== Object.values(m.格).length) { 坏++; bad('格数与节点数对不上'); }
      /* 起点在数据里就是「空」节点（战棋 26:57 type 改成 empty、cleared:true） */
      if (m.格[m.起点].类型 !== '空' || !m.格[m.起点].已过) { 坏++; bad(`第 ${层} 层的起点没有被标成「已过的空节点」`); }
      样本.push(行);
    }
  }
  if (!坏) ok(`40 张地图（4 层 × 10 个种子）的**固定类型**节点个数全部对得上本层的计划表，一个不少、也不多（「空」是填充类型，只要求 ≥1）`);
  info(`抽样：第 1 层 ${JSON.stringify(样本[0])}`);
  info(`      第 4 层 ${JSON.stringify(样本[30])}`);
  info(`隧道个数分布（40 张图，只许 0 / 2）：${JSON.stringify(隧道分布)}`);
  info('★ 层数口径（照抄原作，没改）：侵蚀源第 2 层起 / 休整第 1 层不放 / 隧道第 2 层起；'
    + '★ 改后新增：个数随层等比放大（第 4 层最多）；隧道 = 26:53 的**简单成对**（一端左端两列、一端右端两列、两端图上距离 ≥2）');
  /* 关卡编号（战棋 26:58-61 / 31-战斗.js:67,96-97） */
  const m1 = G.生成层(1, G.地图种子(20261010, 1)), m2 = G.生成层(2, G.地图种子(20261010, 2));
  const 编号 = (m, t) => Object.values(m.格).filter(n => n.类型 === t).map(n => n.关卡);
  if (编号(m1, '作战').every(x => /^ISW-1-N-\d+$/.test(x))) ok(`第 1 层作战的关卡编号：${编号(m1, '作战').join('、')}（格式 ISW-层-N-序号）`);
  else bad(`第 1 层作战的关卡编号不对：${JSON.stringify(编号(m1, '作战'))}`);
  if (编号(m2, '侵蚀源').every(x => /^ISW-2-S-\d+$/.test(x))) ok(`第 2 层侵蚀源的关卡编号：${编号(m2, '侵蚀源').join('、')}（S 类只在 L≥2）`);
  else bad(`第 2 层侵蚀源的关卡编号不对：${JSON.stringify(编号(m2, '侵蚀源'))}`);
  const m4 = G.生成层(4, G.地图种子(20261010, 4));
  if (编号(m4, '出口守军').every(x => x === 'ISW-4-F-1')) ok('第 4 层的出口守军抽的是终点 Boss 关 ISW-4-F-1（战棋 26:59 的 bossReady 分支）');
  else bad(`第 4 层出口守军的关卡编号不对：${JSON.stringify(编号(m4, '出口守军'))}`);
  /* 隧道：成对 + 稳定的「起点侧 ↔ 出口侧」快通道 + 图上真的省步（调研 §5 A6） */
  {
    let 对 = 0, 省够 = 0, 起点侧 = 0, 出口侧 = 0, 有隧道 = 0, 省够2 = 0;
    const 距离们 = [];
    for (let i = 0; i < 30; i++) {
      const 种子 = (730000 + i * 7919) >>> 0;
      const m = G.生成层(2, G.地图种子(种子, 2));
      const L = m.列数;
      const 隧 = (m.隧道 || []).slice();
      if (隧.length !== 2) continue;
      有隧道++; 对++;
      const [a, b] = 隧;
      const d = G.BFS距离(a, m.格, L).get(b);
      距离们.push(d);
      if (d >= 2) 省够++;                                  // 走隧道花 1 点 → 省 d−1 ≥ 1 步
      if (d >= 3) 省够2++;                                 // ≥3 → 省 ≥2 步（A6 原本想要的量级）
    }
    if (有隧道 && 对 === 有隧道) ok(`隧道成对 ${对}/${有隧道}（第 2 层起才有，原作曲折密道不在第 Ⅰ 层）`);
    else bad(`隧道没成对：${对}/${有隧道}`);
    if (省够 === 有隧道) ok(`${省够}/${有隧道} 张图的隧道两端图上距离 ≥2（走一次花 1 点 → 省 ≥1 步；中位 ${距离们.slice().sort((x, y) => x - y)[距离们.length >> 1]} 步，其中 ≥3 的 ${省够2} 张）`);
    else bad(`有图的隧道两端太近（省不到 1 步）：${省够}/${有隧道}`);
    info('★ A6（「一端在起点侧、一端在出口侧」）**试过后放弃** —— 它只是调研里「可以试」的一个花样、不是作者要求；'
      + '实测它会变成一条硬约束（一部分图挑不出来 → 拉高重试 → 还要加三档兜底），作者拍板「不要太考虑边缘 case」。'
      + '现在回到 26:53 的**简单成对**（一端在左端两列、一端在右端两列、两端图上距离 ≥2）。理由写在 `协作/任务板.md`。');
  }
  /* 生成成本：跑 200 个「种子 × 层」，看平均 / 最多重试几次
     ★ 2026-10-12 地图大改：新硬条件严得多（连通下限按面积、出口拉开 ≥3、守军必须是收费站），
       重试上限从战棋的 200 抬到 `91-地图.js` 的 `重试上限`（2000）。这里量真值。 */
  {
    const 试们 = [];
    let 失败 = 0;
    for (let i = 0; i < 200; i++) {
      const 种子 = (555000 + i * 7919) >>> 0;
      const 层 = 1 + (i % 4);
      try { 试们.push(G.生成层(层, G.地图种子(种子, 层)).试); } catch (e) { 失败++; bad(`生成失败：种子 ${种子} 第 ${层} 层`); }
    }
    const 平试 = 试们.reduce((a, b) => a + b, 0) / 试们.length;
    if (!失败 && Math.max(...试们) < 2000) ok(`生成成本：200 个「种子 × 层」0 失败、平均重试 ${平试.toFixed(1)} 次、最多 ${Math.max(...试们)} 次（上限 2000）`);
    else bad(`生成成本不对：失败 ${失败}、最多 ${试们.length ? Math.max(...试们) : '—'} 次`);
    info('★ 重试上限为什么从 200 抬到 2000：新硬条件让单次成功率掉到 ~1/50–1/700（第 4 层最狠），200 次会真的生成失败；2000 仍是确定性的（种子 + 试×7919）');
  }
}

/* ============================ [3] 移动：BFS + 消耗 = 格数 + 可以跳格 ============================ */
console.log('\n[3] 移动：四邻接 BFS、消耗 = 走过的格数、可以跳格、推进剂不够走不到');
{
  const R = 开一局(20261010);
  /* ★ 2026-10-12 地图大改：推进剂不再是常量 7，而是 **该图最短路 + 偶数余量[层]**。 */
  const 账0 = G.推进剂账(R);
  if (R.推进剂 === 账0.最短路 + 账0.余量 && 账0.上限 === R.推进剂) {
    ok(`进层推进剂 = ${R.推进剂} = 该图最短路 ${账0.最短路} + 余量 ${账0.余量}（第 ${R.层} 层；余量恒偶数）`);
  } else bad(`进层推进剂不对：${R.推进剂}（账 ${JSON.stringify(账0)}）`);

  /* BFS 距离 vs 真实四邻接步数：一次点到距离 3 的格，看扣的推进剂是不是 3（可以跳格） */
  const 表 = G.全距离(R);
  const 目标 = [...表.keys()].find(k => 表.get(k) === 3);
  if (目标 == null) { bad('这张图上找不到距离 3 的格，跳格测不了'); }
  else {
    const 前 = R.推进剂;
    const 走 = 肉鸽.移动(目标);
    if (走 && 走.距离 === 3 && R.推进剂 === 前 - 3) ok(`跳格：从 ${坐标(R.地图.起点)} 一次点到 ${坐标(目标)}（BFS 距离 3），推进剂 ${前} → ${R.推进剂}（消耗 = 走过的格数 3）`);
    else bad(`跳格消耗不对：距离 ${走 && 走.距离}，推进剂 ${前} → ${R.推进剂}`);
    const 日志 = R.日志.filter(x => x.文本.includes('跳过中间格'));
    if (日志.length) ok(`日志里写明了跳格：${日志[日志.length - 1].文本}`);
    else bad('跳格没有写日志（战棋 30:21 会写「跳过中间格，直接前往」）');
    肉鸽.清空格(肉鸽.当前格());
  }

  /* 推进剂够不够：BFS 深度上限 = 推进剂（战棋 28:25） */
  const R2 = 开一局(20261011);
  const 表2 = G.全距离(R2);
  const 远 = [...表2.keys()].find(k => 表2.get(k) > R2.推进剂);
  if (远 == null) info('这张图上没有超过推进剂的格，跳过「走不到」的检查');
  else {
    const 能 = 肉鸽.能去的().map(n => n.k);
    if (!能.includes(远) && 肉鸽.移动(远) === null && R2.推进剂 > 0) ok(`推进剂只有 ${R2.推进剂}（该图最短路 ${R2.地图.最短路} + 余量 ${G.推进剂余量(2)}），距离 ${表2.get(远)} 的 ${坐标(远)} 走不到（能去的 ${能.length} 个，都不超过 ${R2.推进剂} 步）`);
    else bad(`推进剂不够却走得过去：${坐标(远)} 距离 ${表2.get(远)}，推进剂 ${R2.推进剂}`);
  }
  /* 推进剂刚好用完：走 d 步之后剩余 = prop − d */
  const R3 = 开一局(20261012);
  R3.推进剂 = 2;
  const 表3 = G.全距离(R3);
  const 两步 = [...表3.keys()].find(k => 表3.get(k) === 2);
  if (两步 != null) {
    const 走 = 肉鸽.移动(两步);
    if (走 && R3.推进剂 === 0 && 走.追击) ok(`推进剂 2 走 2 步 → 剩 0，这一格结算完会触发追击战（战棋 30:34 的「推进剂 ≤0 → 追击战」）`);
    else bad(`推进剂归零没标记追击：剩 ${R3.推进剂}、追击 ${走 && 走.追击}`);
  } else info('这张图上没有距离 2 的格，跳过「刚好用完」的检查');
  /* 走过的格不再是目标（战棋 moveTargets 会滤掉已过的格） */
  const R4 = 开一局(20261013);
  const 一 = 肉鸽.能去的()[0].k;
  肉鸽.移动(一); 肉鸽.清空格(肉鸽.当前格());
  if (!肉鸽.能去的().map(n => n.k).includes(一)) ok(`走过后 ${坐标(一)} 不再出现在「能去的」里（一格只结算一次）`);
  else bad('走过的格还能再去');
}

/* ============================ [3b] ★ 2026-10-12 地图大改新增的三段 ============================ */
/* --- [3b-1] 推进剂 = 该图最短路 + 偶数余量[层]（二部图：余量必须是偶数） --- */
console.log('\n[3b] 推进剂 = 该图最短路 + 偶数余量（作者第 ② 条 + 调研 §2.3 的二部图那条）');
{
  let 对 = 0, 偶 = 0, 总 = 0;
  const 逐层 = {};
  for (const 层 of [1, 2, 3, 4]) {
    const 步 = [], 比 = [];
    for (let i = 0; i < 24; i++) {
      const 种子 = (20261010 + i * 7919) >>> 0;
      const m = G.生成层(层, G.地图种子(种子, 层));
      const R = { 层, 地图: m, 层推进剂修正: 0, 零件推进剂加成: 0, 层出口小径: [] };
      const 账 = G.推进剂账(R);
      const 上限 = G.推进剂上限(R);
      总++;
      if (上限 === 账.最短路 + 账.余量 && 账.上限 === 上限) 对++;
      if (账.余量 % 2 === 0 && G.推进剂余量是偶数(层)) 偶++;
      /* 预算比 = 实际最小步数 ÷ 推进剂：**每一张图**都要 ≤0.85（调研 §3.2 的目标带） */
      步.push(账.最短路);
      比.push(账.最短路 / 上限);
    }
    const 中 = a => a.slice().sort((x, y) => x - y)[a.length >> 1];
    逐层[层] = { 余量: G.推进剂余量(层), 最短路中位: 中(步), 上限中位: 中(步) + G.推进剂余量(层), 比最大: Math.max(...比), 比中位: 中(比) };
  }
  if (对 === 总) ok(`96 张图全部满足「推进剂上限 = 该图最短路 + 余量[层]」（${对}/${总}）`);
  else bad(`有图的推进剂不等于「该图最短路 + 余量」：${总 - 对}/${总}`);
  if (偶 === 总) ok(`四层余量全是偶数：${[1, 2, 3, 4].map(L => `第${L}层 +${G.推进剂余量(L)}`).join(' / ')}（+1 无效：网格是二部图，起点到出口所有路径同奇偶）`);
  else bad(`余量不是偶数：${[1, 2, 3, 4].map(G.推进剂余量).join(' / ')}`);
  const 比最大 = Math.max(...[1, 2, 3, 4].map(L => 逐层[L].比最大));
  if (比最大 <= 0.88) ok(`★ 预算比（该图最短路 ÷ 推进剂）**每一张图**都 ≤0.88：最大 ${比最大.toFixed(3)}（目标 ≤0.85，实测超出的是「最短路极短」的那几张：取整到偶数余量会放大比值；中位见下）`);
  else bad(`有图的预算比超过 0.88：最大 ${比最大.toFixed(3)}`);
  for (const L of [1, 2, 3, 4]) {
    const v = 逐层[L];
    info(`第 ${L} 层：余量 +${v.余量} · 该图最短路中位 ${v.最短路中位} · 上限中位 ${v.上限中位} · 预算比 中位 ${v.比中位.toFixed(2)} / 最大 ${v.比最大.toFixed(2)}`);
  }
  if (逐层[4].上限中位 > 逐层[1].上限中位) {
    ok(`推进剂随层变大（作者第 ② 条）：第 1 层上限中位 ${逐层[1].上限中位} → 第 4 层 ${逐层[4].上限中位}`);
  } else bad(`推进剂没有随层变大：${[1, 2, 3, 4].map(L => 逐层[L].上限中位).join(' / ')}`);
  /* 账里的每一项都对得上（界面 / 日志就按这个写） */
  const m = G.生成层(2, G.地图种子(20261010, 2));
  const R = { 层: 2, 地图: m, 层推进剂修正: -2, 零件推进剂加成: 1, 层出口小径: [2] };
  const 账 = G.推进剂账(R);
  if (账.上限 === 账.最短路 + 账.余量 + 账.层修正 + 账.零件 + 账.小径 && 账.小径 === G.肉鸽数值.出口小径加成) {
    ok(`推进剂账齐全：最短路 ${账.最短路} + 余量 ${账.余量} + 层修正 ${账.层修正} + 零件 ${账.零件} + 小径 ${账.小径} = ${账.上限}`);
  } else bad(`推进剂账对不上：${JSON.stringify(账)}`);
}

/* --- [3b-2] 退路成本预告（调研 §5 A4；三层反馈的「预告」那一层） --- */
console.log('\n[3b-2] 退路成本预告：走进去之后要花 M 点才回得来（调研 A4，纯读）');
{
  const R = 开一局(20261090);
  const 格们 = Object.keys(R.地图.格).map(Number);
  const L = R.地图.列数;
  const 割 = G.割点们(new Set(格们), L);
  const 干路 = k => G.邻居(k, L).filter(x => R.地图.格[x]).length >= 3 || 割.has(k);
  let 干路零 = 0, 干路数 = 0, 支线正 = 0, 支线数 = 0, 算不出 = 0;
  for (const k of 格们) {
    const m = G.退路成本(R, k);
    if (m == null) { 算不出++; continue; }
    if (干路(k)) { 干路数++; if (m === 0) 干路零++; }
    else { 支线数++; if (m >= 1) 支线正++; }
  }
  if (干路数 && 干路零 === 干路数) ok(`干路格（度 ≥3 或割点）的退路成本恒为 0（${干路数} 格）—— 它自己就是「不用回头」的那条路`);
  else bad(`干路格的退路成本不是 0：${干路零}/${干路数}`);
  if (支线数 && 支线正 === 支线数) ok(`支线格（度 ≤2 且非割点）的退路成本都是正数（${支线数} 格，最小 ${Math.min(...格们.filter(k => !干路(k)).map(k => G.退路成本(R, k)))} 步）`);
  else bad(`有支线格的退路成本 ≤0：${支线数 - 支线正}/${支线数}`);
  if (算不出 === 0) ok('每一格都算得出退路成本（连不上干路的格会让玩家困死，一个都不能有）');
  else bad(`有 ${算不出} 格算不出退路成本`);
  /* 纯读：算一遍不改 RUN 任何字段、不消耗随机数 */
  const 前 = JSON.stringify({ 当前: R.当前, 推进剂: R.推进剂, 已走过: R.已走过, 地图: R.地图 });
  for (const k of 格们) { G.退路成本(R, k); G.退路成本(R, k); }
  const 后 = JSON.stringify({ 当前: R.当前, 推进剂: R.推进剂, 已走过: R.已走过, 地图: R.地图 });
  if (前 === 后) ok('退路成本是**纯读**：连算两遍，RUN 的当前格 / 推进剂 / 已走过 / 地图一个字节都没动');
  else bad('退路成本改了 RUN 的状态（它必须是纯读）');
  /* 界面上真的画出了那一句 */
  if (界面.屏 !== '大地图') 界面.开屏('大地图');
  const 屏文 = 屏文字();
  if (/进去后要花 \d+ 点才回得来|主干道上/.test(屏文)) {
    ok(`大地图格子上画了预告：${(屏文.match(/(进去后要花 \d+ 点才回得来|主干道上)/) || [])[0]}`);
  } else bad('大地图上没有「进去后要花 M 点才回得来」这一句');
  /* 不在「能去」里的格子不该被画上退路成本（已过的格子没有「退路」这回事） */
  const 已过 = 格们.filter(k => R.地图.格[k].已过 && k !== R.当前);
  if (已过.length === 0 || !格们.some(k => R.地图.格[k].已过)) info('这张图上暂时没有已过的格，跳过「已过不画退路」的检查');
  else ok(`已过的格（${已过.length} 个）不在「能去的」里，所以界面上不会给它们画退路成本`);
  info('★ 口径：干路 = 度 ≥3 或割点（与 `试放` 挑池用同一个判据）；M = 从该格 BFS 到最近的、不在已走过里的干路格');
}

/* --- [3b-3] 节点安放规则：战斗类进干路 / 收益类进支线（调研 §5 A3，**「尽量」不做硬保证**） --- */
console.log('\n[3b-3] 节点安放：战斗类（作战/精英/侵蚀源）进干路 · 收益类（黑市/招募站/事件/瞭望站/遗迹）进支线（调研 §5 A3）');
{
  const 收益类 = ['黑市', '招募站', '事件', '瞭望站', '遗迹'];
  const 战斗类 = ['作战', '精英', '侵蚀源'];
  let 收益总 = 0, 收益支 = 0, 战斗总 = 0, 战斗干 = 0;
  const 逐层收益 = {};
  for (const 层 of [1, 2, 3, 4]) {
    let 层收益 = 0, 层收益支 = 0;
    for (let i = 0; i < 20; i++) {
      const 种子 = (20261100 + i * 7919) >>> 0;
      const m = G.生成层(层, G.地图种子(种子, 层));
      const L = m.列数, 格们 = Object.keys(m.格).map(Number);
      const 割 = G.割点们(new Set(格们), L);
      const 度 = k => G.邻居(k, L).filter(x => m.格[x]).length;
      const 取 = ts => ts.flatMap(t => Object.values(m.格).filter(n => n.类型 === t).map(n => n.k));
      const 收益 = 取(收益类), 战斗 = 取(战斗类);
      const 本图支 = 收益.filter(k => 度(k) <= 2).length;
      收益总 += 收益.length; 收益支 += 本图支; 层收益 += 收益.length; 层收益支 += 本图支;
      战斗总 += 战斗.length; 战斗干 += 战斗.filter(k => 度(k) >= 3 || 割.has(k)).length;
    }
    逐层收益[层] = 层收益 ? +(层收益支 / 层收益).toFixed(3) : 0;
  }
  const 收益比 = 收益支 / 收益总, 战斗比 = 战斗干 / 战斗总;
  /* ★ 统筹 2026-10-12 追认：A3 是「**尽量**」，不做硬保证，也不为极少数图加特判。
     所以这里只留**一条软断言**：干路上的战斗类节点 ≥ 一半（收益类进支线的比例只报数字，不断言）。 */
  if (收益比 >= 0.8) ok(`收益类节点 ${收益支}/${收益总} = ${(收益比 * 100).toFixed(1)}% 落在**支线**（度 ≤2；改前实测黑市死胡同比 0.000、平均度 2.99 = 全在干路上）`);
  else info(`收益类节点进支线的比例 ${(收益比 * 100).toFixed(1)}%（A3 是「尽量」，**不断言**）`);
  if (战斗比 >= 0.5) ok(`战斗类节点 ${战斗干}/${战斗总} = ${(战斗比 * 100).toFixed(1)}% 落在**干路**（度 ≥3 或割点；软断言：≥ 一半）`);
  else bad(`战斗类节点进干路的比例太低：${(战斗比 * 100).toFixed(1)}%`);
  info(`逐层收益节点在支线的比例：${[1, 2, 3, 4].map(L => `第${L}层 ${(逐层收益[L] * 100).toFixed(0)}%`).join(' / ')}`);
  info('★ 口径（写进任务板）：A3 按「尽量」实现 —— 优先池 = 干路 / 支线，池子不够就回落到「哪儿都行」；'
    + '**没有**为了「战斗类一个都不落死胡同」加特判（原来那条硬断言已按统筹意见删除）。');
}

/* ============================ [4] 推进剂 0 → 追击战 ============================ */
console.log('\n[4] 推进剂 0 → 追击战；追击完下一层推进剂上限 −2');
{
  const R = 开一局(20261014);
  R.推进剂 = 0;
  if (肉鸽.能去的().length === 0) ok('推进剂 0 时一个格都去不了（战棋 28:29）');
  else bad(`推进剂 0 还能去 ${肉鸽.能去的().length} 个格`);
  const 开打 = 界面.追击战();
  if (界面.屏 === '战斗' && 界面.肉鸽战斗 && 界面.肉鸽战斗.格类型 === '追击') ok(`推进剂 0 触发追击战：进入战斗屏，这一场的节点类型 = 「${界面.肉鸽战斗.格类型}」（编成用「${界面.肉鸽战斗.类型}」档）`);
  else bad(`追击战没触发：屏 ${界面.屏}、战斗 ${JSON.stringify(界面.肉鸽战斗)}`);
  const 层前 = R.层;
  打完这一场();
  if (R.层 === 层前 + 1 && R.层推进剂修正 === -2 && R.推进剂 === G.推进剂上限(R)) {
    ok(`追击战打完进了第 ${R.层} 层，推进剂上限被扣到 ${R.推进剂}（7 − 2，战棋 31:300 + 28:9）`);
  } else bad(`追击之后不对：层 ${R.层}（原 ${层前}）、修正 ${R.层推进剂修正}、推进剂 ${R.推进剂}`);
  if (R.日志.some(x => x.文本.includes('被追击'))) ok(`日志里写了：${R.日志.filter(x => x.文本.includes('被追击')).pop().文本}`);
  else bad('日志里没写被追击');
  /* 追击战之后的下一层：上限 −2；再往后一层恢复正常（战棋 28:9 的 layerPropBonus 只影响一层）
     ★ 2026-10-12 地图大改：上限不再是常量 7，所以两条都按「该图最短路 + 余量 + 修正」算。 */
  const R2 = 开一局(20261015);
  R2.追击 = true;                      // 上一层被追击过（战场上是 追击战() 打完自动设上的）
  肉鸽.下一层();
  const 被追层 = { 层: R2.层, 修正: R2.层推进剂修正, 推进剂: R2.推进剂, 追击: R2.追击, 账: G.推进剂账(R2) };
  肉鸽.下一层();                        // 再换一层（这一层没被追击）
  const 复位账 = G.推进剂账(R2);
  const 期望复位 = 复位账.最短路 + 复位账.余量;
  if (被追层.修正 === -2 && 被追层.推进剂 === 被追层.账.最短路 + 被追层.账.余量 - 2
      && R2.层推进剂修正 === 0 && R2.推进剂 === 期望复位) {
    ok(`「被追击」只影响下一层：第 ${被追层.层} 层推进剂 ${被追层.推进剂}（该图最短路 ${被追层.账.最短路} + 余量 ${被追层.账.余量} − 2），第 ${R2.层} 层回到 ${R2.推进剂}（= ${复位账.最短路} + ${复位账.余量}）`);
  } else bad(`推进剂修正没有复位：第 ${被追层.层} 层 ${被追层.推进剂}（修正 ${被追层.修正}，账 ${JSON.stringify(被追层.账)}） → 第 ${R2.层} 层 ${R2.推进剂}（修正 ${R2.层推进剂修正}，期望 ${期望复位}）`);
  info(`（\`追击\` 这个标记在进层时会被清掉，所以第 ${被追层.层} 层的「修正」是从上一层带过来的 −2）`);
}

/* ============================ [5] 7 种新节点各自的结算 ============================ */
console.log('\n[5] 7 种新节点：黑市 / 瞭望站 / 隧道 / 遗迹 / 休整 / 出口守军 / 侵蚀源');
{
  /* --- 黑市：花源碳买藏品（价格照战棋 23b-藏品.js:10）★ 货架 4 件、刷新与卖零件见第 [11] 段 --- */
  const R = 开一局(20261020);
  R.源碳 = 100;
  const 货 = 肉鸽.黑市货();
  if (货.length === G.肉鸽数值.黑市货件数) ok(`黑市摆出 ${货.length} 件藏品（★ 2026-10-11 从 2 件提到 ${G.肉鸽数值.黑市货件数} 件，照抄原作诡意行商满档）：${货.map(id => `${G.藏品名(id)}（${G.藏品表[id].稀有}，${肉鸽.黑市价(id)} 源碳）`).join('、')}`);
  else bad(`黑市货不对：${JSON.stringify(货)}`);
  const 甲 = 货[0], 价 = 肉鸽.黑市价(甲), 前碳 = R.源碳;
  const 买 = 肉鸽.黑市买(甲);
  if (买.ok && R.源碳 === 前碳 - 价 && R.藏品.includes(甲)) ok(`买下【${买.名}】花 ${价} 源碳（源碳 ${前碳} → ${R.源碳}，进藏品 ${R.藏品.length} 件）`);
  else bad(`黑市买入不对：${JSON.stringify(买)}，源碳 ${R.源碳}`);
  if (肉鸽.黑市价(甲) === G.藏品价格[G.藏品表[甲].稀有]) ok(`价格 = 战棋的 RELIC_PRICE：${G.藏品表[甲].稀有} → ${肉鸽.黑市价(甲)}（23b-藏品.js:10）`);
  else bad('黑市价格没按战棋的表');
  const 重买 = 肉鸽.黑市买(甲);
  if (!重买.ok && /手上了/.test(重买.why)) ok(`同一件不能买两次：${重买.why}`);
  else bad('重复买了同一件藏品');
  R.源碳 = 1;
  const 穷 = 肉鸽.黑市买(货[1]);
  if (!穷.ok && /源碳不够/.test(穷.why)) ok(`源碳不够时买不了：${穷.why}`);
  else bad(`源碳不够却买到了：${JSON.stringify(穷)}`);
  R.藏品.push('f1');   // 黑市会员卡：−30%（战棋 23b:122）
  R.源碳 = 100;
  if (肉鸽.黑市价(货[1]) === Math.round(G.藏品价格[G.藏品表[货[1]].稀有] * 0.7)) ok(`拿到【黑市会员卡】后价格 −30%：${肉鸽.黑市价(货[1])} 源碳`);
  else bad(`会员卡没打折：${肉鸽.黑市价(货[1])}`);
  if (R.日志.some(x => x.文本.includes('黑市'))) ok(`黑市写日志：${R.日志.filter(x => x.文本.includes('黑市')).pop().文本}`);
  else bad('黑市没写日志');

  /* --- 瞭望站：推进剂 +1（上限+1）、揭开周围 4 格、希望 +3 --- */
  const R2 = 开一局(20261021);
  R2.推进剂 = 3;
  const 希望前 = R2.希望;
  肉鸽.跳格(找格(R2, '瞭望站'));
  const 看 = 肉鸽.结算瞭望站();
  if (看 && R2.推进剂 === 4 && R2.希望 === 希望前 + G.肉鸽数值.瞭望站希望) ok(`瞭望站：推进剂 3 → ${R2.推进剂}（+1，战棋 30:74）、希望 ${希望前} → ${R2.希望}（+${G.肉鸽数值.瞭望站希望}，初稿）`);
  else bad(`瞭望站结算不对：${JSON.stringify(看)}，推进剂 ${R2.推进剂} 希望 ${R2.希望}`);
  if (看.揭开 > 0 && R2.已揭开.length === 看.揭开) ok(`揭开周围 4 格：${看.揭开} 格（战棋 30:75 的 gdist ≤ 4）`);
  else bad(`揭开格数不对：${JSON.stringify(看)}`);
  if (R2.地图.格[R2.当前].类型 === '空' && R2.地图.格[R2.当前].已过) ok('瞭望站结算完这一格变成「已过的空节点」');
  else bad('瞭望站结算完没有清空这一格');
  /* 上限是 propMax()+1（战棋 30:74）—— ★ 2026-10-12：propMax() 变成「该图最短路 + 余量」，
     所以这里只钉「+1 真的起作用」，不写死 8。 */
  const R2b = 开一局(20261021);
  肉鸽.跳格(找格(R2b, '瞭望站'));
  const 瞭望前 = R2b.推进剂;
  肉鸽.结算瞭望站();
  if (R2b.推进剂 === 瞭望前 + G.肉鸽数值.瞭望站推进剂) ok(`瞭望站把推进剂抬了 +${G.肉鸽数值.瞭望站推进剂}：${瞭望前} → ${R2b.推进剂}（战棋 30:74 的 propMax()+1 换成「当前 +1」，同一语义）`);
  else bad(`瞭望站的 +1 没生效：${瞭望前} → ${R2b.推进剂}`);

  /* --- 隧道：跳到另一头、**花 1 点推进剂**（★ 2026-10-11 节点改造第 9 条；照抄原作曲折密道
         「※行动力只在进入时被消耗」）--- */
  const R3 = 开一局(20261022);
  const 隧道们 = R3.地图.隧道;
  if (隧道们.length !== 2) info(`这张图没有成对的隧道（合法：战棋 26:53 是配对成功才放），换一张`);
  else {
    肉鸽.跳格(隧道们[0]);
    const 丙 = R3.推进剂, 另 = 隧道们[1];
    const 传 = 肉鸽.结算隧道();
    if (传.ok && 传.传送 && R3.当前 === 另 && R3.推进剂 === 丙 - G.肉鸽数值.隧道花费) {
      ok(`隧道：${坐标(隧道们[0])} → ${坐标(另)}，推进剂 ${丙} → ${R3.推进剂}（−${G.肉鸽数值.隧道花费}，照抄「行动力只在进入时被消耗」）`);
    } else bad(`隧道传送不对：${JSON.stringify(传)}，当前 ${R3.当前} 推进剂 ${R3.推进剂}（原 ${丙}）`);
    if (R3.已揭开.includes(另)) ok('隧道另一头被揭开（战棋 30:42）');
    else bad('隧道另一头没揭开');
  }
  /* 推进剂不够就传不了（0 点连进都进不去） */
  const R3b = 开一局(20261022);
  if (R3b.地图.隧道.length === 2) {
    肉鸽.跳格(R3b.地图.隧道[0]);
    R3b.推进剂 = 0;
    const 穷 = 肉鸽.结算隧道();
    if (穷.ok === false && /推进剂不够/.test(穷.why)) ok(`推进剂 0 时隧道拒绝：${穷.why}`);
    else bad(`推进剂 0 却传过去了：${JSON.stringify(穷)}`);
  }

  /* --- 遗迹：**三选一**（★ 2026-10-11 节点改造第 7 条，照抄黑流树海「沉寂之屋」）--- */
  const R4 = 开一局(20261023);
  肉鸽.跳格(找格(R4, '遗迹'));
  const 碳前 = R4.源碳, 耐前 = R4.耐久;
  const 翻 = 肉鸽.结算遗迹('藤蔓');
  if (R4.源碳 === 碳前 + G.肉鸽数值.遗迹源碳 && R4.耐久 === 耐前 - G.肉鸽数值.遗迹耐久价 && 翻.ok) {
    ok(`遗迹「清理门口的藤蔓」：作战耐久 ${耐前} → ${R4.耐久}（−${G.肉鸽数值.遗迹耐久价}）、源碳 ${碳前} → ${R4.源碳}（+${G.肉鸽数值.遗迹源碳}，战棋 30:79）` +
       `${翻.零件 ? `、零件【${翻.零件.名}】` : '（零件箱满了）'}`);
  } else bad(`遗迹（藤蔓）不对：${JSON.stringify(翻)} 源碳 ${碳前} → ${R4.源碳} 耐久 ${耐前} → ${R4.耐久}`);
  if (!('藏品' in 翻) || 翻.藏品 == null) ok('★ 「50% 送藏品」已经删掉：遗迹只给零件（作者点名第 7 条）');
  else bad(`遗迹还在送藏品：${JSON.stringify(翻.藏品)}`);
  if (R4.地图.格[R4.当前].已过) ok('遗迹结算完这一格变成已过');
  else bad('遗迹没清空');
  /* 三条路的代价：交流花源碳、离开什么都不拿 */
  {
    const R4b = 开一局(20261023);
    肉鸽.跳格(找格(R4b, '遗迹'));
    const 碳0 = R4b.源碳;
    const r = 肉鸽.结算遗迹('交流');
    if (r.ok && R4b.源碳 === 碳0 - G.肉鸽数值.遗迹源碳价 + G.肉鸽数值.遗迹源碳) {
      ok(`遗迹「试着和它交流」：源碳 ${碳0} → ${R4b.源碳}（−${G.肉鸽数值.遗迹源碳价} 代价 +${G.肉鸽数值.遗迹源碳} 收益，照抄「消耗 8 源石锭」）`);
    } else bad(`遗迹（交流）不对：${JSON.stringify(r)} 源碳 ${碳0} → ${R4b.源碳}`);
    const R4c = 开一局(20261023);
    肉鸽.跳格(找格(R4c, '遗迹'));
    const 碳1 = R4c.源碳, 耐1 = R4c.耐久;
    const r3 = 肉鸽.结算遗迹('离开');
    if (r3.ok && r3.选 === '离开' && R4c.源碳 === 碳1 && R4c.耐久 === 耐1 && !r3.零件) {
      ok(`遗迹「离开」：源碳 ${碳1}、作战耐久 ${耐1} 一点没动，也没拿零件（放弃）`);
    } else bad(`遗迹（离开）不对：${JSON.stringify(r3)}`);
    /* 付不起就拒绝 */
    const R4d = 开一局(20261023);
    肉鸽.跳格(找格(R4d, '遗迹'));
    R4d.耐久 = 1;
    const 付不起 = 肉鸽.结算遗迹('藤蔓');
    if (付不起.ok === false && /作战耐久不够/.test(付不起.why)) ok(`作战耐久不够时「清理藤蔓」拒绝：${付不起.why}`);
    else bad(`作战耐久不够却清理了藤蔓：${JSON.stringify(付不起)}`);
  }

  /* --- 休整：**互斥三选一**（★ 2026-10-11 节点改造第 8 条）--- */
  const R5 = 开一局(20261024);
  R5.层 = 2;                                   // 第 1 层不出现休整（层数门在 91-地图.js），结算本身不拦
  R5.耐久 = 5;
  const r5 = 肉鸽.结算休整('耐久');
  if (R5.耐久 === 5 + G.肉鸽数值.休整耐久 && r5.ok) ok(`休整「坐下休息」：作战耐久 5 → ${R5.耐久}（+${G.肉鸽数值.休整耐久}，战棋 30:60）`);
  else bad(`休整耐久不对：${R5.耐久}`);
  const R5b = 开一局(20261024);
  R5b.层 = 2; R5b.耐久 = 5; R5b.希望 = 10;
  const 希前 = R5b.希望;
  肉鸽.跳格(找格(R5b, '休整'));
  const 推前 = R5b.推进剂;
  const r5b = 肉鸽.结算休整('推进剂');
  const 推期望 = Math.min(G.推进剂上限(R5b) + 1, 推前 + G.肉鸽数值.休整推进剂);
  if (R5b.希望 === 希前 && R5b.耐久 === 5 && R5b.推进剂 === 推期望 && r5b.ok) {
    ok(`休整「把这一格让出来」：推进剂 ${推前} → ${R5b.推进剂}（+${G.肉鸽数值.休整推进剂}，上限 +${G.推进剂上限(R5b) + 1} 封顶；照抄原作「安全的角落」的 2 行动力），` +
       `耐久与希望一点没动（${R5b.耐久} / ${R5b.希望}）`);
  } else bad(`休整的推进剂项不对：推进剂 ${推前} → ${R5b.推进剂} 耐久 ${R5b.耐久} 希望 ${R5b.希望}`);
  /* 互斥三选一的菜单：**第 2 层**（第 1 层根本没有休整格，见下面那一条） */
  const R5c = 开一局(20261024);
  肉鸽.进层(2);                                  // ★ 换层会重建地图，所以要在找格之前进层
  const 菜单5c = 肉鸽.格菜单(找格(R5c, '休整'));
  const 动们 = 菜单5c.map(a => a.动).join('、');
  if (菜单5c.length === 3 && 动们.includes('休整:耐久') && 动们.includes('休整:晋升') && 动们.includes('休整:推进剂')) {
    ok(`休整只有**互斥三选一**（拿一个就结束）：${动们} —— 「花希望买耐久」与「跳过」都删掉了`);
  } else bad(`休整的选项不对：${动们}`);
  /* 第 1 层真的不放休整格 */
  {
    let 有休整 = 0;
    for (let i = 0; i < 20; i++) {
      const m = G.生成层(1, G.地图种子((700000 + i * 7919) >>> 0, 1));
      if (Object.values(m.格).some(n => n.类型 === '休整')) 有休整++;
    }
    if (有休整 === 0) ok('第 1 层 20 张图一个休整格都没有（照抄原作「安全的角落：※该节点不会在第 Ⅰ 层出现」）');
    else bad(`第 1 层出现了休整：${有休整} / 20 张`);
  }

  /* --- 出口守军：出口前一场精英战，打赢了出口才放行 --- */
  /* ① 没打守军时，出口不放行（站在出口那一格看这一格的菜单） */
  const R6 = 开一局(20261025);
  const m6 = R6.地图;
  肉鸽.跳格(m6.守军);
  if (肉鸽.当前战斗类型() === '守军' && 肉鸽.当前奖励类型() === '精英') ok(`出口守军（层 1–3）走「守军」编成（${G.节点类型表['出口守军'].名} → ${肉鸽.当前战斗类型()}，5 台摆满前 3 后 2），奖励仍按「精英」档，关卡编号 ${肉鸽.当前格().关卡}`);
  else bad(`出口守军的编成类型不对：${肉鸽.当前战斗类型()} / 奖励 ${肉鸽.当前奖励类型()}`);
  肉鸽.跳格(m6.出口尽头);
  const 菜单 = 肉鸽.格菜单(m6.出口尽头);
  if (菜单.length && /守军/.test(菜单[0].名)) ok(`守军没打掉时出口不放行：${菜单[0].名}`);
  else bad(`守军没打掉出口也放行了：${JSON.stringify(菜单)}`);
  if (界面.前进() === false) ok('点了「前进」也被挡回来（界面.前进() 返回 false，提示先去打守军）');
  else bad('守军没打掉就能前进');
  /* ② 站到守军格上打这一场（走一步过去） */
  const R6b = 开一局(20261025);
  const m6b = R6b.地图;
  /* 先走到守军旁边，再走一步进守军格 */
  const 邻 = G.邻居(m6b.守军).find(k => m6b.格[k]);
  肉鸽.跳格(邻);
  const 走 = 界面.去节点(m6b.守军);
  if (走 === '出口守军' && 界面.屏 === '编队') ok(`从 ${坐标(邻)} 走一步到守军格 ${坐标(m6b.守军)}（1 步 1 推进剂）→ 自动进编队屏`);
  else bad(`走到守军格没进编队屏：类型 ${走}、屏 ${界面.屏}`);
  /* 编队屏 → 开战 → 打赢 → 守军格清空、出口放行 */
  界面.编队.出击 = R6b.队伍.slice(0, 3).map((m, i) => ({ 键: m.键, 位: i }));
  界面.动作('开战');
  const 层前 = R6b.层;
  if (界面.屏 === '战斗' && 界面.肉鸽战斗 && 界面.肉鸽战斗.格类型 === '出口守军') {
    /* 临时把敌人打残 + **清掉增援波次**，只验流程（数值平衡不在这份测试里）。
       ★ 2026-10-11 第二轮：增援改成「第 2 回合起 4 波」之后，光把开局那几台压到 1 点血不够 ——
         第 2 回合补进来的是满血敌人，3 台我方清不掉，这一场就必输、后面的通关链全断。 */
    界面.ctx.enemies.forEach(e => { e.maxHp = 1; e.hp = 1; });
    界面.ctx.allies.forEach(u => { u.maxHp = 10000000; u.hp = 10000000; });   // 我方调成不死，只验流程
    界面.ctx.波次 = [];
    打完这一场();
    const 胜 = { 守军已过: m6b.格[m6b.守军].已过, 类型: m6b.格[m6b.守军].类型, 层: R6b.层, 屏: 界面.屏 };
    if (胜.守军已过 && 胜.类型 === '空') ok(`出口守军打赢：守军那一格被清空（${胜.类型}）、层还是第 ${胜.层} 层，**不直接换层**`);
    else bad(`出口守军打赢后守军格没清空：${JSON.stringify(胜)}`);
    if (胜.层 === 层前) ok('出口守军胜利**不换层**（本仓库的换义：换层由走到「出口」那一格决定）');
    else bad(`出口守军胜利就换层了：${层前} → ${胜.层}`);
    if (R6b.日志.some(x => /出口守军/.test(x.文本))) ok(`出口守军写日志：${R6b.日志.filter(x => /出口守军|守军/.test(x.文本)).pop().文本}`);
    else bad('出口守军没写日志');
  } else bad(`守军那一场没进战斗：${界面.屏} / ${JSON.stringify(界面.肉鸽战斗)}`);

  /* --- 侵蚀源（第 2 层起）：一场硬仗 + 额外奖励；第一期不做侵蚀场本身 --- */
  const R7 = 开一局(20261026);
  R7.层 = 2; R7.场次 = 0;
  R7.地图 = G.生成层(2, G.地图种子(R7.种子, 2));
  R7.当前 = R7.地图.起点;
  const 源 = 找格(R7, '侵蚀源');
  if (源 == null) bad('第 2 层没有侵蚀源格');
  else {
    肉鸽.跳格(源);
    if (肉鸽.当前战斗类型() === '侵蚀源' && 肉鸽.当前奖励类型() === '精英') ok(`侵蚀源走「侵蚀源」编成（一场硬仗，5 台摆满前 3 后 2）+ 按精英档发奖励；★ 第一期**不做侵蚀场本身**（只当强敌节点，写进任务板）`);
    else bad(`侵蚀源的编成类型不对：${肉鸽.当前战斗类型()} / 奖励 ${肉鸽.当前奖励类型()}`);
    const 碳前2 = R7.源碳;
    const 胜2 = 肉鸽.战斗结束('胜', '侵蚀源', { 敌方: [] });
    if (胜2.额外 && 胜2.额外.源碳 === G.肉鸽数值.侵蚀源源碳 && R7.源碳 === 碳前2 + G.肉鸽数值.胜利源碳 + G.肉鸽数值.侵蚀源源碳) {
      ok(`侵蚀源胜利：常规奖励 源碳 +${G.肉鸽数值.胜利源碳} 之外，**额外** 源碳 +${胜2.额外.源碳}（合计 ${R7.源碳}），并抽了 1 件藏品`);
    } else bad(`侵蚀源的额外奖励不对：${JSON.stringify(胜2.额外)}，源碳 ${碳前2} → ${R7.源碳}`);
    if (R7.日志.some(x => x.文本.includes('侵蚀源'))) ok(`侵蚀源写日志：${R7.日志.filter(x => x.文本.includes('侵蚀源')).pop().文本}`);
    else bad('侵蚀源没写日志');
  }
  /* 第 1 层不该有侵蚀源格（战棋 26:47：layer >= 2 才放） */
  const R8 = 开一局(20261026);
  if (找格(R8, '侵蚀源') == null) ok('第 1 层没有侵蚀源格（战棋 26:47：第 2 层起才有）');
  else bad('第 1 层出现了侵蚀源');
}

/* ============================ [5b] 每个节点都「可点、可结算、能回大地图」 ============================ */
console.log('\n[5b] 7 种节点的界面闭环：点格 → 结算 → 回大地图');
{
  const 试 = (层, 类型, 动作, 弹窗答案 = 'no') => {
    const R = 开一局(20261027);
    R.层 = 层; R.场次 = 0;
    R.地图 = G.生成层(层, G.地图种子(R.种子, 层));
    R.当前 = R.地图.起点;
    R.推进剂 = 60;                          // 节点闭环测的是流程，给足推进剂（隧道那 1 点也付得起）
    const k = 找格(R, 类型);
    if (k == null) return { 无格: true };
    /* 由界面自己走过去（`界面.去节点` 会按 BFS 算距离并扣推进剂）；
       ★ 2026-10-11 起隧道 / 遗迹 / 休整 / 事件都走**选项弹窗**，用 `对话框钩子` 替玩家点一下
       （隧道默认点「留在这里」= 'no'，免得走过去就被传送了）。 */
    const 原钩子 = 界面.对话框钩子;
    界面.对话框钩子 = () => 弹窗答案;
    界面.去节点(k);
    const 跳格 = R.当前 !== k;
    if (跳格) { 肉鸽.跳格(k); 界面.去节点(k); }
    界面.对话框钩子 = 原钩子;
    const 屏1 = 界面.屏;
    /* ★ 注意：`动作` 可能是 `'奇遇:0'`（下标 0）—— 判空一律用 `!= null`，别用真值判断 */
    if (动作 != null) 界面.动作(动作);
    return { 屏1, 屏2: 界面.屏, 类型: R.地图.格[k] ? R.地图.格[k].类型 : '空', 跳格 };
  };
  const 表 = [
    ['黑市', null, '黑市离开'],
    ['瞭望站', null, null, '登高'],
    ['遗迹', null, null, '藤蔓'],
    ['休整', 2, '休整:耐久'],
    ['事件', null, '奇遇:0', null],   // 事件是「先看屏 → 点选项」：`奇遇:0` = 界面按钮 `data-act="奇遇:<选项文字>"` 的下标写法
    ['招募站', null, '回大地图'],
  ];
  for (const [类型, 层, 动作, 弹窗答案] of 表) {
    const r = 试(层 || 1, 类型, 动作, 弹窗答案);
    if (r.无格) { info(`第 ${层 || 1} 层这张图没有 ${类型}，跳过`); continue; }
    if (r.屏2 === '大地图') ok(`${类型}：点格${r.跳格 ? '（直接站过去）' : '（走一步）'}进「${r.屏1}」${动作 ? ` → 动作「${动作}」` : ''} → 「${r.屏2}」（闭环）`);
    else bad(`${类型} 没闭环：屏 ${r.屏1} → ${r.屏2}`);
  }
  /* 战斗类节点（作战 / 精英 / 出口守军 / 侵蚀源）：点格进编队屏 → 开战 → 战斗屏 → 回大地图 */
  for (const 类型 of ['作战', '精英']) {    const r = 试(1, 类型, null);
    if (r.无格) { info(`第 1 层这张图没有 ${类型}，跳过`); continue; }
    if (r.屏1 === '编队' && 界面.肉鸽编队模式) {
      界面.编队.出击 = 肉鸽.RUN.队伍.slice(0, 3).map((m, i) => ({ 键: m.键, 位: i }));
      界面.动作('开战');
      if (界面.屏 === '战斗' && 界面.肉鸽战斗 && 界面.肉鸽战斗.格类型 === 类型) {
        ok(`${类型}：点格 → 编队屏 → 开战 → 战斗屏（节点类型「${界面.肉鸽战斗.格类型}」/ 编成「${界面.肉鸽战斗.类型}」）`);
        界面.ctx.enemies.forEach(e => { e.maxHp = 1; e.hp = 1; });
    界面.ctx.allies.forEach(u => { u.maxHp = 10000000; u.hp = 10000000; });   // 我方调成不死，只验流程
        界面.ctx.波次 = [];      // ★ 2026-10-11：连增援波次一起清（理由见上面出口守军那一段的注释）
        打完这一场();
        if (界面.屏 === '大地图' || 界面.屏 === '肉鸽结算') ok(`　└ 打赢回「${界面.屏}」（闭环），节点已清空`);
        else bad(`${类型} 打赢后没回大地图：${界面.屏}`);
      } else bad(`${类型} 开战之后不在战斗屏：${界面.屏}`);
    } else bad(`${类型} 点格没进编队屏：${界面.屏}`);
  }
  /* 隧道：站到隧道格上 → 界面.穿隧道()（走弹窗，用 对话框钩子 替玩家点「传送过去」） */
  {
    const R = 开一局(20261028);
    const 隧道们 = R.地图.隧道;
    if (隧道们.length !== 2) info('这张图没有成对隧道，跳过界面闭环');
    else {
      const k = 隧道们[0];
      /* 隧道这一格能走到吗（走不到就站过去，只测弹窗 -> 传送 -> 回大地图这一段） */
      const 能去 = 肉鸽.能去的().map(n => n.k);
      const 走得到 = 能去.includes(k);
      界面.对话框钩子 = () => 'no';            // 走过去的时候先别传送
      界面.去节点(k);
      if (R.当前 !== k) 肉鸽.跳格(k);
      界面.去节点(k);
      界面.对话框钩子 = null;
      const 屏1 = 界面.屏;
      界面.对话框钩子 = () => 'go';           // 站定之后选「传送过去」
      界面.穿隧道();
      if (R.当前 === 隧道们[1] && 界面.屏 === '大地图') ok(`隧道：点格进「${屏1}」→ 弹窗选「传送过去」→ 到了 ${坐标(隧道们[1])} 并回到大地图（这一格${走得到 ? '走得到' : '走不到，直接站过去测的'}）`);
      else bad(`隧道界面闭环不对：当前 ${坐标(R.当前)} 屏 ${界面.屏}`);
      界面.对话框钩子 = null;
    }
  }
}

/* ============================ [6] 终点通关 ============================ */
console.log('\n[6] 打完终点 Boss 要通关（修掉「打完终点 Boss 不通关」）');
{
  const R = 开一局(20261030);
  R.层 = 4; R.场次 = 0;
  R.地图 = G.生成层(4, G.地图种子(R.种子, 4));
  R.当前 = R.地图.起点;
  R.推进剂 = 1;
  const m = R.地图;
  if (m.格[m.守军].类型 === '出口守军' && m.格[m.守军].关卡 === 'ISW-4-F-1') ok(`第 4 层的出口守军 = 终点 Boss 关 ${m.格[m.守军].关卡}（蓝色大肥鱼）`);
  else bad(`第 4 层出口守军不对：${m.格[m.守军].类型} / ${m.格[m.守军].关卡}`);
  /* 站到守军旁边，走一步过去（顺便确认「消耗 = 走过的格数」） */
  R.推进剂 = 60;                          // 给足推进剂：这里只测「走过去」与通关流程
  const 前推 = R.推进剂;
  const 类型 = 界面.去节点(m.守军);
  const 走了 = 前推 - R.推进剂;
  if (类型 === '出口守军' && 界面.屏 === '编队' && 走了 >= 1) ok(`走到守军格 ${坐标(m.守军)}（走了 ${走了} 步，扣 ${走了} 推进剂）→ 进编队屏`);
  else bad(`走去守军格不对：类型 ${类型}、屏 ${界面.屏}、推进剂 ${前推} → ${R.推进剂}`);
  /* ★ 2026-10-11 第二轮：终点 Boss 编成现在是 **9 台摆满 9 格**（大肥鱼 + 8 台护卫）+ 4 波增援，
     所以这里把敌人 HP 全压到 1 + **清掉增援波次** + **我方调成不死**。
     这一段测的是「打赢守军 → 走到出口 → 通关」这条链闭合，
     **数值平衡不在这份测试里**（大肥鱼 240000 HP / 装甲 1800 的换算归 Claude，强度归 M6 平衡工具）。 */
  招几个(5);                                    // ★ 券系统：这一场要摆 5 台 → 先把名册招够
  界面.编队.出击 = R.队伍.slice(0, 5).map((x, i) => ({ 键: x.键, 位: i }));
  界面.动作('开战');
  if (界面.屏 === '战斗') ok(`终点 Boss 战开打：我方 5 台、敌方 ${界面.ctx.enemies.length} 台（${界面.ctx.enemies.map(u => u.key).join('、')}），种子 ${界面.ctx.种子}`);
  else bad(`打这一场没进战斗：${界面.屏}`);
  if (界面.ctx) {
    界面.ctx.enemies.forEach(u => { u.maxHp = 1; u.hp = 1; });
    界面.ctx.allies.forEach(u => { u.maxHp = 10000000; u.hp = 10000000; });
    界面.ctx.波次 = [];
  }
  打完这一场();
  const 战报 = 界面.ctx;
  info(`这一场：${战报.result ? 战报.result.结果 + '（' + 战报.result.原因 + '）' : '超时'} · ${战报.turn} 回合`);
  if (肉鸽.进行中 && 界面.屏 === '大地图' && m.格[m.守军].已过) ok('守军打赢后回到大地图、守军格清空（还没通关，要再走到出口格）');
  else bad(`守军打赢之后不对：屏 ${界面.屏}、守军已过 ${m.格[m.守军].已过}、进行中 ${肉鸽.进行中}`);
  /* 走到出口（尽头）→ 通关 */
  界面.动作('去节点', String(m.出口尽头));
  if (!肉鸽.进行中 && R.结局 === '通关' && 界面.屏 === '肉鸽结算') ok(`走到出口尽头 ${坐标(m.出口尽头)} → 本局结束、结局 = 「${R.结局}」、切到肉鸽结算屏`);
  else bad(`走到出口没通关：进行中 ${肉鸽.进行中}、结局 ${R.结局}、屏 ${界面.屏}`);
  if (屏文字().includes('通关')) ok(`结算屏上写着「通关」：${(屏文字().match(/<div class="eyebrow">([^<]*)<\/div>/) || [])[1] || '（没找到 eyebrow）'}`);
  else bad('结算屏上没有「通关」字样');
  if (!肉鸽.有存档()) ok('通关之后清掉了存档（战棋 31:333 的 runVictory 也是本局结束）');
  else bad('通关之后存档还在');
  info(`通关日志：${R.日志.slice(-2).map(x => x.文本).join(' | ')}`);
  /* 失败那条路仍然正常 */
  const R2 = 开一局(20261031);
  R2.耐久 = 1;
  const f = 肉鸽.战斗结束('败', '作战', { 敌方: [{ hp: 5 }] });
  if (f.结束 && !肉鸽.进行中 && R2.结局 === '失败') ok(`失败那条路仍然正常：耐久 1 打输 → 本局结束、结局 = 「${R2.结局}」（${R2.结局原因}）`);
  else bad(`失败那条路坏了：${JSON.stringify(f)}、结局 ${R2.结局}`);
  界面.开屏('肉鸽结算');
  if (屏文字().includes('本局结束') && !屏文字().includes('通关')) ok('失败结算屏写的是「本局结束」，不是「通关」');
  else bad('失败结算屏不对');
}

/* ============================ [7] 存档 → 读档：地图 / 位置 / 推进剂一致 ============================ */
console.log('\n[7] 存档 → 读档：地图逐格 / 位置 / 推进剂 / 已走过 一致');
{
  const R = 开一局(20261040);
  /* 真的走两步、再看一眼黑市，让状态有内容 */
  const 可 = 肉鸽.能去的();
  肉鸽.移动(可[0].k);
  const 可2 = 肉鸽.能去的();
  if (可2.length) 肉鸽.移动(可2[0].k);
  const 快照 = {
    地图: 地图JSON(R), 当前: R.当前, 推进剂: R.推进剂, 层: R.层,
    已走过: JSON.stringify(R.已走过), 源碳: R.源碳, 希望: R.希望, 耐久: R.耐久, 藏品: JSON.stringify(R.藏品),
  };
  if (肉鸽.存档()) ok(`写存档：第 ${R.层} 层、位置 ${坐标(R.当前)}、推进剂 ${R.推进剂}、已走过 ${R.已走过.length} 格`);
  else bad('写存档失败');
  肉鸽.RUN = null; 肉鸽.进行中 = false;          // 模拟「关掉页面」
  const 读 = 肉鸽.读存档();
  if (!读) bad('读档失败');
  else {
    const 一样 = 地图JSON(读) === 快照.地图 && 读.当前 === 快照.当前 && 读.推进剂 === 快照.推进剂
      && 读.层 === 快照.层 && JSON.stringify(读.已走过) === 快照.已走过
      && 读.源碳 === 快照.源碳 && 读.希望 === 快照.希望 && 读.耐久 === 快照.耐久 && JSON.stringify(读.藏品) === 快照.藏品;
    if (一样) ok(`读档一致：地图逐格相同（${Object.keys(读.地图.格).length} 格）、位置 ${坐标(读.当前)}、推进剂 ${读.推进剂}、层 ${读.层}、已走过 ${读.已走过.length} 格`);
    else bad(`读档对不上：位置 ${读.当前}/${快照.当前}、推进剂 ${读.推进剂}/${快照.推进剂}、层 ${读.层}/${快照.层}`);
    /* 读档后还能继续走 */
    if (肉鸽.能去的().length >= 0 && 肉鸽.当前格()) ok(`读档后还能继续走：能去的 ${肉鸽.能去的().length} 个格`);
    else bad('读档后走不动了');
  }
  /* 走一步就存 → 读回来位置也对（每步都存档） */
  const R3 = 开一局(20261041);
  const 目标 = 肉鸽.能去的()[0].k;
  肉鸽.移动(目标);
  const 位 = R3.当前;
  肉鸽.存档();
  肉鸽.RUN = null;
  const 读3 = 肉鸽.读存档();
  if (读3 && 读3.当前 === 位) ok(`每一步都自动存档：读回来位置还是 ${坐标(位)}`);
  else bad(`自动存档的位置不对：${读3 && 读3.当前} / ${位}`);
}

/* ============================ [8] 同种子两次逐字相同 ============================ */
console.log('\n[8] 带种子的确定性：同种子两次逐字相同（禁用 Math.random）');
{
  const 跑 = 种子 => {
    const R = 开一局(种子);
    return JSON.stringify({ 地图: R.地图, 推进剂: R.推进剂, 当前: R.当前, 起点: R.地图.起点, 出口尽头: R.地图.出口尽头, 出口小径: R.地图.出口小径, 守军: R.地图.守军 });
  };
  const a = 跑(20261050), b = 跑(20261050), c = 跑(20261051);
  if (a === b) ok(`同种子（20261050）两次生成的地图逐字相同（${a.length} 个字符）`);
  else bad('同种子两次地图不一样');
  if (a !== c) ok('换一个种子地图就不一样');
  else bad('换种子地图居然一样');
  /* 同种子 → 同一格抽到的编成也一样 */
  const 编成 = 种子 => {
    const R = 开一局(种子);
    R.层 = 2; R.场次 = 0;
    R.地图 = G.生成层(2, G.地图种子(R.种子, 2));
    R.当前 = 找格(R, '精英') != null ? 找格(R, '精英') : R.地图.起点;
    const e = 肉鸽.抽当前编成();
    return e ? [...(e.前 || []), ...(e.后 || [])].join('+') : '无';
  };
  const e1 = 编成(20261052), e2 = 编成(20261052);
  if (e1 === e2) ok(`同种子同一格抽到的编成也一样：${e1}`);
  else bad(`同种子抽到的编成不一样：${e1} / ${e2}`);
  /* 源码里不许有 Math.random（91-地图.js 的可执行代码里） */
  const { readFileSync } = await import('fs');
  const 图源码 = readFileSync(join(ROOT, 'src', 'js', '91-地图.js'), 'utf8');
  const 图代码 = 图源码.replace(/\/\*[\s\S]*?\*\//g, '').replace(/^\s*\/\/.*$/gm, '');   // 先去掉注释
  if (!/Math\.random/.test(图代码)) ok('91-地图.js 的代码里没有 Math.random（随机数一律 mulberry32 + 种子，方案 6.1）');
  else bad('91-地图.js 里出现了 Math.random');
  const 肉源码 = readFileSync(join(ROOT, 'src', 'js', '90-肉鸽.js'), 'utf8')
    .replace(/\/\*[\s\S]*?\*\//g, '').replace(/^\s*\/\/.*$/gm, '');
  const 肉地图段 = 肉源码.slice(肉源码.indexOf('进层('), 肉源码.indexOf('失败耐久('));   // 地图 / 移动这一大段
  if (!/Math\.random/.test(肉地图段)) ok('90-肉鸽.js 的地图与移动那一段也没有 Math.random');
  else bad('90-肉鸽.js 的地图与移动那一段出现了 Math.random');
  info('（`70-编成.js` 的 `抽编成` 里有个 `rng || Math.random` 兜底，那是 M1 就有的；抽当前编成() 永远传种子，不走那一条 —— 兜底只走 `抽编成兜底`（有日志的那条），见 tests/comp.js 第 [7] 段）');}

/* ============================================================================
 * ★ 2026-10-11 节点改造（作者拍板「① 节点改造这几条全部照做」）
 * 方案书 = `协作/节点设计对比-黑流树海.md`；判据 = **消除「零代价纯收益」**。
 * ========================================================================== */

/** 把出口守军打赢（只验流程：敌人 HP 压到 1 + 清波次 + 我方不死）。 */
function 秒掉守军() {
  if (!界面.ctx) return false;
  界面.ctx.enemies.forEach(e => { e.maxHp = 1; e.hp = 1; });
  界面.ctx.allies.forEach(u => { u.maxHp = 10000000; u.hp = 10000000; });
  界面.ctx.波次 = [];
  打完这一场();
  return true;
}
/** 把这一层的出口守军直接标成「已清」（不想真的打一场时用；出口的放行逻辑只看这一格）。 */
function 清掉守军(R) { const 守 = R.地图.格[R.地图.守军]; if (守) { 守.已过 = true; 守.类型 = '空'; } }
/** 开一局并**站到 `层` 层**：`开一局()` 只建第 1 层，而节点改造之后休整 / 隧道 / 侵蚀源都不在第 1 层，
 *  所以这些段要先 `肉鸽.进层(层)` 换成一张真的第 N 层地图，再 `跳格` 到要测的那一格。
 *  返回 `{R, k}`（`k` = 这一层第一个该类型的格号；没有就是 null）。 */
function 站到(种子, 层, 类型) {
  const R = 开一局(种子);
  if (层 !== 1) 肉鸽.进层(层);
  const k = 类型 ? 找格(R, 类型) : null;
  if (k != null) { R.当前 = k; R.地图.格[k].已过 = false; }
  return { R, k };
}

/* ============================ [9] 出口两型 + 换希望 + 小径带推进剂到下一层 ============================ */
console.log('\n[9] 出口两型（尽头 / 小径）：剩余推进剂 × `出口换希望`（★ 2026-10-13 起 0.5 = 2:1，向下取整）换希望 / 小径带推进剂到下一层');
{
  const G1 = G.守军奖励;
  /* --- 尽头：推进剂 5 → 希望 +floor(5 × 率)，推进剂清零 --- */
  const R = 开一局(20261060);
  肉鸽.跳格(R.地图.出口尽头);
  清掉守军(R);
  R.推进剂 = 5;
  const 希前 = R.希望;
  if (界面.前进('尽头') === true && R.层 === 2) {
    ok(`走「出口尽头」：剩余推进剂 5 × ${G.肉鸽数值.出口换希望} → 希望 ${希前} → ${R.希望}（+${R.希望 - 希前}），进了第 ${R.层} 层`);
  } else bad(`出口尽头没换层：层 ${R.层}、希望 ${R.希望}`);
  /* ★ 2026-10-13 经济收紧：率从 1 改成 0.5（`肉鸽数值.出口换希望`），**换算形状没改**（余量 × 率，向下取整）——
     断言写成「同一构建内的关系式」（框架 §16）：期望值 = `Math.floor(5 × 率)`，**不钉 1:1 这个历史常量**。 */
  if (R.希望 === 希前 + Math.floor(5 * G.肉鸽数值.出口换希望)) ok(`换希望的比率 = ${G.肉鸽数值.出口换希望} : 1（形状照抄原作「将所有剩余行动力转化为希望」，率是 2026-10-13 经济收紧的旋钮）`);
  else bad(`换希望的数字不对：${希前} → ${R.希望}（期望 +${Math.floor(5 * G.肉鸽数值.出口换希望)}）`);
  if (R.日志.some(x => x.文本.includes('出口尽头') && x.文本.includes('希望 +'))) ok(`日志写了：${R.日志.filter(x => x.文本.includes('出口尽头')).pop().文本}`);
  else bad('出口尽头没写日志');
  /* --- 尽头：一点不剩就换不到希望（不倒退、也不奖励） --- */
  const R2 = 开一局(20261060);
  肉鸽.跳格(R2.地图.出口尽头);
  清掉守军(R2);
  R2.推进剂 = 0; R2.追击 = true;              // 追击过 → 不再触发追击战，直接换层
  const 希2 = R2.希望;
  界面.前进('尽头');
  if (R2.希望 === 希2 && R2.层 === 2) ok(`推进剂 0 走「出口尽头」：希望一点不涨（${希2}），照样进下一层（照抄原作：没剩的就换不到）`);
  else bad(`推进剂 0 的出口尽头不对：希望 ${希2} → ${R2.希望}、层 ${R2.层}`);
  /* --- 小径：不换希望，下一层推进剂上限 +2 --- */
  const R3 = 开一局(20261061);
  const 小径上限前 = G.推进剂上限(R3);
  const 小径余量前 = G.推进剂余量(R3.层);
  肉鸽.跳格(R3.地图.出口小径);
  清掉守军(R3);
  R3.推进剂 = 6;
  const 希3 = R3.希望;
  if (界面.前进('小径') === true && R3.层 === 2) {
    ok(`走「出口小径」：希望不换（${希3} → ${R3.希望}），进第 2 层`);
  } else bad(`出口小径没换层：层 ${R3.层}、希望 ${R3.希望}`);
  /* ★ 2026-10-12 地图大改：**+1 → +2**（二部图：+1 完全无效）。
     上限的「基础」跟着这一层的图走，所以期望值 = 新层该图最短路 + 新层余量 + 小径加成。 */
  const 小径期望 = R3.地图.最短路 + G.推进剂余量(R3.层) + G.肉鸽数值.出口小径加成;
  if (G.肉鸽数值.出口小径加成 === 2 && G.肉鸽数值.出口小径加成 % 2 === 0) {
    ok(`出口小径加成 = **+${G.肉鸽数值.出口小径加成}**（偶数；调研 §2.3：网格是二部图，+1 与 +0 的可行路线数逐字相同 → 必须 +2）`);
  } else bad(`出口小径加成不是偶数 2：${G.肉鸽数值.出口小径加成}`);
  if (R3.希望 === 希3 && G.推进剂上限(R3) === 小径期望 && R3.推进剂 === G.推进剂上限(R3)) {
    ok(`小径把推进剂带到下一层：第 2 层上限 = 该图最短路 ${R3.地图.最短路} + 余量 ${G.推进剂余量(2)}（${小径余量前 === G.推进剂余量(2) ? '同' : '另'}一层余量）+ 小径 ${G.肉鸽数值.出口小径加成} = ${G.推进剂上限(R3)}，进层就按新上限发 ${R3.推进剂}`);
  } else bad(`小径的推进剂加成不对：上限 ${G.推进剂上限(R3)}（期望 ${小径期望}）、推进剂 ${R3.推进剂}；第 1 层上限原本是 ${小径上限前}`);
  if (R3.层出口小径.includes(2)) ok(`存档字段 \`RUN.层出口小径\` 记着「哪一层的上限 +${G.肉鸽数值.出口小径加成}」：${JSON.stringify(R3.层出口小径)}`);
  else bad(`层出口小径 没记上：${JSON.stringify(R3.层出口小径)}`);
  /* --- 两型互斥：选过一次之后本层就定了 --- */
  const R4 = 开一局(20261062);
  肉鸽.跳格(R4.地图.出口尽头);
  清掉守军(R4);
  肉鸽.选出口('尽头');
  const 定1 = 肉鸽.本层出口类型();
  肉鸽.选出口('小径');
  const 定2 = 肉鸽.本层出口类型();
  if (定1 === '尽头' && 定2 === '小径' && Object.keys(G.出口选择表(R4)).length === 1) {
    ok(`出口两型**互斥**（一层只记一个）：选了「${定1}」再改「${定2}」，\`RUN.层出口选择\` 里还是只有 ${Object.keys(G.出口选择表(R4)).length} 个键`);
  } else bad(`出口两型没互斥：${JSON.stringify(G.出口选择表(R4))}`);
  if (肉鸽.选出口('乱写') === false) ok('认不出来的出口类型被拒绝（`选出口()` 返回 false）');
  else bad('乱写的出口类型居然被接受了');
  /* --- 界面：格菜单给的是两个互斥选项 --- */
  const R5 = 开一局(20261063);
  清掉守军(R5);
  const 菜单头 = 肉鸽.格菜单(R5.地图.出口尽头).map(a => a.动);
  const 菜单径 = 肉鸽.格菜单(R5.地图.出口小径).map(a => a.动);
  if (菜单头.includes('前进:尽头') && 菜单头.includes('前进:小径') && 菜单径.includes('前进:尽头') && 菜单径.includes('前进:小径')) {
    ok(`出口格菜单给的是两个互斥选项：${菜单头.join('、')}（两个出口格都一样）；守军没清时改成指路「去节点:<守军格>」`);
  } else bad(`出口格菜单不对：尽头 ${菜单头.join('、')} / 小径 ${菜单径.join('、')}`);
  /* --- 追击战那条路不要被出口换希望搅乱（改前修过的连换两层 bug） --- */
  const R6 = 开一局(20261064);
  肉鸽.跳格(R6.地图.出口尽头);
  清掉守军(R6);
  R6.推进剂 = 0;
  const 层前6 = R6.层;
  界面.前进('尽头');
  if (R6.层 === 层前6 + 1) ok(`推进剂 0 在出口触发追击战：打完只换**一层**（第 ${层前6} → ${R6.层}）—— 改前修过的「连换两层」没有再犯`);
  else bad(`出口追击战换层不对：第 ${层前6} → ${R6.层}`);
  info(`出口守军奖励常量（【初稿·待作者调】）：希望用精英档 ${G.肉鸽数值.精英希望}、源碳 ${G1.源碳}、额外源碳 ${G1.额外源碳}、必给零件 ${G1.必给零件}`);
}

/* ============================ [10] 出口守军补奖励 ============================ */
console.log('\n[10] 出口守军补奖励（推翻改前的「打赢零收益」；【初稿·待作者调】）');
{
  const R = 开一局(20261070);
  R.推进剂 = 60;
  const m = R.地图;
  /* 先站到守军旁边，再走一步进守军格（去节点 才算得出距离） */
  肉鸽.跳格(G.邻居(m.守军, m.列数).find(k => m.格[k]));
  const 界面类型 = 界面.去节点(m.守军);
  if (界面类型 === '出口守军' && 界面.屏 === '编队') ok(`走到守军格 → 编队屏（改前也是这样）`);
  else bad(`走到守军格不对：${界面类型} / 屏 ${界面.屏}`);
  界面.编队.出击 = R.队伍.slice(0, 3).map((x, i) => ({ 键: x.键, 位: i }));
  界面.动作('开战');
  秒掉守军();
  const 奖励 = 界面.战报 && 界面.战报.result ? 界面.战报.result : null;
  const 源碳 = R.源碳, 希望 = R.希望;
  if (m.格[m.守军].已过 && 肉鸽.进行中) ok(`守军打赢：守军格清空、层没变（${R.层}），出口放行`);
  else bad(`守军打赢之后不对：已过 ${m.格[m.守军].已过}、进行中 ${肉鸽.进行中}`);
  if (希望 >= G.肉鸽数值.起始希望 + G.肉鸽数值.精英希望) ok(`守军这一场给了**希望 +${G.肉鸽数值.精英希望}**（精英档，改前就有）`);
  else bad(`守军没给希望：${希望}`);
  if (源碳 >= G.肉鸽数值.起始源碳 + G.肉鸽数值.胜利源碳 + G.守军奖励.额外源碳) {
    ok(`★ 补的奖励真的到账：源碳 ${G.肉鸽数值.起始源碳} → ${源碳}（精英档 ${G.肉鸽数值.胜利源碳} ＋ 关口额外 ${G.守军奖励.额外源碳}）`);
  } else bad(`守军的补奖励没到账：源碳 ${源碳}（期望 ≥ ${G.肉鸽数值.起始源碳 + G.肉鸽数值.胜利源碳 + G.守军奖励.额外源碳}）`);
  const 日志 = R.日志.filter(x => x.文本.includes('出口守军已被击溃')).pop();
  if (日志 && /关口奖励 源碳 \+/.test(日志.文本)) ok(`日志写了关口奖励：${日志.文本}`);
  else bad(`守军的日志没写补奖励：${日志 && 日志.文本}`);
  /* 必给零件（战棋 31:293「精英必给」） */
  const 零件日志 = R.日志.filter(x => x.文本.includes('出口守军战利品') || x.文本.includes('获得零件'));
  if (零件日志.length) ok(`守军必给零件（照抄战棋 31:293 的「精英必给」）：${零件日志.pop().文本}`);
  else info('守军这一场零件箱满了 / 抽签没发（不失败：`G.守军奖励.必给零件` 那条口径允许「零件箱满了就不收」）');
}

/* ============================ [11] 黑市：刷新 + 卖零件 ============================ */
console.log('\n[11] 黑市：刷新（4/8/12/16、上限 4 次，照抄原作诡意行商）+ 卖零件（照抄战棋 30:117-120）');
{
  const R = 开一局(20261080);
  R.源碳 = 200;
  肉鸽.跳格(找格(R, '黑市'));
  const 货1 = 肉鸽.黑市货().slice();
  if (货1.length === G.肉鸽数值.黑市货件数) ok(`货架 ${货1.length} 件（肉鸽数值.黑市货件数 = ${G.肉鸽数值.黑市货件数}）`);
  else bad(`货架件数不对：${货1.length}`);
  /* 刷新价：4 → 8 → 12 → 16，上限 4 次 */
  const 价们 = [];
  for (let i = 0; i < 5; i++) { R.黑市刷新次数 = i; 价们.push(肉鸽.黑市刷新价()); }
  const 想价 = [4, 8, 12, 16, null];
  if (JSON.stringify(价们) === JSON.stringify(想价.map(x => x == null ? null : x + (G.肉鸽数值.黑市刷新基价 - 4)))) {
    ok(`刷新价逐级 +${G.肉鸽数值.黑市刷新加价}：${价们.slice(0, 4).join(' → ')}，第 5 次 = 刷满（${价们[4]}）`);
  } else bad(`刷新价不对：${JSON.stringify(价们)}（期望 4/8/12/16/null）`);
  /* 真的刷一次：扣源碳、次数 +1、摆出来的货换了一批 */
  R.黑市刷新次数 = 0;
  const 碳前 = R.源碳, 价1 = 肉鸽.黑市刷新价();
  const 刷 = 肉鸽.黑市刷新();
  const 货2 = 肉鸽.黑市货();
  if (刷.ok && R.源碳 === 碳前 - 价1 && R.黑市刷新次数 === 1 && JSON.stringify(货2) !== JSON.stringify(货1)) {
    ok(`刷新一次：源碳 ${碳前} → ${R.源碳}（−${价1}）、次数 ${R.黑市刷新次数}、货架换了一批（${货1.slice(0, 2).join('/')} → ${货2.slice(0, 2).join('/')}）`);
  } else bad(`刷新不对：${JSON.stringify(刷)} 源碳 ${碳前} → ${R.源碳} 次数 ${R.黑市刷新次数}`);
  /* 刷满 4 次之后再刷被拒绝 */
  for (let i = 0; i < 4; i++) 肉鸽.黑市刷新();
  const 满 = 肉鸽.黑市刷新();
  if (R.黑市刷新次数 === G.肉鸽数值.黑市刷新上限 && 满.ok === false && /4 次/.test(满.why)) {
    ok(`刷到上限（${G.肉鸽数值.黑市刷新上限} 次）：${满.why}（照抄原作「每个节点最多刷新 4 次」）`);
  } else bad(`刷新上限不对：次数 ${R.黑市刷新次数}、${JSON.stringify(满)}`);
  /* 源碳不够就刷不动 */
  R.黑市刷新次数 = 0; R.源碳 = 1;
  const 穷 = 肉鸽.黑市刷新();
  if (穷.ok === false && /源碳不够/.test(穷.why)) ok(`源碳不够时刷不了：${穷.why}`);
  else bad(`源碳不够却刷了：${JSON.stringify(穷)}`);
  /* --- 卖零件：自然物按估价、其他一律 2 源碳（战棋 30:101,119） --- */
  const R2 = 开一局(20261081);
  R2.源碳 = 20;
  R2.零件 = [];
  G.拿零件('wheel', '测试');          // 加工品 → 2 源碳
  G.拿零件('bloodcap', '测试');       // 自然物 → 按估价
  const 碳0 = R2.源碳;
  const 估价血蕈 = (R2.零件.find(p => p.k === 'bloodcap') || {}).value;
  const 卖掉0 = 肉鸽.黑市卖零件(0);
  const 卖掉1 = 肉鸽.黑市卖零件(0);   // 卖掉第一件之后 bloodcap 变成 0 号
  if (卖掉0.ok && 卖掉0.价 === 2 && R2.源碳 === 碳0 + 2 + 估价血蕈) ok(`卖加工品【${卖掉0.名}】+2 源碳（战棋 30:119「其他零件 2 源碳结晶」）`);
  else bad(`卖加工品不对：${JSON.stringify(卖掉0)} 源碳 ${碳0} → ${R2.源碳}`);
  if (卖掉1.ok && 卖掉1.价 === 估价血蕈 && /血蕈/.test(卖掉1.名)) {
    ok(`卖自然物【${卖掉1.名}】+${卖掉1.价} 源碳（按估价 —— 战棋 30:101「自然物按估价卖出」）；理财类终于能变现了`);
  } else bad(`卖自然物不对：${JSON.stringify(卖掉1)}（手上还剩 ${JSON.stringify(R2.零件)}）`);
  /* 界面上真的有「刷新」和「卖零件」两个按钮（先放一件零件回去，不然「卖零件」那一栏是空态） */
  G.拿零件('spring', '测试');
  界面.开屏('黑市');
  const 文 = 屏文字();
  if (/data-act="黑市刷新"/.test(文) && /data-act="黑市卖:0"/.test(文)) {
    ok('黑市屏上「刷新库存」与「卖零件」两个动作都接上了（`data-act="黑市刷新"` / `data-act="黑市卖:<下标>"`）');
  } else bad('黑市屏上没有刷新 / 卖零件的按钮');
  /* 刷新次数是**存档字段**（`RUN.黑市刷新次数`）：这一段手上是 R2（刚卖过零件、还一次没刷），
     所以现场刷一次，再验它真的记在 RUN 上（值 = 1）。 */
  R2.源碳 = 50;
  const 刷一次 = 肉鸽.黑市刷新();
  if ('黑市刷新次数' in R2 && R2.黑市刷新次数 === 1 && 刷一次.ok) {
    ok(`刷新次数是存档字段：\`RUN.黑市刷新次数\` = ${R2.黑市刷新次数}（现场刷一次 → 1，价格 ${刷一次.价}）`);
  } else bad(`黑市刷新次数没进 RUN / 不对：${JSON.stringify({ v: R2.黑市刷新次数, 刷一次 })}`);
}

/* ============================ [12] 事件换成有代价的 ============================ */
console.log('\n[12] 事件：逐字搬回战棋原版 5 个（30-移动与节点.js:123-129）+ 黑流树海 3 个，每个都有代价');
{
  /* 表本身：前 5 条必须对得上战棋的 EVENTS
     ★ 2026-10-12 作者试玩后点名改了「迷路的机师」那一条（原话：「这个事件非常蠢，不能免费送，
       应该是花 4 个源碳结晶收一个随机的招募券」）—— 这一行的**期望值跟着作者的新口径改**，
       判据本身（名字 / 选项文字 / 出处行号逐项相等）一个字没放宽；另外 4 个事件仍然逐字照抄战棋。
       新口径的机检在下面第 [22] 段（源碳 3 / 4 两种情况的真实数字 + 同种子两遍逐字相同）。 */
  const 想 = [
    ['漂流的补给舱', '推进剂 +3', '经验 +5', '30-移动与节点.js:124'],
    ['平行宇宙的回声', '作战耐久 −1，获得随机零件', '离开', '30-移动与节点.js:125'],
    ['迷路的机师', '花 4 源碳结晶 → 一张随机招募券', '离开', '30-移动与节点.js:126'],
    ['扭曲的时钟', '推进剂 −2，经验 +10', '离开', '30-移动与节点.js:127'],
    ['黑箱', '花 3 源碳结晶打开', '不碰它', '30-移动与节点.js:128'],
  ];
  const 前5 = G.事件表.slice(0, 5);
  const 逐字 = 前5.every((e, i) => e.名 === 想[i][0] && e.选[0].文 === 想[i][1] && e.选[1].文 === 想[i][2] && e.出处 === 想[i][3]);
  if (逐字 && 前5.length === 5) {
    ok(`战棋原版 5 个事件的名字 / 出处行号全对得上（其中 4 个逐字照抄；「迷路的机师」按作者 2026-10-12 拍板改成「花 4 源碳结晶 → 一张随机招募券」）：${前5.map(e => e.名).join('、')}`);
  } else bad(`前 5 个事件与战棋对不上：${JSON.stringify(前5.map(e => [e.名, e.选.map(o => o.文), e.出处]))}`);
  const 第二批 = G.事件表.slice(5);
  if (第二批.length === 3 && 第二批.every(e => /黑流树海/.test(e.出处))) {
    ok(`第二批 3 个照抄黑流树海（每个都带出处）：${第二批.map(e => `${e.名}（${e.选.length} 选项）`).join('、')}`);
  } else bad(`第二批事件不对：${JSON.stringify(第二批.map(e => [e.名, e.出处]))}`);
  /* 每个事件的每个选项都写明代价或收益（人工判断的那 8 条，这里机检「文字里有量化符号」） */
  const 没量化 = G.事件表.filter(e => e.选.some(o => !/[+\-−±]|\d|离开|不碰|不关|不感|招募一名/.test(o.文)));
  if (!没量化.length) ok('每个选项的文字里都写了量化效果或明确的「离开 / 不碰」：没有一个「点一下白拿」的按钮');
  else bad(`有选项看不出代价 / 收益：${JSON.stringify(没量化.map(e => e.名))}`);
  /* 真的走一遍 5 个原版事件（逐个把这一格的事件换掉） */
  const 走 = (名, 选项下标) => {
    const { R } = 站到(20261090, 2, '事件');
    /* 把「这一格遇到哪个事件」钉死成想测的那一个 */

    const 找 = G.事件表.findIndex(e => e.名 === 名);
    const 快照 = { 推进剂: R.推进剂, 源碳: R.源碳, 耐久: R.耐久, 经验: R.经验, 队伍: R.队伍.length, 场次: R.场次 };
    const 结果 = 肉鸽.奇遇(String(选项下标));
    return { R, 快照, 结果, 找 };
  };
  /* 为了让「遇到哪个事件」可控：临时把 `RUN.当前` 换成能命中那个事件的格号（同一个 rng 口径） */
  const 钉死事件 = (R, 序号) => {
    /* `当前事件()` 用 `mulberry32(种子 + 层×811 + 格号×23)` 抽；
       这里把 层 挪到能让 seed+层*811+格号*23 ≡ 命中那个下标的位置做不到稳定，
       所以改用「把事件表缩小到只剩它」的办法：临时替换 `事件表` 太长，
       直接验证 `做()` 本身（`G.事件表[i].选[j].做(R)`）—— 这是**纯函数级别的验证**，
       界面上「弹窗 → 选 → 结算 → 回大地图」的闭环在第 [5b] 段。 */
    return 序号;
  };
  {
    const R = 开一局(20261090);
    const 数 = {};
    for (let i = 0; i < 60; i++) {
      R.当前 = i; R.层 = 1 + (i % 4);
      const e = 肉鸽.当前事件();
      数[e.名] = (数[e.名] || 0) + 1;
    }
    const 命中 = Object.keys(数).length;
    if (命中 >= 6) ok(`同一局不同格会抽到不同事件（60 次抽到 ${命中} 种）：${Object.entries(数).map(([k, v]) => `${k}×${v}`).join('、')}`);
    else info(`60 次只抽到 ${命中} 种事件：${JSON.stringify(数)}`);
    /* 同一格永远是同一个事件（同种子可复现） */
    R.当前 = 13; R.层 = 2;
    const a = 肉鸽.当前事件().名;
    const b = 肉鸽.当前事件().名;
    if (a === b) ok(`同一局同一格的事件**可复现**（不是 Math.random）：${a}`);
    else bad(`同一格两次抽到不同事件：${a} / ${b}`);
  }
  /* 逐条验「做」：平行宇宙的回声（耐久 −1 换零件） */
  {
    const R = 开一局(20261091);
    R.层 = 2;
    R.零件 = [];
    const 前 = { 耐久: R.耐久, 零件: R.零件.length };
    const 事 = G.事件表.find(e => e.名 === '平行宇宙的回声');
    const 结果 = 事.选[0].做(R);
    if (R.耐久 === 前.耐久 - 1 && R.零件.length >= 前.零件 + 1 && /作战耐久 −1/.test(结果)) {
      ok(`「平行宇宙的回声」第 1 项真的付代价换收益：作战耐久 ${前.耐久} → ${R.耐久}、零件 ${前.零件} → ${R.零件.length}（${结果}）`);
    } else bad(`回声不对：${JSON.stringify({ 结果, 耐久: R.耐久, 零件: R.零件.length })}`);
  }
  /* 扭曲的时钟（推进剂 −2 换经验 +10） */
  {
    const R = 开一局(20261092);
    R.推进剂 = 5;
    const 前 = { 推进剂: R.推进剂, 经验: R.经验 };
    const 事 = G.事件表.find(e => e.名 === '扭曲的时钟');
    const 结果 = 事.选[0].做(R);
    if (R.推进剂 === 前.推进剂 - 2 && R.经验 > 前.经验 && /推进剂 −2/.test(结果)) {
      ok(`「扭曲的时钟」：推进剂 ${前.推进剂} → ${R.推进剂}（−2）、经验 ${前.经验} → ${R.经验}（${结果}）`);
    } else bad(`扭曲的时钟不对：${JSON.stringify({ 结果, 推进剂: R.推进剂, 经验: R.经验 })}`);
  }
  /* 黑箱（花 3 源碳：一半经验 +6 / 一半给零件） */
  {
    let 经 = 0, 零 = 0;
    for (const 种子 of [20261093, 20261094, 20261095, 20261096, 20261097, 20261098]) {
      const R = 开一局(种子);
      R.源碳 = 20; R.零件 = [];
      const 前碳 = R.源碳, 前经 = R.经验;
      const 事 = G.事件表.find(e => e.名 === '黑箱');
      const 结果 = 事.选[0].做(R);
      if (R.源碳 === 前碳 - 3 && R.经验 > 前经) 经++;
      else if (R.源碳 === 前碳 - 3 && R.零件.length) 零++;
    }
    if (经 + 零 === 6) ok(`「黑箱」花 3 源碳开箱：${经} 次给经验 +6、${零} 次给零件（战棋 30:128 的「一半概率」两条路都走到了）`);
    else bad(`黑箱不对：给经验 ${经} 次、给零件 ${零} 次（共 6 次）`);
    /* 钱不够：什么都不发生（战棋 `if (RUN.he < 3) return;`） */
    const R = 开一局(20261099);
    R.源碳 = 2;
    const 前碳 = R.源碳;
    const 事 = G.事件表.find(e => e.名 === '黑箱');
    const 空 = 事.选[0].做(R);
    if (空 == null && R.源碳 === 前碳) ok(`源碳不够（2 < 3）时黑箱什么都不发生（照抄战棋 30:128 的 \`if (RUN.he < 3) return;\`）`);
    else bad(`源碳不够却开了黑箱：${JSON.stringify(空)} 源碳 ${前碳} → ${R.源碳}`);
  }
  /* 沉重的契约（一半作战耐久换 5 推进剂） */
  {
    const R = 开一局(20261100);
    R.耐久 = 9; R.推进剂 = 2;
    const 事 = G.事件表.find(e => e.名 === '沉重的契约');
    const 结果 = 事.选[1].做(R);
    if (R.耐久 === 9 - 4 && R.推进剂 === 2 + 5) ok(`「沉重的契约」推翻石磨：作战耐久 9 → ${R.耐久}（消耗一半 = 4）、推进剂 2 → ${R.推进剂}（${结果}）`);
    else bad(`沉重的契约不对：耐久 ${R.耐久}、推进剂 ${R.推进剂}（${结果}）`);
  }
  /* 结算过的格不再结算第二次（RUN.事件已选） */
  {
    const { R } = 站到(20261101, 2, '事件');
    const 一 = 肉鸽.奇遇('0');
    const 键 = `${R.层}:${R.当前}`;
    if (一.ok && 一.结果 && (R.事件已选 || {})[键]) {
      ok(`事件结算写进 \`RUN.事件已选\`（存档字段）：${键} → ${R.事件已选[键]}`);
    } else bad(`事件没记进 事件已选：${JSON.stringify(一)} / ${JSON.stringify(R.事件已选)}`);
  }
}

/* ============================ [13] 瞭望站：只给视野，不再给希望 ============================ */
console.log('\n[13] 瞭望站：删掉「希望 +3」（原作羽瞰点只给视野）；远眺 4 格 / 登高 12 格 +1 推进剂');
{
  if (G.肉鸽数值.瞭望站希望 === 0) ok(`常量 \`肉鸽数值.瞭望站希望\` = ${G.肉鸽数值.瞭望站希望}（★ 作者点名「删掉希望 +3」，一条常量就够）`);
  else bad(`瞭望站希望还是 ${G.肉鸽数值.瞭望站希望}`);
  /* 远眺：只揭开 4 格，不给推进剂、不给希望 */
  const R = 开一局(20261110);
  肉鸽.跳格(找格(R, '瞭望站'));
  R.推进剂 = 3;
  const 希前 = R.希望;
  const 远 = 肉鸽.结算瞭望站('远眺');
  if (远 && 远.选 === '远眺' && 远.半径 === G.肉鸽数值.瞭望站远眺 && R.推进剂 === 3 && R.希望 === 希前) {
    ok(`「远眺」：揭开周围 ${远.半径} 格（新揭开 ${远.揭开} 格）、推进剂一点不动（${R.推进剂}）、希望一点不给（${R.希望}）`);
  } else bad(`远眺不对：${JSON.stringify(远)} 推进剂 ${R.推进剂} 希望 ${R.希望}（原 ${希前}）`);
  /* 登高：揭开 12 格 + 推进剂 +1 */
  const R2 = 开一局(20261111);
  肉鸽.跳格(找格(R2, '瞭望站'));
  R2.推进剂 = 3;
  const 希2 = R2.希望;
  const 登 = 肉鸽.结算瞭望站('登高');
  if (登 && 登.选 === '登高' && 登.半径 === G.肉鸽数值.瞭望站登高 && R2.推进剂 === 3 + G.肉鸽数值.瞭望站推进剂 && R2.希望 === 希2) {
    ok(`「登高」：揭开周围 ${登.半径} 格（新揭开 ${登.揭开} 格）、推进剂 ${3} → ${R2.推进剂}（+${G.肉鸽数值.瞭望站推进剂}）、希望还是 ${R2.希望}`);
  } else bad(`登高不对：${JSON.stringify(登)} 推进剂 ${R2.推进剂} 希望 ${R2.希望}`);
  /* 不传参数 → 按登高（原作行为） */
  const R3 = 开一局(20261112);
  肉鸽.跳格(找格(R3, '瞭望站'));
  R3.推进剂 = 3;
  const 默 = 肉鸽.结算瞭望站();
  if (默.选 === '登高' && R3.推进剂 === 4) ok('不传参数时按「登高」算（= 原作羽瞰点的行为，界面 / 老调用点都安全）');
  else bad(`默认档不对：${JSON.stringify(默)} 推进剂 ${R3.推进剂}`);
  /* 界面上有「远眺 / 登高」两个选项，且文案里没有「希望 +3」 */
  const R4 = 开一局(20261113);
  肉鸽.跳格(找格(R4, '瞭望站'));
  const 原钩 = 界面.对话框钩子;
  let 弹窗选项 = null;
  界面.对话框钩子 = (标题, 文本, 选项) => { 弹窗选项 = 选项; return '远眺'; };
  界面.去瞭望();
  界面.对话框钩子 = 原钩;
  const 文 = (弹窗选项 || []).map(o => `${o.值}:${o.名}`).join(' | ');
  if ((弹窗选项 || []).length === 2 && !/希望 \+/.test(文)) {
    ok(`瞭望站弹窗是两选一、且**没有「希望 +N」这种收益**（只写着「不给希望」）：${文}`);
  } else bad(`瞭望站弹窗不对：${文}`);
  info('（原作还有一条「点亮生命游戏的分裂节点后揭示范围 12 → 24」——我们没有天赋树，这一条不适用）');
}

/* ============================ [14] 遗迹三选一 ============================ */
console.log('\n[14] 遗迹：三选一（2 作战耐久 / 8 源碳 / 离开，照抄「沉寂之屋」）——「50% 送藏品」已删');
{
  /* 三条路的核心代价 / 收益在第 [5] 段已经逐条量过，这里补「格菜单 + 界面弹窗 + 只落在死胡同」 */
  const { R, k } = 站到(20261120, 2, '遗迹');
  const 菜单 = 肉鸽.格菜单(k);
  if (菜单.length === 1 && /三选一/.test(菜单[0].名)) ok(`遗迹格菜单写明三选一：${菜单[0].名}`);
  else bad(`遗迹格菜单不对：${JSON.stringify(菜单)}`);
  const 原钩 = 界面.对话框钩子;
  let 弹窗 = null;
  界面.对话框钩子 = (标题, 文本, 选项) => { 弹窗 = 选项; return '离开'; };
  界面.去遗迹();
  界面.对话框钩子 = 原钩;
  const 值们 = (弹窗 || []).map(o => o.值);
  if (值们.length === 3 && 值们.includes('藤蔓') && 值们.includes('交流') && 值们.includes('离开')) {
    ok(`遗迹弹窗是**互斥三选一**：${(弹窗 || []).map(o => o.值 + '=' + o.名).join(' | ')}`);
  } else bad(`遗迹弹窗不对：${JSON.stringify(值们)}`);
  /* 遗迹：**有空死胡同就用死胡同**；一个死胡同都没有的图退回「度 ≤2 的支线」→「离起点最近的空格」
     ★ 2026-10-12 地图大改：口径照调研 §5 A3「收益类节点进支线」——
       优先池 = 死胡同 → 度 ≤2 的支线 → 离起点最近的空格（原来只有「死胡同 / 最近空格」两档）。
     ★ 这里改成**统计 40 张图**（单张图的空洞洞是抽样噪声：改造后地形变了，10 张里一张都没死胡同很正常），
       断言「有死胡同的图里遗迹落在死胡同的比例」+「遗迹一律落在度 ≤2 的支线上」两条。 */
  let 有死图 = 0, 在死 = 0, 支线总 = 0, 遗迹总 = 0;
  const 样本 = [];
  for (let i = 0; i < 40; i++) {
    const m = G.生成层(2, G.地图种子((700000 + i * 7919) >>> 0, 2));
    const L = m.列数;
    const 有 = x => !!m.格[x];
    const 度 = x => G.邻居(x, L).filter(有).length;
    const 死 = Object.keys(m.格).map(Number).filter(x => G.是死胡同(x, 有, L));
    const 遗 = Object.keys(m.格).map(Number).filter(x => m.格[x].类型 === '遗迹');
    const 距 = G.BFS距离(m.起点, m.格, L);
    for (const x of 遗) {
      遗迹总++;
      if (度(x) <= 2) 支线总++;
      else bad(`遗迹落在了干路（度 ${度(x)}）：这张图死胡同 [${死.join(',')}]、遗迹 ${x}`);
    }
    if (死.length) { 有死图++; if (遗.every(x => 度(x) === 1)) 在死++; }
    样本.push(`格 ${Object.keys(m.格).length} / 死胡同 ${死.length} / 遗迹 ${遗.join(',')}（度 ${遗.map(度).join(',')}，距起点 ${遗.map(x => 距.get(x)).join(',')}）`);
  }
  if (遗迹总 === 支线总) ok(`★ 遗迹（${遗迹总} 张）**全部**落在支线上（度 ≤2）—— 调研 §5 A3「收益类节点进支线」`);
  else bad(`有遗迹落在干路上：${支线总}/${遗迹总}`);
  if (有死图) ok(`有死胡同的图里，遗迹落在死胡同的比例 ${在死}/${有死图}（优先池就是死胡同；被别的节点先占掉时会退到「度 ≤2 的支线」→「离起点最近的空格」）`);
  else info('这 40 张图一个死胡同都没有 —— 走的是「度 ≤2 的支线 → 离起点最近的空格」兜底');
  info(`抽样：${样本.slice(0, 4).join('　|　')}`);
}

/* ============================ [15] 休整互斥三选一 ============================ */
console.log('\n[15] 休整：互斥三选一（耐久 +2 / 晋升 −1 希望 / 推进剂 +2），第 1 层不出现');
{
  const { R, k } = 站到(20261130, 2, '休整');
  const 菜单 = 肉鸽.格菜单(k);
  const 动们 = 菜单.map(a => a.动);
  if (动们.length === 3 && 动们.includes('休整:耐久') && 动们.includes('休整:晋升') && 动们.includes('休整:推进剂')) {
    ok(`休整三选一：${动们.join('、')}（「花希望买耐久」与「跳过」都没有了）`);
  } else bad(`休整选项不对：${动们.join('、')}`);
  /* 三个选项各来一次，互相不影响（拿一个就结束） */
  const 三选 = ['耐久', '晋升', '推进剂'].map(选 => {
    const { R: r } = 站到(20261131, 2, '休整');
    const 前 = { 耐久: r.耐久, 希望: r.希望, 推进剂: r.推进剂 };
    const 结 = 肉鸽.结算休整(选);
    return { 选, 前, 后: { 耐久: r.耐久, 希望: r.希望, 推进剂: r.推进剂 }, 结, 已过: r.地图.格[r.当前].已过, R: r };
  });
  const 都过 = 三选.every(x => x.结 && x.结.ok && x.已过);
  const 耐久项 = 三选[0], 晋升项 = 三选[1], 推进剂项 = 三选[2];
  if (都过 && 耐久项.后.耐久 === 耐久项.前.耐久 + G.肉鸽数值.休整耐久 && 耐久项.后.推进剂 === 耐久项.前.推进剂) {
    ok(`「坐下休息」：耐久 ${耐久项.前.耐久} → ${耐久项.后.耐久}（+${G.肉鸽数值.休整耐久}），推进剂与希望不动`);
  } else bad(`休整耐久项不对：${JSON.stringify(耐久项)}`);
  if (晋升项.结.减价 === true && 晋升项.后.耐久 === 晋升项.前.耐久 && 晋升项.后.推进剂 === 晋升项.前.推进剂) {
    ok(`「放弃休息」：\`RUN.下次晋升减价\` = true，耐久 ${晋升项.后.耐久} 一点不涨（拿一个就结束 = 真的互斥）`);
  } else bad(`休整晋升项不对：${JSON.stringify(晋升项)}`);
  if (推进剂项.后.推进剂 > 推进剂项.前.推进剂 && 推进剂项.后.推进剂 === Math.min(G.推进剂上限(推进剂项.R) + 1, 推进剂项.前.推进剂 + G.肉鸽数值.休整推进剂)
      && 推进剂项.后.耐久 === 推进剂项.前.耐久) {
    ok(`「把这一格让出来」：推进剂 ${推进剂项.前.推进剂} → ${推进剂项.后.推进剂}（+${G.肉鸽数值.休整推进剂}，被上限 ${G.推进剂上限(推进剂项.R) + 1} 封了一格），耐久不涨`);
  } else bad(`休整推进剂项不对：${JSON.stringify(推进剂项)}`);
  /* 第 1 层不出现（层数门在 91-地图.js 的 计划要放） */
  let 一层有 = 0;
  for (let i = 0; i < 30; i++) {
    const m = G.生成层(1, G.地图种子((800000 + i * 7919) >>> 0, 1));
    if (Object.values(m.格).some(n => n.类型 === '休整')) 一层有++;
  }
  if (一层有 === 0) ok('第 1 层 30 张图一个休整格都没有（照抄原作「安全的角落：※该节点不会在第 Ⅰ 层出现」）');
  else bad(`第 1 层出现休整：${一层有} / 30 张`);
  /* 隧道第 2 层起（原作曲折密道「不会在第 Ⅰ、Ⅱ、Ⅵ 层出现」，我们只抄「第 1 层不放」） */
  let 一层隧道 = 0, 二层隧道 = 0;
  for (let i = 0; i < 30; i++) {
    const m1 = G.生成层(1, G.地图种子((810000 + i * 7919) >>> 0, 1));
    const m2 = G.生成层(2, G.地图种子((810000 + i * 7919) >>> 0, 2));
    if (Object.values(m1.格).some(n => n.类型 === '隧道')) 一层隧道++;
    if (Object.values(m2.格).some(n => n.类型 === '隧道')) 二层隧道++;
  }
  if (一层隧道 === 0 && 二层隧道 === 30) ok(`隧道：第 1 层 0 / 30 张、第 2 层 30 / 30 张（照抄原作「第 1 层不成对出现」那一半）`);
  else bad(`隧道的层数门不对：第 1 层 ${一层隧道} / 30、第 2 层 ${二层隧道} / 30`);
}

/* ============================ [16] 隧道代价 + 侵蚀源代价 ============================ */
console.log('\n[16] 补代价：隧道进入花 1 推进剂 + 侵蚀源先付代价（硬闯 +15% / 花 8 源碳净化）');
{
  /* --- 隧道：进去花 1 点（第 [5] 段量过结算，这里量界面文案与「付不起」） --- */
  const R = 开一局(20261140);
  const 隧道们 = R.地图.隧道;
  if (隧道们.length !== 2) info('第 1 层没有隧道（节点改造后第 1 层不放）—— 换到第 2 层');
  const { R: R2 } = 站到(20261141, 2, null);
  const 隧 = R2.地图.隧道;
  if (隧.length === 2) {
    肉鸽.跳格(隧[0]);
    R2.推进剂 = 1;
    const 原钩 = 界面.对话框钩子;
    let 提示文 = '';
    界面.对话框钩子 = (标题, 文本, 选项) => { 提示文 = 文本; return 'go'; };
    const 传 = 界面.穿隧道();
    界面.对话框钩子 = 原钩;
    if (传 && 传.ok && R2.当前 === 隧[1] && R2.推进剂 === 0) ok(`界面走一遍：弹窗文案里有「要花 1 点推进剂」（${/要花 <b>1<\/b> 点推进剂/.test(提示文) ? '有' : '没有'}）、传完推进剂 1 → ${R2.推进剂}`);
    else bad(`隧道界面闭环不对：${JSON.stringify(传)} 推进剂 ${R2.推进剂}`);
  } else info('第 2 层这张图没有成对隧道，跳过界面闭环');
  /* --- 侵蚀源：两条互斥的代价 --- */
  const { R: R3 } = 站到(20261142, 2, '侵蚀源');
  if (肉鸽.侵蚀源代价() !== null) bad(`刚进这一格就有代价了：${肉鸽.侵蚀源代价()}`);
  else ok('侵蚀源刚走到时不带任何代价（必须先选）');
  const 菜单 = 肉鸽.格菜单(R3.当前);
  if (菜单.length && /先付代价/.test(菜单[0].名)) ok(`侵蚀源格菜单先要代价：${菜单[0].名}`);
  else bad(`侵蚀源格菜单不对：${JSON.stringify(菜单)}`);
  /* ① 硬闯：不花源碳，这一场敌方 +15% */
  const 碳前 = R3.源碳;
  const 硬 = 肉鸽.结算侵蚀源代价('硬闯');
  if (硬.ok && 硬.敌方加成 === G.肉鸽数值.侵蚀源强攻加成 && R3.源碳 === 碳前 && 肉鸽.侵蚀源敌方加成() === 硬.敌方加成) {
    ok(`「硬闯」：源碳一点没花（${R3.源碳}），本场敌方攻防 +${Math.round(硬.敌方加成 * 100)}%（【初稿】）`);
  } else bad(`硬闯不对：${JSON.stringify(硬)} 源碳 ${碳前} → ${R3.源碳} 当前加成 ${肉鸽.侵蚀源敌方加成()}`);
  /* ② 净化：花 8 源碳，这一场正常 */
  const { R: R4 } = 站到(20261143, 2, '侵蚀源');
  const 碳4 = R4.源碳;
  const 净 = 肉鸽.结算侵蚀源代价('净化');
  if (净.ok && R4.源碳 === 碳4 - G.肉鸽数值.侵蚀源净化价 && 肉鸽.侵蚀源敌方加成() === 0) {
    ok(`「花源碳买净化」：源碳 ${碳4} → ${R4.源碳}（−${G.肉鸽数值.侵蚀源净化价}），这一场不加成（${肉鸽.侵蚀源敌方加成()}）`);
  } else bad(`净化不对：${JSON.stringify(净)} 源碳 ${碳4} → ${R4.源碳} 加成 ${肉鸽.侵蚀源敌方加成()}`);
  /* ③ 源碳不够 → 净化被拒绝 */
  const { R: R5 } = 站到(20261144, 2, '侵蚀源');
  R5.源碳 = 1;
  const 穷 = 肉鸽.结算侵蚀源代价('净化');
  if (穷.ok === false && /源碳不够/.test(穷.why)) ok(`源碳不够时净化被拒绝：${穷.why}`);
  else bad(`源碳不够却净化了：${JSON.stringify(穷)}`);
  /* ④ 加成真的进这一场战斗（敌方攻防 ×1.15） */
  {
    const { R: R6 } = 站到(20261145, 2, '侵蚀源');
    R6.推进剂 = 60;
    肉鸽.结算侵蚀源代价('硬闯');
    界面.准备肉鸽编队();
    界面.编队.出击 = R6.队伍.slice(0, 3).map((x, i) => ({ 键: x.键, 位: i }));
    界面.动作('开战');
    if (界面.屏 === '战斗' && 界面.ctx) {
      const 敌方 = 界面.ctx.enemies[0];
      const 日志 = R6.日志.filter(x => x.文本.includes('侵蚀源') && x.文本.includes('+15%')).pop();
      if (日志 && 敌方 && 敌方.defense > 0) ok(`硬闯的加成真的进了这一场：日志「${日志.文本}」，敌方 ${敌方.key} 的防御已经被抬到 ${敌方.defense}`);
      else bad(`硬闯的加成没进战斗：${日志 && 日志.文本}`);
      打完这一场();
    } else bad(`侵蚀源开战没进战斗：屏 ${界面.屏}`);
  }
}

/* ============================ [17] 总检：13 个节点逐个过「收益 / 代价 / 选择」 ============================ */
console.log('\n[17] 总检：13 个节点没有一个「零代价纯收益」（判据见 协作/节点设计对比-黑流树海.md §2.2）');
{
  /* 这一段的判据是**机检能查的那部分**：每个节点都必须有一条「要花东西」的路。
     真正「有没有取舍」的判断写在任务板的逐节点表里（人读），这里把可机检的钉住：
       ① 出口两型都必须有代价（尽头清零推进剂 / 小径放弃希望）；
       ② 事件每个选项都有量化文字（第 [12] 段已查）；
       ③ 五类「点了就有」的动作都必须带一个负数或问号（费）；
       ④ 瞭望站不再给希望（第 [13] 段）。 */
  const { R } = 站到(20261150, 2, null);
  const 表 = [];
  const 记 = (类型, 名) => {
    const k = 找格(R, 类型);
    if (k == null) return 表.push({ 类型, 名, 无格: true });
    R.当前 = k; R.地图.格[k].已过 = false;
    表.push({ 类型, 名, 菜单: 肉鸽.格菜单(k).map(a => ({ 动: a.动, 名: a.名 })) });
  };
  for (const [类型, 名] of [['作战', '作战'], ['精英', '精英'], ['侵蚀源', '侵蚀源'], ['黑市', '黑市'], ['事件', '事件'],
    ['瞭望站', '瞭望站'], ['遗迹', '遗迹'], ['休整', '休整'], ['招募站', '招募站'], ['隧道', '隧道'], ['出口守军', '出口守军']]) 记(类型, 名);
  清掉守军(R);
  R.当前 = R.地图.出口尽头; R.地图.格[R.当前].已过 = false;
  表.push({ 类型: '出口尽头', 名: '出口尽头', 菜单: 肉鸽.格菜单(R.当前).map(a => ({ 动: a.动, 名: a.名 })) });
  R.当前 = R.地图.出口小径; R.地图.格[R.当前].已过 = false;
  表.push({ 类型: '出口小径', 名: '出口小径', 菜单: 肉鸽.格菜单(R.当前).map(a => ({ 动: a.动, 名: a.名 })) });
  for (const x of 表) {
    if (x.无格) { info(`${x.名}：这一层没有这种格，跳过`); continue; }
    info(`${x.名}：${x.菜单.map(a => a.名).join('　|　')}`);
  }
  /* 出口两型都真的有代价 */
  const 尽头 = 表.find(x => x.类型 === '出口尽头');
  const 小径 = 表.find(x => x.类型 === '出口小径');
  if (尽头 && 小径 && 尽头.菜单.some(a => /前进:尽头/.test(a.动)) && 小径.菜单.some(a => /前进:小径/.test(a.动))) {
    ok('出口两型在格菜单里各给一条互斥的路（`前进:尽头` / `前进:小径`）—— 出口不再是「唯一一扇门」');
  } else bad('出口两型的菜单不对');
  /* 瞭望站 / 遗迹 / 休整 / 隧道 / 事件 的菜单里都写清了代价 */
  const 要写代价 = [['瞭望站', /视野|远眺|登高/], ['遗迹', /三选一/], ['休整', /坐下休息/], ['隧道', /花 \d+ 推进剂/], ['事件', /代价/]];
  let 缺 = 0;
  for (const [名, 正则] of 要写代价) {
    const x = 表.find(y => y.类型 === 名);
    if (!x || x.无格) continue;
    const 全 = x.菜单.map(a => a.名).join(' ');
    if (!正则.test(全)) { 缺++; bad(`${名} 的菜单里没写清它的代价 / 内容：${全}`); }
  }
  if (!缺) ok('瞭望站 / 遗迹 / 休整 / 隧道 / 事件的格菜单**都把代价写在了按钮上**（玩家点之前就知道要花什么）');
  info('★ 完整的「收益 / 代价 / 有没有选择」逐节点表在 协作/任务板.md（第 [17] 段的机检只钉「有没有代价」这一半）');
}

/* ============================ [18] 节点新增状态进存档 v3 + 旧档兼容 ============================ */
console.log('\n[18] 节点新增状态进存档 v3；旧存档缺字段 / 坏值一律补默认值、不崩');
{
  const { R } = 站到(20261160, 2, null);
  R.黑市刷新次数 = 3;
  R.层出口选择 = { 1: '小径', 2: '尽头' };
  R.层出口小径 = [2];
  R.事件已选 = { '2:7': '漂流的补给舱：推进剂 +3' };
  R.侵蚀源已净化 = { '2:9': '硬闯' };
  肉鸽.存档();
  const 快照 = {
    黑市刷新次数: R.黑市刷新次数, 层出口选择: JSON.stringify(R.层出口选择),
    层出口小径: JSON.stringify(R.层出口小径), 事件已选: JSON.stringify(R.事件已选), 侵蚀源已净化: JSON.stringify(R.侵蚀源已净化),
  };
  肉鸽.RUN = null;
  const 读 = 肉鸽.读存档();
  if (读 && 读.黑市刷新次数 === 快照.黑市刷新次数 && JSON.stringify(读.层出口选择) === 快照.层出口选择
      && JSON.stringify(读.层出口小径) === 快照.层出口小径 && JSON.stringify(读.事件已选) === 快照.事件已选
      && JSON.stringify(读.侵蚀源已净化) === 快照.侵蚀源已净化) {
    ok(`五个新字段都跟着存档往返一致：黑市刷新次数 ${读.黑市刷新次数}、层出口选择 ${JSON.stringify(读.层出口选择)}、层出口小径 ${JSON.stringify(读.层出口小径)}、事件已选 ${Object.keys(读.事件已选).length} 条、侵蚀源已净化 ${JSON.stringify(读.侵蚀源已净化)}`);
  } else bad(`新字段没存全：${JSON.stringify({ 读, 快照 })}`);
  /* 旧存档（加这些字段之前存的那一版）：删掉字段 + 塞坏值 → 读回来补默认值，不崩 */
  {
    const R2 = 开一局(20261161);
    delete R2.黑市刷新次数;
    delete R2.层出口选择;
    delete R2.层出口小径;
    delete R2.事件已选;
    delete R2.侵蚀源已净化;
    肉鸽.存档();
    肉鸽.RUN = null;
    const 旧 = 肉鸽.读存档();
    if (旧 && 旧.黑市刷新次数 === 0 && JSON.stringify(旧.层出口选择) === '{}' && Array.isArray(旧.层出口小径)
        && 旧.层出口小径.length === 0 && JSON.stringify(旧.事件已选) === '{}' && JSON.stringify(旧.侵蚀源已净化) === '{}') {
      ok('旧存档（一个字段都没有）读回来补成默认值：刷新次数 0、层出口选择 {}、层出口小径 []、事件已选 {}、侵蚀源已净化 {}，不崩');
    } else bad(`旧存档补默认值不对：${JSON.stringify(旧 && { 刷新: 旧.黑市刷新次数, 出口: 旧.层出口选择, 小径: 旧.层出口小径, 事件: 旧.事件已选, 净化: 旧.侵蚀源已净化 })}`);
    /* 坏值：字符串 / NaN / 数组塞进对象字段 */
    const R3 = 开一局(20261162);
    R3.黑市刷新次数 = '乱写';
    R3.层出口选择 = ['不是对象'];
    R3.层出口小径 = '不是数组';
    R3.事件已选 = 42;
    R3.侵蚀源已净化 = null;
    肉鸽.存档();
    肉鸽.RUN = null;
    const 坏 = 肉鸽.读存档();
    if (坏 && 坏.黑市刷新次数 === 0 && JSON.stringify(坏.层出口选择) === '{}' && Array.isArray(坏.层出口小径)
        && 坏.层出口小径.length === 0 && JSON.stringify(坏.事件已选) === '{}' && JSON.stringify(坏.侵蚀源已净化) === '{}') {
      ok('坏值也补成默认值（"乱写" / 数组 / 字符串 / 42 / null 都不会把界面弄崩）');
    } else bad(`坏值没补回来：${JSON.stringify(坏 && { 刷新: 坏.黑市刷新次数, 出口: 坏.层出口选择, 小径: 坏.层出口小径, 事件: 坏.事件已选, 净化: 坏.侵蚀源已净化 })}`);
    /* ★ 2026-10-12 地图大改：**存档升到 v4**（地图的形状 / 尺寸变了 —— 旧档的格号集合与新形状
       对不上：同一个格号在两套边长下是另一个坐标，读回来会走错格子，所以整个丢掉）。 */
    if (G.存档版本 === 4 && G.存档键 === 'mecha-autobattle-run-v4') ok(`存档版本升到 v${G.存档版本}（键 ${G.存档键}）—— 地图形状 / 尺寸变了，v1–v3 一律丢弃 + 清键`);
    else bad(`存档版本不对：v${G.存档版本} / ${G.存档键}`);
  }
  /* 新的一局就带着这五个字段（★ 2026-10-11 券系统又加了两个：`券` / `招募站已领券`）。
     这一段要的是**刚开局、还没招人**的状态，所以直接走 `肉鸽.新的一局()`（不走 `开一局()` ——
     那个助手会顺手把 3 张券花掉换人，券就不是初值了）。 */
  肉鸽.新的一局('无', 20261163);
  const R4 = 肉鸽.RUN;
  const 字段 = ['黑市刷新次数', '层出口选择', '层出口小径', '事件已选', '侵蚀源已净化', '券', '招募站已领券'];
  const 缺 = 字段.filter(f => !(f in R4));
  if (!缺.length) ok(`\`新的一局()\` 就把这七个字段带上了：${字段.join('、')}（节点改造五个 ＋ 券系统两个）`);
  else bad(`新的一局缺字段：${缺.join('、')}`);
  if (Array.isArray(R4.券) && R4.券.length === G.肉鸽数值.开局券数 && R4.招募站已领券.length === 0) {
    ok(`券那两个字段初值对：券 ${R4.券.length} 张（开局发的：${G.券汇总文字(R4)}）、招募站已领券 ${R4.招募站已领券.length} 条、名册 ${R4.队伍.length} 台（**空**）`);
  } else bad(`券字段初值不对：券 ${JSON.stringify(R4.券)} / 已领券 ${JSON.stringify(R4.招募站已领券)}`);
}

/* ============================ [19] 每个动作结算后，界面上看得到结果 ============================ */
/* ★ 2026-10-11「界面体验修复」（作者试玩：「现在很多事情结束以后，结果没有提示，这个需要改进，
 *   然后记录也需要显示」）—— 第 [19]/[20] 段就是这两条的机检验收。
 *   判据（都走玩家那条路：界面动作 → 结算 → 读 `#screen` 的 HTML）：
 *     ① `肉鸽界面.提示` = `{类型, 文本}`，类型在 `成功 / 警告 / 失败 / 信息` 里；
 *     ② 大地图屏顶部有一条 `.resbar`（`data-resbar="1"`）**固定**显示它，并且带类型配色类；
 *     ③ 同一句话**也在 `RUN.日志` 里**（记录屏读的就是它）。 */
console.log('\n[19] 每个动作结算后，界面上看得到结果（结果条 + 同一句话进 RUN.日志）');
{
  /** 从当前屏的 HTML 里抠出结果条那一条（玩家一眼能看到的就是这一条）。 */
  const 结果条 = () => {
    const m = /<p class="resbar ([a-z]+)" data-resbar="1"(?: data-res-type="([^"]*)")?>([\s\S]*?)<\/p>/.exec(屏文字());
    if (!m) return null;
    /* 结构是 `<b>类型</b><span>文本</span>`：抠出来的整段要去掉开头那个类型词 */
    const 全 = m[3].replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim();
    const 文本 = 全.replace(/^(成功|警告|失败|信息)\s*/, '');
    return { 类: m[1], 类型: m[2] || null, 文本 };
  };
  /* ★ 日志一律读**当前的** `肉鸽.RUN`（`开一局()` 会换一个新 RUN 对象，早先存下来的 R 会是旧的）。 */
  const 日志尾 = () => { const L = (肉鸽.RUN && 肉鸽.RUN.日志) || []; return L.length ? L[L.length - 1].文本 : ''; };

  /* --- ① 大地图顶部固定有一条结果条（还没有结果时也在，写着「还没有结果」） --- */
  let R = 开一局(20261070);
  肉鸽界面.清结果();                   // 这一段测「还没做事时」的样子：先把开局留下的结果清掉（口径 ②）
  界面.开屏('大地图');
  const 空条 = 结果条();
  if (空条 && 空条.类 === 'info' && /还没有结果/.test(空条.文本)) ok(`大地图顶部固定有结果条（还没做事时：${空条.文本}）`);
  else bad(`大地图顶部没有结果条：${JSON.stringify(空条)}`);
  if (/data-log-entry/.test(屏文字())) ok('大地图上有「记录」入口按钮（data-log-entry）');
  else bad('大地图上没有「记录」入口');

  /* --- ② 招募（用掉一张同类券 + 花希望 + 现在几台） ---
     ★ 2026-10-12 修真 bug：招募**必须持券**（不选券直接拒绝）→ 这里改成走玩家那条路：
     先在招募屏上选中一张对得上的券（`界面.用券`），再点候选（`界面.招募`）。 */
  界面.开屏('招募');
  R.希望 += 200;
  const 新键 = G.ALLY_T.map(t => t.mech).find(k => !R.队伍.some(m => m.键 === k));
  {
    let i = (R.券 || []).findIndex(c => G.券合(c, 新键));
    if (i < 0) {                       // 手上没有对得上的券 → 补一张（测试补券口子，招募那一步照旧走玩家路径）
      R.券.push({ 类: '职业', 名: G.tplOf(新键).tags.战斗分类, 档: null, 来源: '测试' });
      i = R.券.length - 1;
    }
    界面.用券(i);
  }
  const 希前 = R.希望;
  界面.招募(新键);
  const 招条 = 肉鸽界面.提示结果();
  if (招条 && 招条.类型 === '成功' && 招条.文本.includes(`花希望 ${希前 - R.希望}`) && 招条.文本.includes(`队伍`.replace('队伍', `队里 ${R.队伍.length}`))) {
    ok(`招募结算：结果条 = 「${招条.文本}」`);
  } else bad(`招募的结果条不对：${JSON.stringify(招条)}`);
  if (日志尾() === 招条.文本) ok('同一句话也写进了 RUN.日志（结果条与记录同源）');
  else bad(`结果条那句话没进日志：条「${招条.文本}」 vs 日志尾「${日志尾()}」`);
  界面.开屏('大地图');
  if (结果条() && 结果条().类型 === '成功' && 结果条().文本 === 招条.文本) ok('切回大地图后，顶部结果条显示的就是刚才那一条（切屏不清）');
  else bad(`切屏回来结果条变了：${JSON.stringify(结果条())}`);

  /* --- ③ 黑市买 / 刷新（花源碳） --- */
  const 黑 = 找格(R, '黑市');
  if (黑 == null) info('第 1 层这张图没有黑市，跳过黑市两条');
  else {
    R.源碳 = 60;
    肉鸽.跳格(黑);
    界面.去节点(黑);
    const 货0 = 肉鸽.黑市货();
    界面.黑市买(货0[0]);
    const 买条 = 肉鸽界面.提示结果();
    if (买条 && 买条.类型 === '成功' && /买下了【.+】（−\d+ 源碳/.test(买条.文本)) ok(`黑市买：结果条 = 「${买条.文本}」（类型 ${买条.类型}）`);
    else bad(`黑市买的结果条不对：${JSON.stringify(买条)}`);
    if (日志尾() === 买条.文本) ok('黑市买那句话也进了日志');
    else bad(`黑市买没进日志：${日志尾()}`);
    界面.黑市刷新();
    const 刷条 = 肉鸽界面.提示结果();
    if (刷条 && 刷条.类型 === '成功' && /花 \d+ 源碳刷新（第 \d+ \/ \d+ 次）/.test(刷条.文本)) ok(`黑市刷新：结果条 = 「${刷条.文本}」`);
    else bad(`黑市刷新的结果条不对：${JSON.stringify(刷条)}`);
    /* 买不起 → 红条 + 写清为什么（源碳是 0） */
    R.源碳 = 0;
    const 贵货 = 肉鸽.黑市货()[0];
    界面.黑市买(贵货);
    const 穷条 = 肉鸽界面.提示结果();
    if (穷条 && 穷条.类型 === '失败' && 穷条.文本.length > 4) ok(`黑市买不起：红条写明原因 —— 「${穷条.文本}」`);
    else bad(`黑市买不起没有红条：${JSON.stringify(穷条)}`);
    界面.黑市离开();
  }

  /* --- ④ 瞭望站 / 遗迹 / 休整 / 隧道 / 事件（各抽一条，弹窗同步给答案） --- */
  R = 开一局(20261071);
  R.层 = 2; R.场次 = 0;
  R.地图 = G.生成层(2, G.地图种子(R.种子, 2));
  R.当前 = R.地图.起点; R.推进剂 = 60;
  const 试弹窗 = (格类型, 答案, 调用) => {
    const k = Object.keys(R.地图.格).map(Number).find(x => R.地图.格[x].类型 === 格类型) ;
    if (k == null) return null;
    肉鸽.跳格(k);
    界面.对话框钩子 = () => 答案;
    调用();
    界面.对话框钩子 = null;
    return 肉鸽界面.提示结果();
  };
  const 瞭 = 试弹窗('瞭望站', '登高', () => 界面.去瞭望());
  if (瞭 && /瞭望站（登高）/.test(瞭.文本) && 瞭.类型 === '信息') ok(`瞭望站：结果条 = 「${瞭.文本}」`);
  else bad(`瞭望站没有结果：${JSON.stringify(瞭)}`);
  const 遗 = 试弹窗('遗迹', '藤蔓', () => 界面.去遗迹());
  if (遗 && /遗迹（清理门口的藤蔓）/.test(遗.文本) && 遗.类型 === '成功') ok(`遗迹三选一：结果条 = 「${遗.文本}」`);
  else bad(`遗迹没有结果：${JSON.stringify(遗)}`);
  const 休 = 试弹窗('休整', '耐久', () => 界面.休整());
  if (休 && /休整完了（耐久）/.test(休.文本)) ok(`休整：结果条 = 「${休.文本}」`);
  else bad(`休整没有结果：${JSON.stringify(休)}`);
  /* 隧道（成对才有） */
  if (R.地图.隧道 && R.地图.隧道.length === 2) {
    肉鸽.跳格(R.地图.隧道[0]);
    界面.对话框钩子 = () => 'go';
    界面.穿隧道();
    界面.对话框钩子 = null;
    const 隧 = 肉鸽界面.提示结果();
    if (隧 && /穿过隧道（花 \d+ 推进剂/.test(隧.文本)) ok(`隧道：结果条 = 「${隧.文本}」`);
    else bad(`隧道没有结果：${JSON.stringify(隧)}`);
  } else info('这张图没有成对隧道，跳过隧道那条');
  /* 事件（选项结算；成功与失败各看一条） */
  const 事格 = Object.keys(R.地图.格).map(Number).find(x => R.地图.格[x].类型 === '事件');
  if (事格 != null) {
    肉鸽.跳格(事格);
    界面.开屏('奇遇');
    界面.动作('奇遇:0');
    const 事 = 肉鸽界面.提示结果();
    if (事 && /事件「/.test(事.文本)) ok(`事件选项：结果条 = 「${事.文本}」`);
    else bad(`事件没有结果：${JSON.stringify(事)}`);
  } else info('这张图没有事件格，跳过事件那条');

  /* --- ⑤ 晋升（成功一条 + 缺券失败一条） --- */
  R = 开一局(20261072);
  R.希望 += 200;
  界面.去晋升();
  const 谁 = R.队伍[0].键;
  const 卷前 = (R.券 || []).length;
  if (卷前 === 0) {
    界面.晋升(谁);
    const 缺 = 肉鸽界面.提示结果();
    if (缺 && 缺.类型 === '失败' && /没有可用的同类券/.test(缺.文本)) ok(`晋升缺券：红条写明原因 —— 「${缺.文本}」`);
    else bad(`晋升缺券没有红条：${JSON.stringify(缺)}`);
    if (R.队伍[0].等级 === G.肉鸽数值.招募等级 && R.希望 === 200 + 8 + 0 - 0) info('（缺券时希望一分没扣，等级也没动）');
  } else info(`这一局开局自带 ${卷前} 张券，跳过「缺券」那条`);
  /* 真有对得上的券时，晋升成功要给「花了多少希望 + 用掉哪张券 + 现在的等级」 */
  {
    const 目标 = R.队伍[0].键;
    /* 开局那 3 张券不一定对得上这台机体 —— 手写一张对得上的（照战棋 `27-开局.js:77`
       「同职业或同势力」的口径），这样这一段在**任何种子**下都真的跑到「晋升成功」那条路。
       形状：`{类:'职业', 名:<这台机体的战斗分类>, 档:null, 来源:'测试'}`（`券合()` 只认这几个字段）。 */
    if (!G.找同类券(R, 目标)) G.发券(R, '职业', '测试', (G.tplOf(目标).tags || {}).战斗分类, 0);
    const 找 = G.找同类券(R, 目标);
    const 希 = R.希望;
    if (找) {
      界面.晋升(目标);
      const 升 = 肉鸽界面.提示结果();
      if (升 && 升.类型 === '成功' && /晋升到 Lv\d+（−\d+ 希望，剩 \d+；用掉一张 .+）：HP \d+ → \d+/.test(升.文本)) {
        ok(`晋升：结果条 = 「${升.文本}」（希望 ${希} → ${R.希望}）`);
      } else bad(`晋升的结果条不对：${JSON.stringify(升)}`);
      if (日志尾() === 升.文本) ok('晋升那句话也进了日志');
      else bad('晋升没进日志');
    } else bad(`造不出对得上的券：${目标}`);
  }

  /* --- ⑥ 丢券（成功一条；手上没券就先造一张，免得这一段被开局随机券的运气跳过） --- */
  {
    if (!(R.券 || []).length) G.发券(R, '职业', '测试', (G.tplOf(R.队伍[0].键).tags || {}).战斗分类, 1);
    const 数前 = R.券.length;
    界面.丢券(0);
    const 丢 = 肉鸽界面.提示结果();
    if (丢 && 丢.类型 === '警告' && 丢.文本.includes(`手上还剩 ${R.券.length} 张`) && R.券.length === 数前 - 1) {
      ok(`丢券：结果条 = 「${丢.文本}」`);
    } else bad(`丢券的结果条不对：${JSON.stringify(丢)}`);
    if (日志尾() === 丢.文本) ok('丢券那句话也进了日志');
    else bad('丢券没进日志');
  }

  /* --- ⑦ 走不过去 / 出口被守军挡着（失败条 + 警告条） ---
     ★ 2026-10-12 地图大改：正方形小图上推进剂往往够走遍全图，所以这里**按 BFS 距离**挑一个
       真的超过推进剂的格（不再用「不在能去的里」这种间接判据 —— 那种格现在可能压根不存在）。 */
  R = 开一局(20261073);
  界面.开屏('大地图');
  const 距表 = G.全距离(R);
  const 去不了 = Object.keys(R.地图.格).map(Number)
    .filter(k => k !== R.当前 && (距表.get(k) ?? 999) > R.推进剂)
    .sort((a, b) => (距表.get(b) ?? 0) - (距表.get(a) ?? 0))[0];
  if (去不了 == null) {
    info(`这一层推进剂 ${R.推进剂} 够走到每一格（正方形小图），跳过「走不过去」的红条检查`);
  } else {
    界面.去节点(去不了);
    const 走条 = 肉鸽界面.提示结果();
    if (走条 && 走条.类型 === '失败' && /走不过去/.test(走条.文本)) ok(`走不过去：红条 = 「${走条.文本}」（${坐标(去不了)} 要 ${距表.get(去不了)} 步 > 推进剂 ${R.推进剂}）`);
    else bad(`走不过去没有红条：${JSON.stringify(走条)}`);
  }
  肉鸽.跳格(R.地图.出口尽头);
  界面.前进('尽头');
  const 挡条 = 肉鸽界面.提示结果();
  if (挡条 && 挡条.类型 === '警告' && /出口被守军挡着/.test(挡条.文本)) ok(`出口被守军挡着：警告条 = 「${挡条.文本}」`);
  else bad(`出口被守军挡着没有警告条：${JSON.stringify(挡条)}`);

  /* --- ⑧ 换层（口径 ①：换层清掉上一条，再写这一层的新结果） --- */
  R = 开一局(20261060);
  肉鸽.跳格(R.地图.出口尽头);
  清掉守军(R);
  R.推进剂 = 5;
  肉鸽界面.设结果('成功', '换层之前那一条（应该被清掉）');
  界面.前进('尽头');
  const 换 = 肉鸽界面.提示结果();
  if (R.层 === 2 && 换 && 换.类型 === '信息' && /走了出口尽头/.test(换.文本)) ok(`换层清旧结果、写新结果：「${换.文本}」`);
  else bad(`换层之后的结果条不对：${JSON.stringify(换)}`);
  /* --- ⑨ 战斗结算清单：`肉鸽.战斗结束()` 的返回值渲染成「希望 +N / 源碳 +N / 券【X】/ 零件【Y】/ 藏品【Z】」 ---
   *   真实一场（打赢 / 打输）的**奖励字段是随机的**（零件只有精英 / Boss 必给、藏品只有精英 / Boss 发），
   *   所以这里分两步：① 真的打一场（守军 = 精英档）拿到真返回值，验「清单出现 + 里面至少三种东西」
   *   （作者的验收口径就是「至少三种」）；② 再把五样摆齐的一次返回值直接设上去，验清单把五样都画出来。 */
  {
    const 清单文字 = () => {
      const m = /<div class="battle-res[^"]*" data-battle-res="1">([\s\S]*?)<\/div>/.exec(屏文字());
      return m ? m[1].replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim() : null;
    };
    /* ① 真打一场：拿真返回值 + 数清单里有几样（希望 / 源碳 / 券 / 零件 / 藏品） */
    {
      const R9 = 开一局(20261030);
      R9.层 = 4; R9.场次 = 0;
      R9.地图 = G.生成层(4, G.地图种子(R9.种子, 4));
      R9.当前 = R9.地图.起点; R9.推进剂 = 60;
      界面.去节点(R9.地图.守军);
      界面.编队.出击 = R9.队伍.slice(0, 3).map((m, i) => ({ 键: m.键, 位: i }));
      界面.动作('开战');
      界面.ctx.enemies.forEach(e => { e.maxHp = 1; e.hp = 1; });
      界面.ctx.allies.forEach(u => { u.maxHp = 10000000; u.hp = 10000000; });
      界面.ctx.波次 = [];
      打完这一场();
      const 真 = 肉鸽界面.战斗结算;
      const 一件数 = 真 ? ['希望', '源碳', '券', '零件', '藏品'].filter(k => 真[k] != null).length : 0;
      if (真 && 真.胜 && 一件数 >= 3) ok(`真打一场（出口守军 = 精英档）拿到 ${一件数} 样：${G.战斗奖励清单文字(真)}`);
      else bad(`真打一场的奖励对象不对：${JSON.stringify(真)}`);
      /* 真实那一场的结果条上也写着同一份账 */
      const 条9 = /<p class="resbar [a-z]+" data-resbar="1"[^>]*>([\s\S]*?)<\/p>/.exec(屏文字());
      const 条文 = 条9 ? 条9[1].replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim() : '';
      if (/胜利/.test(条文) && /希望 \+\d+/.test(条文)) ok(`战斗结束的结果条：「${条文}」`);
      else bad(`战斗结束的结果条不对：${条文}`);
      /* ② 五样摆齐：直接设一次返回值，走到出口尽头 → 本局结算屏上要看到清单 */
      肉鸽界面.战斗结算 = { 胜: true, 希望: 6, 源碳: 5, 券: { 类: '职业', 名: '近卫', 档: null, 来源: '战后' },
        零件: { 名: '报废假肢' }, 藏品: { 名: '格斗教范' }, 额外源碳: 6, 守军已清: true };
      界面.去节点(R9.地图.出口尽头);
      if (界面.屏 === '肉鸽结算') {
        const 全 = 清单文字();
        const 齐 = ['希望 +6', '源碳 +5', '券【近卫招募券】', '零件【报废假肢】', '藏品【格斗教范】'].filter(x => 全 && 全.includes(x));
        if (齐.length === 5) ok(`本局结算屏上的战斗奖励清单（五样齐）：${全}`);
        else bad(`奖励清单少了：${JSON.stringify({ 清单: 全, 有: 齐 })}`);
        if (/data-resbar="1"/.test(屏文字())) ok('本局结算屏顶上也有结果条（通关那句话 + 上一场的账）');
        else bad('本局结算屏上没有结果条');
      } else bad(`没走到本局结算屏：${界面.屏}（本局结局 ${R9.结局}）`);
    }
    /* ③ 失败那一场：清单换成「作战耐久 −N」（不编奖励数字） */
    {
      const R10 = 开一局(20261070);
      const 作10 = 肉鸽.能去的().map(n => n.k).find(k => ['作战', '精英'].includes(R10.地图.格[k].类型));
      界面.去节点(作10);
      界面.编队.出击 = R10.队伍.slice(0, 3).map((m, i) => ({ 键: m.键, 位: i }));
      界面.动作('开战');
      界面.ctx.enemies.forEach(e => { e.maxHp = 10000000; e.hp = 10000000; });
      界面.ctx.allies.forEach(u => { u.maxHp = 1; u.hp = 1; });
      界面.ctx.波次 = [];
      打完这一场();
      const 败 = 肉鸽界面.战斗结算;
      if (败 && 败.胜 === false && 败.扣 > 0) ok(`打输那一场：返回值 = ${JSON.stringify(败)}`);
      else bad(`打输那一场的返回值不对：${JSON.stringify(败)}`);
      if (G.战斗奖励清单文字(败).includes(`作战耐久 −${败.扣}`)) ok(`失败清单写的是付出：「${G.战斗奖励清单文字(败)}」`);
      else bad(`失败清单不对：${G.战斗奖励清单文字(败)}`);
      const 条10 = /<p class="resbar ([a-z]+)" data-resbar="1"[^>]*>([\s\S]*?)<\/p>/.exec(屏文字());
      if (条10 && 条10[1] === 'bad' && /失败/.test(条10[2])) ok('打输那一场的结果条是红条（失败）');
      else bad(`打输那一场的结果条不对：${条10 ? 条10[1] : '没找到'}`);
    }
  }

  /* --- ⑩ 〔…〕前缀的日志：记录屏把它当「类型」写进前缀（沿用日志里已有的结构） --- */
  {
    const R11 = 开一局(20261076);
    R11.日志 = [];
    肉鸽.记('〔势力〕月球王国：残月的余响 追加 1 发（每回合上限 1）');
    肉鸽.记('〔Boss〕蓝色大肥鱼：蓄力中（第 4 回合释放【周身冲击】）');
    R11.日志.push({ 层: 2, 文本: '这一条没有前缀', 时间: 0 });
    界面.开屏('记录');
    const 前 = [...屏文字().matchAll(/<span class="tag">([^<]*)<\/span>/g)].map(m => m[1]);
    if (前.length === 3 && 前[0] === '第 2 层 · 日志' && 前[1] === '第 1 层 · Boss' && 前[2] === '第 1 层 · 势力') {
      ok(`〔…〕前缀被当类型写进记录行：${前.join(' | ')}`);
    } else bad(`〔…〕前缀没认出来：${JSON.stringify(前)}`);
  }
}

/* ============================ [20] 记录屏（入口 / 排序 / 上限 / 空日志） ============================ */
console.log('\n[20] 记录屏：RUN.日志 有地方看（最新在前 / 条数上限 / 空日志不崩）');
{
  const 行数 = () => (屏文字().match(/data-log-line="1"/g) || []).length;
  const 行们 = () => [...屏文字().matchAll(/<div class="logline" data-log-line="1">[\s\S]*?<span class="tx">([\s\S]*?)<\/span><\/div>/g)].map(m => m[1]);

  /* --- ① 入口：大地图上点「记录」按钮 → 记录屏 --- */
  const R = 开一局(20261074);
  界面.开屏('大地图');
  const 入口 = /<button data-act="去记录" data-log-entry="1">记录（(\d+) 条）<\/button>/.exec(屏文字());
  if (入口 && Number(入口[1]) === R.日志.length) ok(`大地图的「记录」按钮上写着条数（记录（${入口[1]} 条），和 RUN.日志 一致）`);
  else bad(`记录按钮不对：${入口 ? 入口[0] : '没找到'}（RUN.日志 ${R.日志.length} 条）`);
  界面.动作('去记录');
  if (界面.屏 === '记录' && /data-logbox="1"/.test(屏文字())) ok('点「记录」进了记录屏，里面是可滚动的日志框（.logbox / data-logbox）');
  else bad(`记录屏没打开：屏 ${界面.屏}`);

  /* --- ② 排序：最新在前；每条带「第 N 层 · 类型」前缀 --- */
  const 日志 = R.日志;
  const 画了 = 行们();
  if (画了.length === 日志.length && 画了.length > 0) ok(`记录屏列出了 RUN.日志 的全部 ${画了.length} 条`);
  else bad(`记录屏列了 ${画了.length} 条，RUN.日志 是 ${日志.length} 条`);
  if (画了[0] === 日志[日志.length - 1].文本 && 画了[画了.length - 1] === 日志[0].文本) ok(`排序 = 最新在前（第一条「${画了[0]}」、最后一条「${画了[画了.length - 1]}」）`);
  else bad(`排序不对：第一条「${画了[0]}」、最后一条「${画了[画了.length - 1]}」`);
  const 前缀们 = [...屏文字().matchAll(/<span class="tag">([^<]*)<\/span>/g)].map(m => m[1]);
  if (前缀们.length === 画了.length && 前缀们.every(x => /^第 \d+ 层 · .+$/.test(x))) {
    ok(`每条都带「层 · 类型」前缀（例：「${前缀们[0]}」「${前缀们[1] || '—'}」）`);
  } else bad(`前缀不对：${JSON.stringify(前缀们.slice(0, 3))}`);
  /* 〔…〕前缀的日志会把它当类型挑出来 */
  const 带前缀 = 日志.find(x => /^〔[^〕]+〕/.test(x.文本));
  if (带前缀) {
    const 行 = [...屏文字().matchAll(/<span class="tag">([^<]*)<\/span><span class="idx">#\d+<\/span><span class="tx">([^<]*)<\/span>/g)]
      .find(m => m[2] === 带前缀.文本);
    const 期望 = /^〔([^〕]+)〕/.exec(带前缀.文本)[1];
    if (行 && 行[1].includes(期望)) ok(`带 〔…〕 的日志把它当类型写进前缀（「${行[1]}」）`);
    else bad(`〔…〕 前缀没被认出来：${行 ? 行[1] : '没找到'}（期望含 ${期望}）`);
  } else info('这一局的日志里没有 〔…〕 前缀，跳过那条');

  /* --- ③ 上限：内存 300（超了从最老的截），屏幕只画最近 200 --- */
  if (肉鸽.日志上限 === 300 && G.记录屏条数上限 === 200) ok(`条数上限写死且一致：RUN.日志 上限 ${肉鸽.日志上限} 条、记录屏画最近 ${G.记录屏条数上限} 条`);
  else bad(`上限不对：肉鸽.日志上限 ${肉鸽.日志上限} / 记录屏条数上限 ${G.记录屏条数上限}`);
  R.日志 = [];
  for (let i = 0; i < 400; i++) 肉鸽.记('压测第 ' + i + ' 条');
  if (R.日志.length === 肉鸽.日志上限 && R.日志[0].文本 === '压测第 100 条' && R.日志[R.日志.length - 1].文本 === '压测第 399 条') {
    ok(`超长日志按上限截断：写 400 条 → 留最近 ${R.日志.length} 条（最老的 100 条被丢掉，首条「${R.日志[0].文本}」）`);
  } else bad(`截断不对：${R.日志.length} 条，首条「${R.日志[0] && R.日志[0].文本}」`);
  界面.开屏('记录');
  if (行数() === G.记录屏条数上限) ok(`屏幕按上限画：${行数()} 行 = 记录屏条数上限 ${G.记录屏条数上限}`);
  else bad(`屏幕画了 ${行数()} 行（上限 ${G.记录屏条数上限}）`);
  /* 存档别失控：存的是那个被截断的数组（300 条），不是整本 */
  肉鸽.存档();
  const 存 = JSON.parse(page.sandbox.localStorage.getItem(G.存档键));
  if (存 && 存.RUN.日志.length === 肉鸽.日志上限) ok(`存档里也只有 ${存.RUN.日志.length} 条（不把整本日志塞进 localStorage）`);
  else bad(`存档里的日志条数不对：${存 && 存.RUN.日志.length}`);

  /* --- ④ 空日志：给一句「还没有记录」，不崩 --- */
  const R2 = 开一局(20261075);
  R2.日志 = [];
  界面.开屏('记录');
  if (/data-log-empty="1"/.test(屏文字()) && /还没有记录/.test(屏文字()) && 行数() === 0) ok('空日志：给一句「还没有记录」，一屏不崩、也不画空框');
  else bad('空日志那句没出现');
  /* 坏值（不是数组）也不崩 */
  R2.日志 = '不是数组';
  界面.开屏('记录');
  if (界面.屏 === '记录' && /还没有记录/.test(屏文字())) ok('日志被写成坏值（字符串）也不崩，按空日志处理');
  else bad('坏值日志把记录屏弄崩了');

  /* --- ⑤ 没有 RUN（练习模式那条路）：记录屏给「还没有进行中的局」，不抛异常 --- */
  {
    const 留 = 肉鸽.RUN;
    肉鸽.RUN = null;
    const h = 界面.记录屏();
    if (typeof h === 'string' && h.includes('还没有进行中的局')) ok('没有 RUN 时记录屏给一句「还没有进行中的局」（练习模式 / 平衡工具那条路不受影响）');
    else bad('没有 RUN 时记录屏不对');
    肉鸽.RUN = 留;
  }

  /* --- ⑥ 通关之后仍然看得到这一局的记录（作者要的「记录也要显示」） --- */
  {
    const R3 = 开一局(20261030);
    R3.层 = 4; R3.场次 = 0;
    R3.地图 = G.生成层(4, G.地图种子(R3.种子, 4));
    R3.当前 = R3.地图.起点; R3.推进剂 = 60;
    界面.去节点(R3.地图.守军);
    界面.编队.出击 = R3.队伍.slice(0, 3).map((m, i) => ({ 键: m.键, 位: i }));
    界面.动作('开战');
    界面.ctx.enemies.forEach(e => { e.maxHp = 1; e.hp = 1; });
    界面.ctx.allies.forEach(u => { u.maxHp = 10000000; u.hp = 10000000; });
    界面.ctx.波次 = [];
    打完这一场();
    界面.去节点(R3.地图.出口尽头);
    if (界面.屏 === '肉鸽结算') {
      if (/data-act="去记录"/.test(屏文字())) ok('本局结算屏上也有「看这局的记录」入口');
      else bad('结算屏上没有记录入口');
      界面.动作('去记录');
      if (界面.屏 === '记录' && 行数() > 0) ok(`通关之后还能翻这一局的记录（${行数()} 行，日志 ${R3.日志.length} 条）`);
      else bad(`通关后记录屏打不开：屏 ${界面.屏}、${行数()} 行`);
    } else bad(`这一局没走到通关屏：${界面.屏} / 结局 ${R3.结局}`);
  }
}

/* ============================ [21] 肉鸽里的「本场战报」（三层反馈的结算那一层） ============================
 * 作者 2026-10-12 拍板的第 2 件「三层反馈」：**肉鸽里同样显示**，并且**每一行都写进 `RUN.日志`**
 * （§2.4 原话「肉鸽里同样显示，记录写进 RUN.日志」）。判据：
 *   ① 打完一场（胜 / 败都算）→ `肉鸽界面.战斗战报` = `战报行们(界面.战报)`（一行一条）；
 *   ② 回到大地图（打完一场自动回）→ 屏上有那一块 `data-battle-report="1"`，行数与内容**逐字**对得上；
 *   ③ 同一批行**也在 `RUN.日志` 里**（前缀 `〔战报〕`，记录屏上翻得到）；
 *   ④ 本局结算屏上也有；⑤ 空 / 异常数据不崩；⑥ 同种子两次逐字相同。 */
console.log('\n[21] 肉鸽战斗也出「本场战报」，并写进 RUN.日志（§2.2 结算列 / §2.4）');
{
  const 战报行们 = () => [...屏文字().matchAll(/<li data-report-line="1">([\s\S]*?)<\/li>/g)].map(m => m[1].replace(/<[^>]*>/g, '').trim());
  /* ★ 2026-10-13 日志瘦身（任务书 §(b)）：`〔战报〕` 的那些行**并进了战斗结算那一行**（用 ` · ` 连着），
     所以「日志里的战报」不再是一条条独立的日志条目 —— 这里按 ` · ` 拆开、只挑 `〔战报〕` 开头的段。 */
  const 日志里的战报 = R => (R.日志 || []).map(x => String(x.文本))
    .flatMap(t => t.split(' · ').filter(s => s.startsWith('〔战报〕')).map(s => s.slice('〔战报〕'.length)));
  /** 这一场战斗往 `RUN.日志` 写了几条（`打一场()` 里算，用来钉「每场 ≤2 行」）。 */
  let 本场行数 = 0;
  /** 走玩家的路：开一局 → 点一个战斗格 → 摆 3 台 → 开战 →（作弊保证胜负）→ 打完 */
  const 打一场 = (种子, 胜负) => {
    const R = 开一局(种子);
    const 格 = 肉鸽.能去的().map(n => n.k).find(k => ['作战', '精英', '侵蚀源'].includes(R.地图.格[k].类型));
    界面.去节点(格);
    界面.编队.出击 = R.队伍.slice(0, 3).map((m, i) => ({ 键: m.键, 位: i }));
    界面.动作('开战');
    if (胜负 === '胜') {
      界面.ctx.enemies.forEach(e => { e.maxHp = 1; e.hp = 1; });
      界面.ctx.allies.forEach(u => { u.maxHp = 10000000; u.hp = 10000000; });
    } else {
      界面.ctx.enemies.forEach(e => { e.maxHp = 10000000; e.hp = 10000000; });
      界面.ctx.allies.forEach(u => { u.maxHp = 1; u.hp = 1; });
    }
    界面.ctx.波次 = [];
    const 前 = R.日志.length;
    打完这一场();
    本场行数 = R.日志.length - 前;
    return R;
  };

  /* --- ① 胜的那一场：战报存下来 + 大地图上画出来 + 进日志 --- */
  let R = 打一场(20261070, '胜');
  if (界面.屏 === '大地图') ok(`打完一场回到大地图（结果：${(肉鸽界面.提示结果() || {}).文本}）`);
  else bad(`打完没回大地图：${界面.屏}`);
  /* ★ 2026-10-13（任务书 §(b)）：**这一场在 `RUN.日志` 里只占 ≤2 条**（一条结算 + 一条结果条/战报合并行）。 */
  if (本场行数 > 0 && 本场行数 <= 2) ok(`★ 这一场在 \`RUN.日志\` 里只占 **${本场行数} 条**（≤2：结算 + 战报 / 结果条）`);
  else bad(`这一场写了 ${本场行数} 条日志（要 ≤2）`);
  const 战报 = 肉鸽界面.战斗战报;
  if (Array.isArray(战报) && 战报.length >= 2 && 战报.every(x => typeof x === 'string' && x.length)) {
    ok(`这一场的本场战报存下来了：${战报.length} 行 —— \n      · ${战报.join('\n      · ')}`);
  } else bad(`肉鸽里的战报不对：${JSON.stringify(战报)}`);
  const 屏行 = 战报行们();
  if (/data-battle-report="1"/.test(屏文字()) && 屏行.length === 战报.length && 屏行.every((x, i) => x === 战报[i])) {
    ok(`大地图上画出了那一块（\`data-battle-report\`），${屏行.length} 行与 \`肉鸽界面.战斗战报\` **逐字相同**`);
  } else bad(`大地图上的战报块不对：${JSON.stringify(屏行)}`);
  const 日志行 = 日志里的战报(R);
  if (日志行.length === 战报.length && 日志行.every((x, i) => x === 战报[i])) {
    ok(`${战报.length} 行**全部写进了 \`RUN.日志\`**（前缀 \`〔战报〕\`；★ 2026-10-13 起并进战斗结算那一行里，用 \` · \` 连着，不再各占一条）`);
  } else bad(`日志里的战报对不上：${JSON.stringify(日志行)}`);
  /* 记录屏上翻得到（这一局里做的每一件事都在那儿） */
  界面.动作('去记录');
  const 记录行 = [...屏文字().matchAll(/<div class="logline" data-log-line="1">[\s\S]*?<span class="tx">([\s\S]*?)<\/span><\/div>/g)].map(m => m[1]);
  const 记录里战报段数 = 记录行.reduce((a, t) => a + t.split('〔战报〕').length - 1, 0);
  if (界面.屏 === '记录' && 记录里战报段数 === 战报.length) {
    ok(`记录屏上也翻得到这 ${战报.length} 段（前缀「战报」）；同一句话两处落地`);
  } else bad(`记录屏上看不到战报：${记录里战报段数} vs ${战报.length}`);

  /* --- ② 败的那一场也出（胜败都给） --- */
  R = 打一场(20261071, '败');
  const 败战报 = 肉鸽界面.战斗战报;
  if (Array.isArray(败战报) && 败战报.length >= 2 && 日志里的战报(R).length === 败战报.length) {
    info(`败的那一场也出了战报（${败战报.length} 行）：${败战报[0]}`);
    ok('肉鸽战斗无论胜败都写战报（和「结果条」同一个生命周期）');
  } else bad(`败的那一场没出战报：${JSON.stringify(败战报)}`);

  /* --- ③ 本局结算屏上也有一块 --- */
  {
    const R3 = 开一局(20261030);
    R3.层 = 4; R3.场次 = 0;
    R3.地图 = G.生成层(4, G.地图种子(R3.种子, 4));
    R3.当前 = R3.地图.起点; R3.推进剂 = 60;
    界面.去节点(R3.地图.守军);
    界面.编队.出击 = R3.队伍.slice(0, 3).map((m, i) => ({ 键: m.键, 位: i }));
    界面.动作('开战');
    界面.ctx.enemies.forEach(e => { e.maxHp = 1; e.hp = 1; });
    界面.ctx.allies.forEach(u => { u.maxHp = 10000000; u.hp = 10000000; });
    界面.ctx.波次 = [];
    打完这一场();
    const 通关战报 = 肉鸽界面.战斗战报;
    界面.去节点(R3.地图.出口尽头);
    if (界面.屏 === '肉鸽结算' && 战报行们().length === 通关战报.length && 战报行们().every((x, i) => x === 通关战报[i])) {
      ok(`本局结算屏上也贴着那一块（${通关战报.length} 行，与最后一场的战报逐字相同）`);
    } else bad(`本局结算屏上没有战报块：屏 ${界面.屏} / ${JSON.stringify(战报行们())}`);
  }

  /* --- ④ 空 / 异常数据不崩：没战报时那一块整块不画 --- */
  {
    开一局(20261031);
    肉鸽界面.清结果();                 // 开新局会清：结果条与上一场的战报一起清
    if (!肉鸽界面.战斗战报 && !/data-battle-report="1"/.test(屏文字())) ok('新开一局 / 清结果之后：没有战报，大地图上**整块都不画**（不挂一块空的）');
    else bad(`新局还挂着战报块：${JSON.stringify(肉鸽界面.战斗战报)}`);
    肉鸽界面.战斗战报 = null; 界面.开屏('大地图');
    if (!/data-battle-report="1"/.test(屏文字())) ok('`战斗战报 = null` 时大地图照样不画那一块（不崩）');
    else bad('null 时还画了战报块');
    肉鸽界面.战斗战报 = ['手写的一行'];
    界面.开屏('大地图');
    if (/data-battle-report="1"/.test(屏文字()) && 战报行们().includes('手写的一行')) ok('把 `战斗战报` 直接塞一行进去也照画（纯展示，不依赖引擎）');
    else bad('手写一行没画出来');
    肉鸽界面.清结果();
    let 崩 = null;
    try { G.战报行们(null); G.战报统计({}); G.本场战报Html(null); G.集中攻击预告({}); } catch (e) { 崩 = e && e.message; }
    if (!崩) ok('战报相关的纯函数对 null / {} 都不崩');
    else bad(`空数据崩了：${崩}`);
  }

  /* --- ⑤ 同种子两次：同一场战斗的战报逐字相同 --- */
  {
    const 甲 = 打一场(20261070, '胜'); const 甲报 = JSON.stringify(肉鸽界面.战斗战报); const 甲行 = 日志里的战报(甲);
    const 乙 = 打一场(20261070, '胜'); const 乙报 = JSON.stringify(肉鸽界面.战斗战报); const 乙行 = 日志里的战报(乙);
    if (甲报 === 乙报 && 甲行.join('｜') === 乙行.join('｜') && JSON.parse(甲报).length >= 2) {
      ok(`同种子两次（各 ${甲行.length} 行）两次的战报**逐字相同**（「${JSON.parse(甲报)[0]}」）`);
    } else bad(`同种子两次的战报不一样：\n     甲 ${甲报}\n     乙 ${乙报}`);
  }
}

/* ============================ [22] 「迷路的机师」不再是白送：花 4 源碳结晶换一张随机招募券 ============================
 * 作者 2026-10-12 试玩后点名（原话：「这个事件非常蠢，不能免费送，应该是花 4 个源碳结晶收一个随机的招募券」）。
 * 为什么放在 `tests/map.js` 而不是新开一套：事件表 / 事件节点 / `RUN.事件已选` 存档 / 结果条**都在这一套**
 *   （第 [12] 段就是事件段，[19] 是结果条），而且现成的 `开一局` / `站到` / `屏文字` 工具全在这儿。
 * 判据（一条不删、只加）：
 *   ① 表里那一条已经换成「花 4 源碳结晶 → 一张随机招募券」：白送机师、白给源碳两条路都没了；
 *   ② 源碳 3 → **选不了**（引擎 `ok=false` + 理由；界面按钮 `disabled` + 屏上可见理由），
 *      **源碳一分不变、券一张不发、名册一台不加**；
 *   ③ 源碳 4 → 能选：**源碳 −4、券 +1（来源 = `事件`）、名册不变**；
 *   ④ 券的类别 / 名字**同种子两遍逐字相同**（连开局 3 张券在内，整份 `RUN.券` 逐字相同）；
 *   ⑤ 没有 RUN / 坏数据（源碳是字符串 / NaN / null / {}）**不崩**；
 *   ⑥ 三层反馈都在：预告（按钮文案）/ 即时（结果条）/ 结算（`RUN.日志`）。 */
console.log('\n[22] 「迷路的机师」：花 4 源碳结晶换一张随机招募券（作者 2026-10-12 试玩后点名）');
{
  const 事 = G.事件表.find(e => e.名 === '迷路的机师');
  const 价 = G.肉鸽数值.机师换券源碳;
  const 做不了 = G.事件选项做不了;
  const 选文 = '花 4 源碳结晶 → 一张随机招募券';
  /* 找一个「第 2 层的某个事件格正好抽到迷路的机师」的种子（抽签口径 = `mulberry32(种子 + 层×811 + 格号×23)`）。 */
  const 命中 = (() => {
    const 迷路下标 = G.事件表.findIndex(e => e.名 === '迷路的机师');
    for (let 种子 = 20262001; 种子 < 20262700; 种子++) {
      const m = G.生成层(2, G.地图种子(种子 >>> 0, 2));
      for (const k of Object.keys(m.格).map(Number)) {
        if (m.格[k].类型 !== '事件') continue;
        const r = G.mulberry32(((种子 >>> 0) + 2 * 811 + k * 23) >>> 0);
        if (Math.floor(r() * G.事件表.length) === 迷路下标) return { 种子: 种子 >>> 0, k };
      }
    }
    return null;
  })();
  /** 站到「迷路的机师」那一格（第 2 层）—— 每一步都走玩家那条路（开一局 → 进层 → 站到格上）。 */
  const 站到迷路 = (种子) => {
    const R = 开一局(种子);
    肉鸽.进层(2);
    R.当前 = 命中.k;
    R.地图.格[命中.k] = { 类型: '事件', 已过: false };
    return R;
  };
  if (!事 || !命中) {
    bad(`找不到「迷路的机师」事件，或者找不到能命中它的（种子 / 格号）：${JSON.stringify({ 有事: !!事, 命中 })}`);
  } else {
    /* --- ① 表里那一条换掉了：白送机师 / 白给源碳都没了 --- */
    const 文案 = 事.选.map(o => o.文);
    if (文案[0] === 选文 && !文案.some(t => /免费招募|源碳结晶 \+/.test(t))) {
      ok(`「迷路的机师」的选项换成：${文案.map(t => `「${t}」`).join(' / ')}（白送机师、白给源碳两条都删了）`);
    } else bad(`「迷路的机师」还是老样子：${JSON.stringify(文案)}`);
    if (价 === 4) ok(`代价是作者原话里的数字：\`肉鸽数值.机师换券源碳\` = ${价}（不是初稿）`);
    else bad(`换券的源碳价不是 4：${价}`);
    info(`（这一段用的格：第 2 层第 ${命中.k} 格、种子 ${命中.种子} —— 这一格抽到的正好是「迷路的机师」）`);

    /* --- ② 源碳 3 → 选不了：源碳一分不变、券一张不发、名册一台不加 --- */
    {
      const R = 站到迷路(命中.种子);
      R.源碳 = 3;
      const 前 = { 碳: R.源碳, 券: R.券.length, 队: JSON.stringify(R.队伍) };
      const 拦 = 做不了(事.选[0], R);
      const 直接 = 事.选[0].做(R);                                   // 绕过界面直接调 `做()`：也要挡住
      const 走 = 肉鸽.奇遇(选文);                                     // 引擎那条路
      const 没变 = R.源碳 === 前.碳 && R.券.length === 前.券 && JSON.stringify(R.队伍) === 前.队;
      if (拦 && /4/.test(拦) && 直接 == null && 走.ok === false && 没变) {
        ok(`源碳 3（< 4）→ **选不了**：理由「${拦}」；引擎 \`ok=false\`（why「${走.why}」）；` +
           `源碳 3 → ${R.源碳}、券 ${前.券} → ${R.券.length} 张、名册 ${R.队伍.length} 台 —— 一分都没动`);
      } else bad(`源碳不够却选得了：${JSON.stringify({ 拦, 直接, 走, 碳: R.源碳, 券: R.券.length })}`);
    }

    /* --- ②b 界面上：按钮真的变灰 + 屏上写着可见理由（源碳 4 时不灰） --- */
    {
      const R = 站到迷路(命中.种子);
      const 按钮 = html => (String(html).match(/<button[^>]*奇遇:花 4 源碳结晶[^>]*>/) || [''])[0];
      const 理由行 = html => { const m = /data-事件拦="1">([\s\S]*?)<\/p>/.exec(String(html)); return m ? m[1].replace(/<[^>]*>/g, '') : ''; };
      R.源碳 = 3;
      界面.开屏('奇遇');
      const 屏3 = 屏文字(), 钮3 = 按钮(屏3), 因3 = 理由行(屏3);
      R.源碳 = 4;
      界面.开屏('奇遇');
      const 屏4 = 屏文字(), 钮4 = 按钮(屏4);
      if (/disabled/.test(钮3) && /源碳结晶不够/.test(因3) && 钮4 && !/disabled/.test(钮4)) {
        ok(`界面上：源碳 3 → 那个按钮 \`disabled\` + 屏上可见理由「${因3}」；源碳 4 → 按钮可点（不灰）`);
      } else bad(`界面按钮的灰 / 不灰不对：3「${钮3}」理由「${因3}」/ 4「${钮4}」`);
    }

    /* --- ③ 源碳 4 → 成交：源碳 −4、券 +1（来源 = 事件）、名册不变；顺手验三层反馈 --- */
    {
      const R = 站到迷路(命中.种子);
      R.源碳 = 4;
      const 前 = { 碳: R.源碳, 券: R.券.length, 队: JSON.stringify(R.队伍) };
      const 走 = 界面.选奇遇(选文);                                   // 走玩家那条路（结果条 + 回大地图）
      const 券 = R.券[R.券.length - 1];
      const 条 = 肉鸽界面.提示结果();
      const 行 = ((R.日志 || [])[R.日志.length - 1] || {}).文本 || '';
      if (走 && 走.ok === true && R.源碳 === 前.碳 - 价 && R.券.length === 前.券 + 1
        && 券 && 券.来源 === '事件' && JSON.stringify(R.队伍) === 前.队) {
        ok(`源碳 ${前.碳} → ${R.源碳}（−${价}）、券 ${前.券} → ${R.券.length} 张（+1）、名册 ${R.队伍.length} 台一台没动；` +
           `拿到的是 ${G.券文字(券)}（类别 ${G.券类(券)}）`);
      } else bad(`源碳 4 那一步不对：${JSON.stringify({ 走, 碳: R.源碳, 券: R.券 })}`);
      if (事.选[0].文 === 选文 && 条 && /券/.test(条.文本) && /事件「迷路的机师」/.test(行) && /花 4 源碳结晶/.test(行)) {
        ok(`三层反馈都在：预告「${事.选[0].文}」→ 即时「${条.文本}」→ 结算日志「${行}」`);
      } else bad(`三层反馈缺层：${JSON.stringify({ 预告: 事.选[0].文, 即时: 条 && 条.文本, 结算: 行 })}`);
    }

    /* --- ④ 同种子两遍逐字相同（券的类别 / 名字 / 整份 RUN.券 / 结果句子 / 日志尾巴） --- */
    {
      const 跑一遍 = () => {
        const R = 站到迷路(命中.种子);
        R.源碳 = 4;
        const 走 = 肉鸽.奇遇(选文);
        const 券 = R.券[R.券.length - 1];
        return {
          券: JSON.stringify(R.券), 结果: 走.结果, 名: G.券名(券), 类: G.券类(券), 来源: 券.来源,
          /* 只比日志那一行的**文本**：`RUN.日志` 每条还带一个 `时间`（= 真实时钟），那一位本来就不同。 */
          日志: ((R.日志 || [])[R.日志.length - 1] || {}).文本, 碳: R.源碳,
        };
      };
      const 甲 = 跑一遍(), 乙 = 跑一遍();
      if (甲.券 === 乙.券 && 甲.结果 === 乙.结果 && 甲.日志 === 乙.日志 && 甲.名 === 乙.名 && 甲.碳 === 乙.碳) {
        ok(`同种子（${命中.种子} / 第 2 层第 ${命中.k} 格）两遍**逐字相同**：随机券 = 「${甲.名}」（${甲.类} · 来源「${甲.来源}」）；` +
           `结果「${甲.结果}」；连开局 3 张券在内整份 RUN.券 也逐字相同`);
      } else bad(`同种子两遍不一样：\n     甲 ${JSON.stringify(甲)}\n     乙 ${JSON.stringify(乙)}`);
    }

    /* --- ⑤ 没有 RUN / 坏数据不崩 --- */
    {
      const 存 = 肉鸽.RUN;
      let 崩 = null, 无局 = null, 屏崩 = null, 兜底 = '';
      try { 肉鸽.RUN = null; 无局 = 肉鸽.奇遇('0'); } catch (e) { 崩 = e && e.message; }
      try { 兜底 = 肉鸽界面.奇遇屏(); } catch (e) { 屏崩 = e && e.message; }
      肉鸽.RUN = 存;
      if (!崩 && 无局 && 无局.ok === false && !屏崩 && typeof 兜底 === 'string' && 兜底.length) {
        ok(`没有 RUN 时：\`奇遇()\` 给「${无局.why}」、事件屏画兜底卡片 —— 一处都不崩`);
      } else bad(`没有 RUN 时崩了：${JSON.stringify({ 崩, 无局, 屏崩 })}`);
      /* 坏数据：源碳认不出来的一律当 0（拦下来、不扣钱不发券）；字符串 `'4'` 这种还认得 */
      const R = 站到迷路(命中.种子);
      const 试 = 值 => {
        R.源碳 = 值;
        let 拦 = null, 做 = '（没跑）';
        try { 拦 = 做不了(事.选[0], R); 做 = 事.选[0].做(R); } catch (e) { 做 = '崩:' + (e && e.message); }
        return { 值: String(值), 拦, 做 };
      };
      const 结果们 = ['abc', NaN, null, undefined, {}].map(试);
      R.源碳 = '4';
      const 字符串4 = 做不了(事.选[0], R);
      if (结果们.every(x => x.拦 && x.做 === null) && 字符串4 === null) {
        ok(`坏数据不崩：源碳 = ${结果们.map(x => `\`${x.值}\``).join(' / ')} 一律当 0（给出理由、不扣钱、不发券）；` +
           `字符串 \`'4'\` 照样认得（能做）`);
      } else bad(`坏数据没挡住 / 崩了：${JSON.stringify({ 结果们, 字符串4 })}`);
      /* 事件屏对坏数据也不崩 */
      const 存2 = 肉鸽.RUN;
      肉鸽.RUN = { 源碳: 'abc', 种子: 命中.种子, 层: 2, 当前: 命中.k, 券: [], 队伍: [], 日志: [], 事件已选: {}, 地图: { 格: {} } };
      肉鸽.RUN.地图.格[命中.k] = { 类型: '事件' };
      let 坏屏 = null;
      try { 坏屏 = 肉鸽界面.奇遇屏(); } catch (e) { 坏屏 = '崩:' + (e && e.message); }
      肉鸽.RUN = 存2;
      if (typeof 坏屏 === 'string' && /源碳结晶不够/.test(坏屏)) ok('事件屏碰上「源碳是字符串」的坏 RUN 也照画（按钮灰 + 理由），不崩');
      else bad(`事件屏被坏数据搞崩了：${String(坏屏).slice(0, 120)}`);
    }
  }
}

/* ============================ [23] 本局日志（`RUN.日志`）也能复制 / 下载 ============================
 * 作者 2026-10-12：「需要一个对话在**理解规则**的情况下**检视我的游戏记录**，然后**尝试理解我的游戏思路**」。
 * 背景：只有**战斗内**那一份逐条记录能导出（`413d940` / `src/js/88-战斗记录.js` / `tests/battle_ui.js` 第 [11] 段），
 *   而**大地图那一路**（走哪条路 / 在哪买 / 何时晋升 / 遇到什么事件 / 每层怎么花推进剂）只在 `RUN.日志` 里
 *   —— 只看战斗记录看不出作者的路线与花费思路，所以本局日志也要能整本导出。
 *
 * ★ 为什么加在 `tests/map.js` 而不是 `tests/battle_ui.js`：
 *   · 导出的是**肉鸽那一路**的数据（`RUN.日志`）、入口是**记录屏与大地图**（都在 `92-肉鸽界面.js`），
 *     而这一套里已经有：`开一局` / `招几个` / `屏文字` 这些工具、第 [19] 段（结果条）、
 *     第 [20] 段（记录屏）、第 [21] 段（战报写进 `RUN.日志`）—— 同一条线的上下文全在这儿；
 *   · `battle_ui.js` 第 [11] 段测的是**另一份数据**（战斗内 `ctx.log` → 独立 localStorage 键
 *     `mecha-autobattle-战斗记录`），在那一套里要为了这一件再造一局肉鸽（分队 / 券 / 招募 / 地图），
 *     那一套又不碰肉鸽 —— 放过去反而是重复搭台子。
 *
 * 判据（**一条不删、只加**；复制 / 下载本体与失败兜底复用 `88-战斗记录.js` 的那两个口子）：
 *   ① 两个入口都在：记录屏 + 大地图各有一对「复制本局日志 / 下载本局日志 .txt」按钮；
 *   ② 导出文本 = 摘要字段齐（种子 / 分队 / 当前层 / 希望 / 源碳结晶 / 招募券 / 作战耐久 /
 *      队伍（键+等级）/ 藏品 / 零件 / 当前推进剂）+ `RUN.日志` **全部**行原文照抄（抽 3 行比对）；
 *   ③ 三层反馈：复制成功 / 下载成功 / 失败**各有一句可见反馈**（`.resbar` + 失败摊 `.copyout`）；
 *   ④ 复制 / 下载的**成功与失败两条路**各一条断言（失败 = 替身里没有剪贴板 / 没有 Blob）；
 *   ⑤ 没有 RUN / 日志为空 → 不崩 + 给「还没有记录」；坏数据（不是数组 / 坏条目）不崩；
 *   ⑥ 同种子两遍导出**逐字相同**（只去掉「时间：」那一行）；导出**不改 `RUN`**（只读）。 */
console.log('\n[23] 本局日志（RUN.日志）也能复制 / 下载（作者 2026-10-12「记录导出」这一件）');
{
  const 战斗记录 = G.战斗记录;
  const 去时间 = s => String(s).split('\n').filter(l => !/^时间：/.test(l)).join('\n');
  const 反馈 = () => {
    const m = /data-log-export-feedback="1"><b>([^<]*)<\/b><span>([\s\S]*?)<\/span><\/p>/.exec(屏文字());
    return m ? { 类: m[1], 文: m[2] } : null;
  };

  /* --- ① 两个入口 --- */
  let R = 开一局(20261088);
  界面.开屏('大地图');
  const 地图有 = /data-act="复制日志"[^>]*>复制本局日志<\/button>/.test(屏文字())
    && /data-act="下载日志"[^>]*>下载本局日志 \.txt<\/button>/.test(屏文字());
  if (地图有) ok('入口 ②：**大地图**上就有「复制本局日志」/「下载本局日志 .txt」（挂在「记录」旁边 —— 玩家在这一屏做路线 / 花销决策，导出在这儿最顺手）');
  else bad(`大地图上没有导出入口：${屏文字().slice(0, 300)}`);
  界面.动作('去记录');
  const 记录有 = 界面.屏 === '记录' && /data-act="复制日志"[\s\S]{0,80}复制为文本<\/button>/.test(屏文字())
    && /data-act="下载日志"[\s\S]{0,80}下载本局日志 \.txt<\/button>/.test(屏文字());
  if (记录有) ok('入口 ①：**记录屏**（`RUN.日志` 那一屏）里也有一对（复制为文本 / 下载本局日志 .txt）');
  else bad(`记录屏上没有导出入口：屏 ${界面.屏}`);

  /* --- ② 导出文本：摘要字段齐 + 全部日志行原文照抄（抽 3 行） --- */
  const 日志 = 战斗记录.本局日志们(R);
  const 文 = 战斗记录.本局文本(R);
  info('导出文本真实开头 8 行：\n      ' + 文.split('\n').slice(0, 8).join('\n      '));
  const 摘要 = [`种子：${R.种子}`, `分队：${R.分队}`, `当前层：第 ${R.层} 层`, `希望：${R.希望}`,
    `源碳结晶：${R.源碳}`, `招募券：${(R.券 || []).length} 张`, `作战耐久：${R.耐久}`,
    `当前推进剂：${R.推进剂}`, `队伍（${R.队伍.length} 台）：`, `藏品（${(R.藏品 || []).length} 件）：`,
    `零件（${(R.零件 || []).length} 件）：`]
    .concat(R.队伍.map(m => `${m.键} Lv${m.等级}`));
  const 缺摘要 = 摘要.filter(k => !文.includes(k));
  if (!缺摘要.length) {
    ok(`导出文本开头是**一段摘要**：种子 ${R.种子} / 分队 ${R.分队} / 第 ${R.层} 层 / 希望 ${R.希望} / ` +
      `源碳 ${R.源碳} / 招募券 ${(R.券 || []).length} 张 / 耐久 ${R.耐久} / 推进剂 ${R.推进剂} / ` +
      `队伍（${R.队伍.map(m => `${m.键} Lv${m.等级}`).join('、')}）/ 藏品 ${(R.藏品 || []).length} 件 / 零件 ${(R.零件 || []).length} 件`);
  } else bad(`导出文本的摘要缺这些：${缺摘要.join('、')}`);
  const 缺行 = 日志.filter(x => !文.includes(x.文本));
  if (日志.length > 2 && !缺行.length) ok(`RUN.日志 **${日志.length} 条一条不缺**都在导出文本里（含开局 / 招募 / 移动那些行）`);
  else bad(`导出文本漏了 ${缺行.length} 条：${JSON.stringify(缺行.slice(0, 2).map(x => x.文本))}（日志 ${日志.length} 条）`);
  const 抽 = [0, Math.floor(日志.length / 2), 日志.length - 1];
  const 坏行 = 抽.filter(i => !文.includes(`${i + 1}. [第 ${日志[i].层} 层] ${日志[i].文本}`));
  if (!坏行.length) {
    ok(`逐条那一段 = 「序号. [第 N 层] 原文」，**一行一条**（抽第 ${抽.map(i => i + 1).join(' / ')} 条比对原文，一个字没改写；` +
      `例：\`${抽.map(i => `${i + 1}. [第 ${日志[i].层} 层] ${日志[i].文本}`.slice(0, 46) + '…').join('`、`')}\`）`);
  } else bad(`逐条那一段的格式 / 原文不对（第 ${坏行.map(i => i + 1).join('、')} 条）`);
  /* 只读：导出本身一条日志都不许加（「导出」不该写进被导出的东西里） */
  const 条数前 = R.日志.length, 原文前 = JSON.stringify(R.日志);
  战斗记录.本局文本(R); 战斗记录.本局摘要行(R); 战斗记录.本局文件名(R);
  界面.动作('复制日志'); 界面.动作('下载日志');
  if (R.日志.length === 条数前 && JSON.stringify(R.日志) === 原文前) ok(`导出是**只读**的：导出 / 复制 / 下载之后 RUN.日志 仍是那 ${条数前} 条（导出反馈不写日志）`);
  else bad(`导出把 RUN.日志 改了：${条数前} → ${R.日志.length}`);

  /* --- ③ 复制 / 下载：失败与成功两条路 + 三句可见反馈 --- */
  /* 失败（替身里既没有 `navigator.clipboard` 也没有 `document.execCommand`） */
  const 复失 = 界面.动作('复制日志');
  const 屏复失 = 反馈();
  if (复失 && 复失.ok === false && 复失.方式 === '全选文本' && 屏复失 && 屏复失.类 === '警告'
    && /data-copy-out="1"/.test(屏文字()) && 屏文字().includes(复失.文本.slice(0, 40))) {
    ok(`★ 反馈 ③「失败」：复制不成 → 屏上一条警告「${屏复失.文}」，整段文本摊在 \`data-copy-out\` 文本框里（可手动全选）`);
  } else bad(`复制失败那条路不对：${JSON.stringify({ 复失, 屏复失 })}`);
  /* 成功（造一个剪贴板） */
  page.sandbox.navigator.clipboard = { writeText: async t => { page.sandbox.__日志剪贴板 = t; } };
  const 复成 = 界面.动作('复制日志');
  const 屏复成 = 反馈();
  if (复成 && 复成.ok === true && 复成.方式 === '剪贴板' && page.sandbox.__日志剪贴板 === 战斗记录.本局文本(R)
    && 屏复成 && 屏复成.类 === '成功') {
    ok(`★ 反馈 ①「复制成功」：剪贴板里拿到的**就是导出文本**（${复成.字数} 字）—— 屏上写「${屏复成.文}」`);
  } else bad(`复制成功那条路不对：${JSON.stringify({ 复成, 屏复成 })}`);
  delete page.sandbox.navigator.clipboard;
  /* 下载失败（替身里没有 Blob / URL） */
  const 下失 = 界面.动作('下载日志');
  const 屏下失 = 反馈();
  if (下失 && 下失.ok === false && /不支持下载/.test(下失.提示) && 屏下失 && 屏下失.类 === '警告'
    && /data-copy-out="1"/.test(屏文字())) {
    ok(`★ 反馈 ③「失败」：下载不成 → 屏上一条警告「${屏下失.文}」，同样摊出整段文本`);
  } else bad(`下载失败那条路不对：${JSON.stringify({ 下失, 屏下失 })}`);
  /* 下载成功（造一个假浏览器：Blob + URL.createObjectURL；`a` 元素挂在 body 上能回读） */
  {
    const 名 = 战斗记录.本局文件名(R);
    if (名.includes(`种子${R.种子}`) && /^本局日志-第\d+层-种子\d+-\d{8}-\d{6}\.txt$/.test(名)) {
      ok(`下载文件名带种子与时间、没有非法字符：\`${名}\``);
    } else bad(`文件名不对：${名}`);
    page.sandbox.Blob = class { constructor(parts, opt) { this.parts = parts; this.type = opt && opt.type; } };
    page.sandbox.URL = { createObjectURL: b => 'blob:fake/' + String(((b && b.parts && b.parts[0]) || '')).length, revokeObjectURL() {} };
    const 前 = page.sandbox.document.body.children.length;
    const 下成 = 界面.动作('下载日志');
    const 挂的 = page.sandbox.document.body.children[前];
    const 屏下成 = 反馈();
    if (下成 && 下成.ok === true && 挂的 && 挂的.download === 名 && /^blob:fake\//.test(String(挂的.href))
      && 屏下成 && 屏下成.类 === '成功') {
      ok(`★ 反馈 ②「下载成功」：建了 \`a[download="${挂的.download}"]\`（href ${挂的.href}）—— 屏上写「${屏下成.文}」`);
    } else bad(`下载成功那条路不对：${JSON.stringify({ 下成, 屏下成, 挂的: 挂的 && { download: 挂的.download, href: 挂的.href } })}`);
    delete page.sandbox.Blob; delete page.sandbox.URL;
  }
  /* 大地图那一对按钮走的是同一对函数：反馈也在大地图上画出来 */
  界面.开屏('大地图');
  page.sandbox.navigator.clipboard = { writeText: async t => { page.sandbox.__日志剪贴板2 = t; } };
  const 地图复 = 界面.动作('复制日志');
  const 地图反馈 = /data-log-export-feedback="1"/.test(屏文字());
  delete page.sandbox.navigator.clipboard;
  if (地图复 && 地图复.ok === true && 地图反馈 && page.sandbox.__日志剪贴板2 === 战斗记录.本局文本(R)) {
    ok('大地图上的入口与记录屏是**同一对函数**（复制到的文本一样，反馈也照画在大地图上）');
  } else bad(`大地图上的导出不对：${JSON.stringify({ 地图复, 地图反馈 })}`);

  /* --- ④ 没有 RUN / 日志为空 / 坏数据：不崩，给「还没有记录」 --- */
  const 存日志 = R.日志;
  R.日志 = [];
  界面.开屏('记录');
  const 空文 = (() => { try { return 战斗记录.本局文本(R); } catch (e) { return '崩:' + e.message; } })();
  const 空复 = 界面.动作('复制日志'), 空下 = 界面.动作('下载日志');
  const 空屏 = 反馈();
  if (/还没有记录/.test(空文) && 战斗记录.本局有记录(R) === false && 空复 && 空复.ok === false && 空下 && 空下.ok === false
    && /还没有记录/.test(空复.提示) && /还没有记录/.test(空下.提示) && 空屏 && 空屏.类 === '警告' && !/data-copy-out="1"/.test(屏文字())) {
    ok(`日志为空：不崩、给「${空复.提示}」（下载同样），屏上一条警告、**不摊一个空文本框**`);
  } else bad(`日志为空时不对：${JSON.stringify({ 空文: String(空文).slice(0, 60), 空复, 空下, 空屏 })}`);
  R.日志 = 存日志;
  /* 没有 RUN（练习模式 / 平衡工具那条路） */
  {
    const 存RUN = 肉鸽.RUN;
    肉鸽.RUN = null;
    let 崩 = null, 无文 = '', 无复 = null, 无下 = null;
    try { 无文 = 战斗记录.本局文本(null); 无复 = 界面.动作('复制日志'); 无下 = 界面.动作('下载日志'); }
    catch (e) { 崩 = e && e.message; }
    肉鸽.RUN = 存RUN;
    if (!崩 && /还没有记录/.test(无文) && 无复 && 无复.ok === false && /还没有记录/.test(无复.提示)
      && 无下 && 无下.ok === false && /还没有记录/.test(无下.提示)) {
      ok(`没有 RUN：导出文本写「还没有记录」、两个按钮都不崩（「${无复.提示}」），练习模式那条路不受影响`);
    } else bad(`没有 RUN 时崩了 / 提示不对：${JSON.stringify({ 崩, 无复, 无下 })}`);
  }
  /* 坏数据：日志不是数组 / 条目是垃圾 → 不崩，认得出来的那一条照抄 */
  {
    const 存 = R.日志;
    let 崩 = null, 坏们 = null;
    try { R.日志 = '不是数组'; 坏们 = { 不是数组: 战斗记录.本局有记录(R), 文: String(战斗记录.本局文本(R)).length }; } catch (e) { 崩 = e && e.message; }
    let 条目 = null;
    try {
      R.日志 = [null, {}, { 文本: '好的一条', 层: 2 }, 42];
      条目 = { 们: 战斗记录.本局日志们(R), 文: 战斗记录.本局文本(R) };
    } catch (e) { 崩 = 崩 || (e && e.message); }
    R.日志 = 存;
    if (!崩 && 坏们.不是数组 === false && 坏们.文 > 0 && 条目 && 条目.们.length === 4
      && 条目.文.includes('2. [第 ? 层] （这条记录没有文本）') && 条目.文.includes('3. [第 2 层] 好的一条')) {
      ok(`坏数据不崩：\`日志 = '不是数组'\` → 当空（只写「还没有记录」）；条目是 \`null\` / \`{}\` / 数字 → 一行一条、` +
        `坏的那条写「（这条记录没有文本）」，**认得出来的那一条照样原文照抄**（第 3 条「好的一条」）`);
    } else bad(`坏数据没挡住 / 崩了：${JSON.stringify({ 崩, 坏们, 条目: 条目 && { n: 条目.们.length, 文: String(条目.文).slice(0, 200) } })}`);
  }

  /* --- ⑤ 同种子两遍导出逐字相同（只去掉「时间：」那一行） --- */
  {
    const 导 = 种子 => 去时间(战斗记录.本局文本(开一局(种子)));
    const 甲 = 导(20261089), 乙 = 导(20261089);
    /** 第一处不同（对账用；全同 → null）。 */
    const 首处不同 = (a, b) => {
      const A = a.split('\n'), B = b.split('\n');
      for (let i = 0; i < Math.max(A.length, B.length); i++) if (A[i] !== B[i]) return `第 ${i + 1} 行：甲「${A[i]}」乙「${B[i]}」`;
      return null;
    };
    if (甲 === 乙 && 甲.includes('———— 本局日志（原文照抄，共 ')) {
      ok(`同种子（20261089）两遍导出**逐字相同**（${甲.split('\n').length} 行）；唯一随时间变的那一行按口径去掉 —— ` +
        `「${战斗记录.本局文本(肉鸽.RUN).split('\n')[1]}」`);
    } else bad(`同种子两遍导出不一样：${甲 === 乙 ? '（内容相同但少了「原文照抄」那一段？）' : 首处不同(甲, 乙)}`);
  }
}

/* ============================ [24] 出口守军没清 → 谁都不许通关 / 换层 ============================
 * ★ 2026-10-13 修 bug（作者 2026-10-13 试玩 + 对局录像日志第 280–300 条：「出口守军打输了，却还是通关了」）。
 *
 * 改动前有**两条**换层路（`界面.前进()` 是唯一入口，但它内部走两条）：
 *   ① 正常换层：`界面前进()` 自己查守军 → 挡住了；
 *   ② **推进剂 0 → 追击战**：打赢追击战 → `追击之后()` → `换层()` → 第 4 层直接 `通关()` —— **没查守军**。
 * 所以只要「守军没清 + 推进剂 0（或拖着到 0）」就能**跳过终点 Boss 通关**，与
 * `CLAUDE.md` 第 2 节 M4 段「第 4 层：打赢出口守军 → 点出口 → 肉鸽.下一层() → 层 ≥ 4 → 肉鸽.通关()」冲突。
 *
 * 这一段的四条断言（都是**真的跑**，用真实局部状态 + 真实存档）：
 *   A 守军没清 → `肉鸽.下一层()`（含第 4 层）**不通关、不换层**，挡的这句话进 `RUN.日志`；
 *   B A 之后再让追击战打赢（`肉鸽.追击之后()`，= 引擎里「追击打赢」那一步）→ **还是不通关、不换层**，
 *     这一趟记进 `RUN.待换层`；存档→读档回来**欠账还在**；
 *   C 守军真打赢（`肉鸽.战斗结束('胜','出口守军',…)`）→ **当场补上换层**（第 1 层 → 第 2 层），欠账清空；
 *   D 守军清掉之后的正常出口（第 1–3 层）**照旧换层、照旧把剩余推进剂换成希望**（没修坏）；
 *   E 同种子（同一步操作两遍）**逐字相同**。
 * 旧→新：改动前 A / B 两条会「层 +1」甚至「通关」；现在都留在原层。为什么改：规格要「打完终点 Boss 通关」。 */
console.log('\n[24] 出口守军没清 → 第 4 层不许通关、第 1–3 层不许换层（追击战那条路也不行）');
{
  /** 清掉存档（这一段会真的存档 / 读档，别把存档漏给后面的段）。 */
  const 清档 = () => { try { localStorage.removeItem(G.存档键); } catch (e) {} };
  /** 摆好名册 + 站到「层」层的出口那一格上（守军格按 `清守军` 决定清不清）。 */
  const 摆好 = (种子, 层, { 清守军 = false, 推进剂 = 0 } = {}) => {
    const R = 开一局(种子);
    R.队伍 = [{ 键: 'CB1', 等级: 30 }];
    R.出击 = R.队伍.slice();
    R.层 = 层; R.场次 = 0;
    R.地图 = G.生成层(层, G.地图种子(R.种子, 层));
    const m = R.地图;
    if (清守军) { m.格[m.守军].已过 = true; m.格[m.守军].类型 = '空'; }
    R.当前 = m.出口; R.地图.格[R.当前].已过 = true;
    R.推进剂 = 推进剂;
    return R;
  };
  const 记们 = R => R.日志.map(x => (x && x.文本) || '');

  /* --- A：守军没清 → 第 1 层的「出口那一步的追击战」换不了层 --- */
  {
    const R = 摆好(20261010, 1, { 推进剂: 0 });
    const m = R.地图;
    const 层前 = R.层, 希前 = R.希望;
    R.出口追击 = true;                      // ← `界面.前进()` 在「脚下是出口格 + 推进剂 0」时置的那一位
    肉鸽.追击之后();                        // 引擎里「追击战打赢 → 换层」那一步
    const 挡了 = R.层 === 层前 && !R.结局 && 肉鸽.进行中 && !肉鸽.守军已清()
      && 记们(R).some(t => t.includes('出口守军还没打掉')) && R.希望 === 希前;
    if (挡了) {
      ok(`A 守军没清时「出口那一步的追击战」不放行：**不换层**（层还是 ${R.层}）、希望没换（${希前} → ${R.希望}）；` +
        `日志写「${记们(R).filter(t => t.includes('出口守军还没打掉')).pop()}」`);
    } else bad(`A 守军没清也换层了：层 ${层前} → ${R.层}、结局 ${R.结局}、希望 ${希前} → ${R.希望}、进行中 ${肉鸽.进行中}`);
    if (R.待换层 && R.待换层.层 === 层前 && R.待换层.追击 === true && R.层推进剂修正 === -2) {
      ok(`A 这一趟没白打：记进 \`RUN.待换层\` = ${JSON.stringify(R.待换层)}（追击的 −2 也在），等守军被打赢当场兑现`);
    } else bad(`A 待换层没记对：${JSON.stringify(R.待换层)}、层推进剂修正 ${R.层推进剂修正}`);
    const 一 = 肉鸽.读存档();
    if (一 && 一.待换层 && 一.待换层.层 === 层前 && 一.层 === 层前 && 一.追击 === true) {
      ok(`A 存档 → 读档：欠的那一次换层还在（${JSON.stringify(一.待换层)}，层 ${一.层}）—— 关掉页面再继续不会丢`);
    } else bad(`A 待换层没过存档：${JSON.stringify(一 && { 待换层: 一.待换层, 层: 一.层, 追击: 一.追击 })}`);
    /* --- B：守军真打赢 → 当场补上这一趟（第 1 层 → 第 2 层） --- */
    const R2 = 摆好(20261010, 1, { 推进剂: 0 });
    const 希2 = R2.希望;
    const 守军2 = R2.地图.格[R2.地图.守军];          // 抓住**第 1 层**那一格（换层之后 `R.地图` 就换新图了）
    R2.出口追击 = true;
    肉鸽.追击之后();                        // 先欠一趟
    const 欠过 = R2.待换层 && R2.待换层.层 === 1;
    R2.当前 = R2.地图.守军;
    const r2 = 肉鸽.战斗结束('胜', '出口守军', { 结果: '胜', 敌方: [], 我方: [] });
    if (欠过 && R2.层 === 2 && 肉鸽.进行中 && !R2.待换层 && 守军2.已过 && 守军2.类型 === '空'
        && r2 && r2.守军已清 && R2.希望 > 希2) {
      ok(`B 守军打赢那一下**当场补上换层**：第 1 层 → 第 ${R2.层} 层（希望 ${希2} → ${R2.希望}），` +
        `第 1 层那一格清空（已过 / 类型 ${守军2.类型}）、欠账清空`);
    } else bad(`B 打赢守军没补上换层：层 ${R2.层}、待换层 ${JSON.stringify(R2.待换层)}、欠过 ${欠过}、` +
      `第 1 层守军格 ${JSON.stringify(守军2 && { 已过: 守军2.已过, 类型: 守军2.类型 })}、希望 ${希2} → ${R2.希望}`);
    /* --- C：第 4 层 + 守军没清 + 出口那一步的追击 → **不许通关**（作者报的那一条） --- */
    const R4 = 摆好(155847, 4, { 推进剂: 0 });
    const 层4 = R4.层, 结局4 = R4.结局;
    R4.出口追击 = true;
    肉鸽.追击之后();
    if (R4.层 === 层4 && R4.结局 === 结局4 && 肉鸽.进行中 && !记们(R4).some(t => t.includes('通关！'))) {
      ok(`C 第 4 层守军没清、出口那一步的追击打完 → **不通关**（结局 ${R4.结局}、层还是 ${R4.层}）—— 「守军打输了却还是通关了」堵上了`);
    } else bad(`C 第 4 层守军没清还是通关了：结局 ${R4.结局}、层 ${R4.层}`);
    /* --- D：追击战在**别处**（不是出口那一步）打赢 → 照旧换层（老行为不许砍） --- */
    {
      const R5 = 摆好(20261010, 1, { 推进剂: 0 });
      const 层5 = R5.层;
      R5.追击 = true;                       // `追击之后()` 的自我状态：不是出口那一步，没有 `出口追击`
      const 换 = 肉鸽.追击之后();
      if (R5.层 === 层5 + 1 && !R5.待换层 && !R5.出口追击) {
        ok(`D 追击战在**别处**打赢照旧换层（第 ${层5} 层 → 第 ${R5.层} 层；战棋 31:300 的 chase 分支没动 —— \`tests/map.js\` 第 [4] 段的断言没删没放宽）`);
      } else bad(`D 「别处的追击战」被误伤了：层 ${层5} → ${R5.层}、待换层 ${JSON.stringify(R5.待换层)}`);
    }
    /* --- E：守军清掉之后的正常出口照旧（第 1–3 层）--- */
    let 正常 = 0;
    for (const [种子, 层] of [[20261010, 1], [20261020, 2], [20261030, 3]]) {
      const R3 = 摆好(种子, 层, { 清守军: true, 推进剂: 5 });
      const 希3 = R3.希望;
      const 换 = 界面.前进('尽头');
      if (换 === true && R3.层 === 层 + 1 && R3.希望 === 希3 + Math.floor(5 * G.肉鸽数值.出口换希望) && !R3.待换层) 正常++;
      else bad(`E 第 ${层} 层清掉守军后走不动了：返回 ${换}、层 ${层} → ${R3.层}、希望 ${希3} → ${R3.希望}（期望 +${Math.floor(5 * G.肉鸽数值.出口换希望)}）`);
    }
    if (正常 === 3) ok(`E 清掉守军之后第 1 / 2 / 3 层的正常出口**照旧换层、照旧换希望**（3 / 3，没修坏）`);
    /* --- F：走真实入口 —— 守着出口那一步（推进剂 1、一步进出口）**连战斗都不开**，第 4 层不通关 --- */
    {
      const R7 = 摆好(155847, 4, { 推进剂: 1 });
      界面.开屏('大地图');                  // 走真实入口前先回大地图（`开一局()` 停在招募屏）
      肉鸽界面.清结果();
      const 邻 = G.邻居(R7.地图.出口, R7.地图.列数).filter(k => R7.地图.格[k] && k !== R7.地图.守军)[0];
      R7.当前 = 邻; R7.地图.格[邻].已过 = true;
      const 类型 = 界面.去节点(R7.地图.出口);
      /* 走到出口那一格就把推进剂花成 0（= 追击条件），但守军没清 —— `前进()` 入口的守军闸在
         「推进剂 0 → 追击战」**之前**，所以连追击战都不开打（这正是改动前漏掉的那一条路）。 */
      const 没开打 = 界面.屏 === '大地图' && 界面.肉鸽战斗类型 !== '追击';
      if (类型 === '出口尽头' && 没开打 && R7.当前 === R7.地图.出口 && R7.推进剂 === 0
          && R7.层 === 4 && !R7.结局 && 肉鸽.进行中 && !R7.待换层) {
        ok(`F 走真实入口（推进剂 1、守军没清）：点出口那一格 → 推进剂 1 → 0、**没开追击战**（肉鸽战斗类型 ${界面.肉鸽战斗类型}）、` +
          `第 4 层**不通关**（结局 ${R7.结局}）—— 作者报的那条路在入口就断了`);
      } else bad(`F 真实入口没挡住：类型 ${类型}、屏 ${界面.屏}、肉鸽战斗类型 ${界面.肉鸽战斗类型}、` +
        `当前 ${R7.当前 === R7.地图.出口 ? '出口' : R7.当前}、层 ${R7.层}、结局 ${R7.结局}、待换层 ${JSON.stringify(R7.待换层)}`);
    }
    /* --- G：同种子同操作两遍逐字相同 --- */
    const 跑一遍 = () => {
      const R6 = 摆好(155847, 4, { 推进剂: 0 });
      R6.出口追击 = true;
      肉鸽.追击之后();
      return JSON.stringify({ 层: R6.层, 结局: R6.结局, 希望: R6.希望, 推进剂: R6.推进剂, 待换层: R6.待换层, 日志: 记们(R6) });
    };
    const 甲 = 跑一遍(), 乙 = 跑一遍();
    if (甲 === 乙) ok(`G 同种子（155847）同操作两遍**逐字相同**（${JSON.parse(甲).日志.length} 条日志）`);
    else bad('G 同种子两遍不一样');
    清档(); 肉鸽.清存档();
  }
}




