    if (!扫到.length) ok('③ 逐屏静态审计：每个屏画出来的 `data-act` **全都派发得到**（一个孤儿动作都没有）');
    else bad(`③ 逐屏静态审计发现孤儿动作：${扫到.join('；')}`);
