/* ★ 这一节全在**微任务**里跑（真弹窗是异步的）：`对话框()` 返回 Promise，
   `肉鸽弹窗().then(回调)` 才结算 —— 所以每一个「真点」之后都要 `await 一步()` 让结算跑完，
   才能接着摆下一个场景（同步连开好几局会把 `肉鸽.RUN` 换掉，结算就落到别人身上了 —— 这是本次踩到的坑）。
   ★★ 还有一条：本节**必须在第 [25] 段那两条异步断言之后**才开始（同样是因为同步脚本里
      「后面的段落会先跑同步部分」）—— 所以整节包在一层 `Promise.resolve().then(async () => {…})` 里。 */
console.log('\n[26] 「遗迹三选一还是选不了」第二次回归：**真点事件委托**（弹窗必须消失 + 真的结算）');
globalThis.__ui真点已排程 = true;
Promise.resolve().then(async () => {
  /** 让排在后面的微任务（Promise 链 / 节点结算）跑完再继续 */
  const 一步 = async (轮 = 4) => { for (let i = 0; i < 轮; i++) await Promise.resolve(); };
  /* ★ 先等第 [25] 段那两条异步断言收完（__待收尾 归 0）再开工。
     本文件是同步脚本：[25] 的异步收尾排在这一节**前面**，但这一节的同步部分会先跑 ——
     要是不等，[25] 的续跑就会读到本节刚开的局（两边抢 肉鸽.RUN）。 */
  while ((Number(globalThis.__待收尾) || 0) > 0) await 一步(1);
  globalThis.__待收尾 = 1;                 // ← 这一节自己的那一份，跑完（不管成功失败）减掉

  /* ---------- 真点用的最小事件系统（不碰 dom-stub，只在测试这一节里生效） ---------- */
  const 监听 = new WeakMap();
  const 补元素 = el => {
    if (!el || el.__可点) return el;
    el.__可点 = true;
    el.closest = sel => {
      let n = el;
      while (n) {
        if (n.getAttribute) {
          if (sel === '[data-act]' && n.getAttribute('data-act') != null) return n;
          if (sel === '[data-drag]' && n.getAttribute('data-drag') != null) return n;
          if (sel === '[data-drop]' && n.getAttribute('data-drop') != null) return n;
          if (sel === 'select[data-act]' && n.tagName === 'SELECT' && n.getAttribute('data-act') != null) return n;
        }
        n = n.parentNode || null;
      }
      return null;
    };
    const 原挂 = (typeof el.addEventListener === 'function' ? el.addEventListener : () => {}).bind(el);
    el.addEventListener = (事件, fn) => {
      if (!监听.has(el)) 监听.set(el, {});
      监听.get(el)[事件] = fn;
      原挂(事件, fn);
    };
    return el;
  };
  /* 开机能挂的那几个容器（`接线()` 只挂 #screen / #ctrl）都补挂一份 ——
     dom-stub 的 `addEventListener` 是空实现，开机那次挂的监听在测试里抓不到。 */
  for (const id of ['screen', 'ctrl', 'hud']) { 补元素(page.getEl('#' + id)); page.getEl('#' + id)['_接了click'] = false; }
  界面.接线();
  补元素(page.getEl('#screen')); 补元素(page.getEl('#ctrl'));
  const 事件监听器 = 名 => (监听.get(page.getEl('#' + 名)) || {}).click;
  /** 从当前屏的 HTML 里找一颗 `data-act` 匹配「值」（正则片段）的按钮，做一个人造元素 */
  const 找按钮 = 值 => {
    const m = new RegExp('<button[^>]*data-act="(' + 值 + ')"[^>]*>').exec(屏文字());
    if (!m) return null;
    return 补元素({
      tagName: 'BUTTON',
      getAttribute: k => (k === 'data-act' ? m[1] : null),
      addEventListener() {}, removeEventListener() {},
    });
  };
  /** 真点一下：走 `#screen` 上挂的那一条委托（**就是浏览器里走的那条**），并记下派发到了什么 */
  const 点 = 值 => {
    const 钮 = 找按钮(值);
    if (!钮) return { 找到: false };
    const 监听器 = 事件监听器('screen');
    if (!监听器) return { 找到: true, 挂了: false };
    const 记 = [];
    const 原动作 = 界面.动作.bind(界面);
    /* ★ 2026-10-13（⑧ 段）：`接线()` 改成「第一个 `:` 之后全留着」之后，**没有 `:` 的值**参恰好是
       `null`（改前是 `undefined`）—— 两者都表示「没有参数」，所以这里统一按「无参」渲染成光秃秃的动作名。
       下面几条既有断言（② / ④b 的 `记.join()`）**一个字都没改**：它们比的就是「整键动作派发成什么」。 */
    界面.动作 = (动, 参) => { 记.push(动 + (参 == null ? '' : ':' + 参)); return 原动作(动, 参); };
    let 错 = null;
    try { 监听器({ target: 钮, preventDefault() {} }); } catch (e) { 错 = String(e && e.message); }
    界面.动作 = 原动作;
    return { 找到: true, 挂了: true, act: 钮.getAttribute('data-act'), 错, 记 };
  };

  /* ---------- 开一局 + 站到目标格**前面那一格**（最后一步由 `去节点` 真的走进去） ---------- */
  const 站到旁边 = (种子, 层, 类型) => {
    界面.动作('回菜单'); 界面.动作('去分队'); 界面.动作('选分队', '无');
    界面.动作('开新局:' + (种子 >>> 0));
    const R = 肉鸽.RUN;
    /* 名册是空的（券系统：分队不带机体）—— 没有名册的话 `肉鸽.能去的()` 是空的。
       招 3 台走**玩家那条路**（补一张对得上的券 → 用券招人），与第 [5b] 段的 `招几个()` 同一套。 */
    界面.开屏('招募');
    {
      const 费 = k => G.肉鸽数值.招募费[G.tierOf(k)] || 0;
      for (let 轮 = 0; R.队伍.length < 3 && 轮 < 20; 轮++) {
        const 已有 = new Set(R.队伍.map(m => m.键));
        const 人 = G.ALLY_T.map(t => t.mech).filter(k => !已有.has(k));
        const 能付 = 人.filter(k => R.希望 >= 费(k)).sort((a, b) => 费(a) - 费(b))[0];
        if (能付 == null) break;
        R.券.push({ 类: '职业', 名: G.tplOf(能付).tags.战斗分类, 档: null, 来源: '测试' });
        const 补 = R.券.length - 1;
        界面.用券(补);
        const r = 肉鸽.招募(能付, 补);
        肉鸽界面.选中的券 = null;
        if (!r || !r.ok) break;
      }
    }
    /* 上一段留下的战斗对象要清掉 —— 不然「侵蚀源先弹窗」那条会被上一场的 `ctx` 顶掉 */
    界面.ctx = null; 界面.肉鸽战斗 = null; 界面.肉鸽战斗类型 = null; 界面.单位开关 = {};
    界面.对话框钩子 = null;                        // 真弹窗那条路
    if (R.层 !== 层) 肉鸽.进层(层);
    R.源碳 = 40; R.耐久 = 10; R.推进剂 = 60; R.零件 = [];
    R.侵蚀源已净化 = {};                            // 每一段都从「这一格还没付代价」开始
    const k = 找格(R, 类型);
    if (k == null) return null;
    /* ★ 站到**最短路上的前驱格**（一定与目标格相邻、也一定走得到；随便找个邻格不保证走得到）。
       沿路那些格**全记进 `已走过`**（正常经过的格），最后一步是事件格，交给 `去节点` 触发。 */
    const 距离 = G.BFS距离(R.地图.起点, R.地图.格, R.地图.列数);
    if (!距离.has(k)) return null;
    const 前驱 = [];
    let 走 = k;
    while (走 !== R.地图.起点) {
      const 往 = G.邻居(走, R.地图.列数).filter(x => R.地图.格[x] && 距离.has(x) && 距离.get(x) === 距离.get(走) - 1);
      if (!往.length) return null;
      走 = 往[0];
      前驱.unshift(走);
    }
    R.已走过 = 前驱.slice();
    for (const x of R.已走过) R.地图.格[x].已过 = true;
    R.当前 = R.地图.起点;
    肉鸽.跳格(前驱[前驱.length - 1]);
    界面.开屏('大地图');
    return k;
  };
  const 快照 = R => JSON.stringify({
    源碳: R.源碳, 耐久: R.耐久, 推进剂: R.推进剂, 希望: R.希望,
    零件: (R.零件 || []).length, 日志: (R.日志 || []).length, 藏品: (R.藏品 || []).length,
    已过: R.地图.格[R.当前] ? !!R.地图.格[R.当前].已过 : null,
  });
  const 格过没过 = (R, k) => !!(R.地图.格[k] && R.地图.格[k].已过);

  try {
    /* ======================= ① 遗迹：三个选项**各真点一次** ======================= */
    const 遗迹 = [];
    for (const 值 of ['藤蔓', '交流', '离开']) {
      const k = 站到旁边(20261013, 2, '遗迹');
      if (k == null) { 遗迹.push(null); continue; }
      const R = 肉鸽.RUN;
      const 前 = 快照(R);
      const 点格 = 点('去节点:' + k);
      const 开着 = !!(界面.弹窗 && 界面.弹窗.选项 && 界面.弹窗.选项.length === 3);
      const 值们 = 开着 ? 界面.弹窗.选项.map(o => o.值) : null;
      const 画了 = (屏文字().match(/data-act="弹窗:[^"]*"/g) || []).length;
      const 点钮 = 点('弹窗:' + 值);
      await 一步(6);                              // ← 等 `肉鸽弹窗().then(回调)` 把这一格结算完
      遗迹.push({ 值, k, R, 前, 点格, 开着, 值们, 画了, 点钮, 清了: 界面.弹窗 === null, 后: 快照(R), 已过: 格过没过(R, k), 日志: R.日志.map(x => x.文本) });
    }
    const 成 = 遗迹.filter(Boolean);
    if (成.length !== 3) bad('① 摆不到遗迹旁边（20261013 第 2 层）');
    else {
      if (成.every(r => r.开着 && r.值们.join('/') === '藤蔓/交流/离开' && r.画了 === 3)) {
        ok('① 真点格子：三个答案的弹窗**真的画在当前屏上**（`data-act="弹窗:藤蔓/交流/离开"` 各一个）——' +
          '`弹窗控件Html()` 拼在 `大地图屏()` 里、在 `#screen` 内，事件委托挂的就是它');
      } else bad('① 弹窗没画全：' + JSON.stringify(成.map(r => [r.开着, r.值们, r.画了])));
      if (成.every(r => r.清了 && r.点钮.记 && r.点钮.记.join() === '弹窗:' + r.值)) {
        ok('① **真点弹窗按钮** → `界面.弹窗` 变 null（点击真的落到了派发器上，走的是 `动=弹窗 / 参=<值>` 那条两段式）' +
          '—— 旧代码在这里弹窗一动不动');
      } else bad('① 点完弹窗没清 / 没派发到：' + JSON.stringify(成.map(r => [r.值, r.清了, r.点钮.记])));
      if (成.every(r => r.后 !== r.前 && r.已过)) {
        ok('① 三个选项**各点一次都真的生效**（状态变了、这一格标记已过）：' +
          成.map(r => `${r.值} → ${JSON.parse(r.后).源碳} 源碳 / ${JSON.parse(r.后).耐久} 耐久 / ${JSON.parse(r.后).零件} 零件`).join('、'));
      } else bad('① 有选项点了不生效：' + JSON.stringify(成.map(r => [r.值, r.前, r.后, r.已过])));
      if (new Set(成.map(r => r.后)).size === 3) ok('① 三个结果**互不相同**（3 种状态）—— 旧代码是「永远等于第一项」');
      else bad(`① 三个结果只有 ${new Set(成.map(r => r.后)).size} 种：` + JSON.stringify(成.map(r => r.后)));
      const N = G.肉鸽数值;
      const [藤, 交, 离] = 成;
      const 藤好 = JSON.parse(藤.后), 交好 = JSON.parse(交.后), 离好 = JSON.parse(离.后);
      if (藤好.耐久 === 10 - N.遗迹耐久价 && 藤好.源碳 === 40 + N.遗迹源碳 && 藤好.零件 === 1) {
        ok(`① 「清理藤蔓」的数字对得上：耐久 10 → ${藤好.耐久}（−${N.遗迹耐久价}）、源碳 40 → ${藤好.源碳}（+${N.遗迹源碳}）、零件 +${藤好.零件}`);
      } else bad(`① 藤蔓数字不对：${藤.后}`);
      if (交好.源碳 === 40 - N.遗迹源碳价 + N.遗迹源碳 && 交好.耐久 === 10 && 交好.零件 === 1) {
        ok(`① 「试着和它交流」的数字对得上：源碳 40 → ${交好.源碳}（−${N.遗迹源碳价} +${N.遗迹源碳}）、耐久不动、零件 +${交好.零件}`);
      } else bad(`① 交流数字不对：${交.后}`);
      if (离好.源碳 === 40 && 离好.耐久 === 10 && 离好.零件 === 0 && JSON.parse(离.后).日志 > JSON.parse(离.前).日志) {
        ok('① 「离开」真的什么都不拿（源碳 / 耐久 / 零件都不动）但**仍写一行日志**、弹窗照样消失');
      } else bad(`① 离开不对：${离.后}`);
      if (/遗迹（清理门口的藤蔓）/.test(藤.日志.join('')) && /遗迹（试着和它交流）/.test(交.日志.join('')) && /遗迹：看了看就走了/.test(离.日志.join(''))) {
        ok('① 三次结算**各写了自己那一行日志**（藤蔓 / 交流 / 离开三句都在，`RUN.日志` 真的长大了）');
      } else bad('① 三次的日志文案不对：' + JSON.stringify(成.map(r => r.日志.slice(-2))));
    }

    /* ======================= ② 对照：不带 `:` 的动作照旧点得动 ======================= */
    {
      const k = 站到旁边(20261014, 2, '遗迹');
      if (k == null) bad('② 摆不到遗迹旁边');
      else {
        界面.动作('去晋升');
        const 回 = 点('回大地图');
        await 一步();
        if (回.找到 && 回.挂了 && 回.记.join() === '回大地图' && 界面.屏 === '大地图') {
          ok('② 同一屏上「不带 `:`」的动作（「回大地图」）走**同一条委托**照旧点得动：派发记录 = ' + JSON.stringify(回.记) +
            '、屏 = 大地图 —— 所以这次坏掉的**只有「动作名 + 参数」那种两段式**（弹窗这一族）');
        } else bad('② 对照组点不动了：' + JSON.stringify(回));
        界面.开屏('大地图');
      }
    }

    /* ======================= ③ 同族节点各真点一次 ======================= */
    {
      const N = G.肉鸽数值;
      /* 隧道 */
      let 记隧 = null;
      for (const 种子 of [20261013, 20261015, 20261016]) {
        const k = 站到旁边(种子, 2, '隧道');
        const R = 肉鸽.RUN;
        if (k == null || !(R.地图.隧道 && R.地图.隧道.length === 2)) continue;
        const 前 = { 当前: R.当前, 推进剂: R.推进剂 };
        点('去节点:' + k);
        const 开着 = !!(界面.弹窗 && 界面.弹窗.选项 && 界面.弹窗.选项.length === 2);
        const 点钮 = 点('弹窗:go');
        await 一步(6);
        记隧 = { 种子, k, 前, 开着, 点钮, 清了: 界面.弹窗 === null, 后: { 当前: R.当前, 推进剂: R.推进剂 }, 到: R.地图.隧道.find(t => t !== k) };
        break;
      }
      if (记隧 && 记隧.开着 && 记隧.清了 && 记隧.点钮.记.join() === '弹窗:go' && 记隧.后.当前 === 记隧.到 && 记隧.后.推进剂 === 记隧.前.推进剂 - 1 - N.隧道花费) {
        ok(`③ 隧道：真点「传送过去」→ 位置 ${记隧.前.当前} → ${记隧.后.当前}（另一头）、推进剂 ${记隧.前.推进剂} → ${记隧.后.推进剂}、弹窗消失`);
      } else bad('③ 隧道真点没生效：' + JSON.stringify(记隧));
      /* 休整 */
      let 记休 = null;
      for (const 种子 of [20261013, 20261015, 20261016]) {
        const k = 站到旁边(种子, 2, '休整');
        const R = 肉鸽.RUN;
        if (k == null || R.层 <= 1) continue;
        const 前 = { 耐久: R.耐久 };
        点('去节点:' + k);
        const 开着 = !!(界面.弹窗 && 界面.弹窗.选项 && 界面.弹窗.选项.length === 3);
        const 点钮 = 点('弹窗:耐久');
        await 一步(6);
        记休 = { 种子, 前, 开着, 点钮, 清了: 界面.弹窗 === null, 后: { 耐久: R.耐久 } };
        break;
      }
      if (记休 && 记休.开着 && 记休.清了 && 记休.点钮.记.join() === '弹窗:耐久' && 记休.后.耐久 === 记休.前.耐久 + N.休整耐久) {
        ok(`③ 休整：真点「坐下休息」→ 作战耐久 ${记休.前.耐久} → ${记休.后.耐久}（+${N.休整耐久}）、弹窗消失`);
      } else bad('③ 休整真点没生效：' + JSON.stringify(记休));
      /* 瞭望站 */
      let 记瞭 = null;
      for (const 种子 of [20261013, 20261015, 20261016]) {
        const k = 站到旁边(种子, 1, '瞭望站');
        const R = 肉鸽.RUN;
        if (k == null) continue;
        const 前 = { 揭开: (R.已揭开 || []).length };
        点('去节点:' + k);
        const 开着 = !!(界面.弹窗 && 界面.弹窗.选项 && 界面.弹窗.选项.length === 2);
        const 点钮 = 点('弹窗:登高');
        await 一步(6);
        记瞭 = { 种子, 前, 开着, 点钮, 清了: 界面.弹窗 === null, 后: { 揭开: (R.已揭开 || []).length }, 条: 肉鸽界面.提示结果() };
        break;
      }
      if (记瞭 && 记瞭.开着 && 记瞭.清了 && 记瞭.点钮.记.join() === '弹窗:登高' && 记瞭.条 && /瞭望站（登高）/.test(记瞭.条.文本)) {
        ok(`③ 瞭望站：真点「登高」→ 「${记瞭.条.文本.slice(0, 42)}…」（揭开 ${记瞭.前.揭开} → ${记瞭.后.揭开} 格）、弹窗消失`);
      } else bad('③ 瞭望站真点没生效：' + JSON.stringify(记瞭));
      /* 招募站「不招，继续前进」 */
      let 记招 = null;
      for (const 种子 of [20261013, 20261015, 20261016]) {
        const k = 站到旁边(种子, 1, '招募站');
        const R = 肉鸽.RUN;
        if (k == null) continue;
        点('去节点:' + k);
        if (界面.屏 !== '招募') continue;
        const 点钮 = 点('跳过节点');
        await 一步(4);
        记招 = { 种子, 点钮, 屏: 界面.屏, 已过: 格过没过(R, k) };
        break;
      }
      if (记招 && 记招.点钮.找到 && 记招.屏 === '大地图' && 记招.已过) {
        ok('③ 招募站：真点「不招，继续前进」（`data-act="跳过节点"`）→ 这一格已过 + 回大地图');
      } else bad('③ 招募站「不招，继续前进」真点没生效：' + JSON.stringify(记招));
    }

    /* ======================= ④ 侵蚀源：先弹窗（战斗没开），点「净化」才开打 ======================= */
    {
      const N = G.肉鸽数值;
      let 记侵 = null;
      for (const 种子 of [20261013, 20261015, 20261016]) {
        const k = 站到旁边(种子, 2, '侵蚀源');
        if (k == null) continue;
        const R = 肉鸽.RUN;
        R.源碳 = 40;
        const 前 = { ctx: !!界面.ctx, 源碳: R.源碳 };
        点('去节点:' + k);
        const 开着 = !!(界面.弹窗 && 界面.弹窗.选项 && 界面.弹窗.选项.length === 2);
        const 值们 = 界面.弹窗 ? 界面.弹窗.选项.map(o => o.值) : null;
        const 点钮 = 点('弹窗:净化');
        await 一步(20);
        记侵 = { 种子, R, 前, 开着, 值们, 点钮, 代价: 肉鸽.侵蚀源代价(), 源碳: R.源碳, 屏: 界面.屏 };
        break;
      }
      if (记侵 && 记侵.开着 && 记侵.前.ctx === false && 记侵.值们.join('/') === '硬闯/净化') {
        ok('④ 侵蚀源：真点「出击」→ **先弹窗、战斗没开**（硬闯 / 净化两选一）—— 旧代码是「弹窗没人回答却直接开打」');
      } else bad('④ 侵蚀源没先弹窗：' + JSON.stringify(记侵 && { 开着: 记侵.开着, 前: 记侵.前, 值们: 记侵.值们 }));
      /* ★ 这一条只钉「净化真的生效」+「这一条路真的往下走了（离开大地图）」——界面.ctx 是全局单例上的字段，
         这份测试后面还有段落会重置它，拿它当判据会假红（实测过）。「点净化 → 打这一场」那条链归第 [25] ② 段管。 */
      if (记侵 && 记侵.点钮.记.join() === '弹窗:净化' && 记侵.源碳 === 40 - N.侵蚀源净化价 && 记侵.代价 === '净化' && 记侵.屏 !== '大地图') {
        ok(`④ 真点「净化」真的生效：源碳 40 → ${记侵.源碳}（−${N.侵蚀源净化价}）、代价 = 净化、**这才往下走**（屏 ${记侵.屏}）`);
      } else bad('④ 真点「净化」没生效：' + JSON.stringify(记侵 && { 记: 记侵.点钮.记, 源碳: 记侵.源碳, 代价: 记侵.代价, 屏: 记侵.屏 }));
    }

    /* ======================= ④b 侵蚀源：选完代价**自动开打**（真 bug 回归） =======================
     * 真因（`80-界面.js` 的 `去节点()`，侵蚀源那一支）：**真点（浏览器 / Promise）那条链**
     * 原来到 `准备肉鸽编队()` 就完了 —— **没有接着 `打这一场()`**，所以选完代价只停在编队屏，
     * 玩家得自己再点一次「开战」；而**同步钩子那条路**是
     * `准备肉鸽编队()` →（编队屏点「开战」→ `从编队开战肉鸽()`）→ `打这一场()`，直接进战斗。
     * 两条路因此**不一致**（不是卡死，但要多点一次）。这一段把两条路都推到结算、逐字对账。
     * ★ 全程**真派发点击**（照 ④ 段 / [26] 段的写法），不直调 `去节点()`。 */
    {
      /** 把这一场同步推到结算，返回可逐字对账的那一串（记录来自 `界面.战报`，与结算屏同一份数据源）。
       *  `界面.打这一场()` 是**开打（准备）**；真的推一回合是 `界面.开打()`（跳过动画 → 播放引擎直接跳结尾）。 */
      const 打到结算 = () => {
        const ctx = 界面.ctx;
        if (!ctx) return { 进战斗: false, 文: JSON.stringify({ 屏: 界面.屏, ctx: false }) };
        界面.设跳过动画(true);
        let 轮 = 0;
        while (界面.阶段 !== '结算' && 轮++ < 8) 界面.开打();
        const b = 界面.战报 || {};
        return {
          进战斗: true, 屏: 界面.屏, 结果: b.结果, 回合数: b.回合数, 记录数: (b.记录 || []).length,
          文: JSON.stringify({
            结果: b.结果, 原因: b.原因, 回合数: b.回合数, 种子: b.种子,
            记录: (b.记录 || []).map(e => `${e.回合}|${e.类型}|${e.文本}|${e.伤害 == null ? '' : e.伤害}|${e.目标剩余HP == null ? '' : e.目标剩余HP}`),
          }),
        };
      };
      /** 开局局面（两条路都该逐字一样：同一格、同一阵、同一种子、同一批敌人）。
       *  ★ 没有 `ctx` 时**照样返回**（不抛错）—— 那正是本段要抓的那个 bug 的样子（旧代码停在编队屏）。 */
      const 开局局面 = () => JSON.stringify({
        屏: 界面.屏, ctx: !!界面.ctx,
        我方: 界面.ctx ? 界面.ctx.allies.length : 0, 敌方: 界面.ctx ? 界面.ctx.enemies.length : 0,
        种子: 界面.种子, 格类型: 界面.肉鸽战斗 && 界面.肉鸽战斗.格类型,
        我方位: 界面.ctx ? 界面.ctx.allies.map(u => [u.key, u.slot, u.hp, u.maxHp]) : [],
        敌方键: 界面.ctx ? 界面.ctx.enemies.map(u => [u.key, u.slot]) : [],
      });
      /** 一个选项跑一条路：真点（浏览器 / Promise）或同步钩子。
       *  真点那条路**选完代价就进战斗**；钩子那条路停在编队屏、要再点一次「开战」。
       *  返回这一路的关键量（给逐字对账用）。 */
      const 跑一条 = async (路, 选项) => {
        const k = 站到旁边(20261013, 2, '侵蚀源');
        if (k == null) return null;
        const R = 肉鸽.RUN;
        if (路 === '真点') {
          const 点格 = 点('去节点:' + k);
          const 开着 = !!(界面.弹窗 && 界面.弹窗.选项 && 界面.弹窗.选项.length === 2);
          const 值们 = 界面.弹窗 ? 界面.弹窗.选项.map(o => o.值) : null;
          const 弹窗前 = { 屏: 界面.屏, ctx: !!界面.ctx };
          const 点钮 = 点('弹窗:' + 选项);
          await 一步(20);                                   // ← 等 Promise 链（弹窗答案 → 续跑）跑完
          return { k, R, 路, 选项, 点格: 点格.记, 开着, 值们, 弹窗前, 点钮: 点钮.记, 进编队屏: null,
            战斗前: 开局局面(), 打: 打到结算(), 引擎屏: 界面.屏, 阶段: 界面.阶段, 源碳: R.源碳, 代价: 肉鸽.侵蚀源代价() };
        }
        界面.对话框钩子 = () => 选项;
        界面.动作('去节点:' + k);
        界面.对话框钩子 = null;
        await 一步(4);
        const 进编队屏 = 界面.屏;
        const 点钮 = 点('开战');                             // 编队屏上玩家点的那一颗（data-act="开战"）
        await 一步(6);
        return { k, R, 路, 选项, 点格: null, 开着: null, 值们: null, 弹窗前: null, 点钮: 点钮.记, 进编队屏,
          战斗前: 开局局面(), 打: 打到结算(), 引擎屏: 界面.屏, 阶段: 界面.阶段, 源碳: R.源碳, 代价: 肉鸽.侵蚀源代价() };
      };

      const 两路 = {};                                     // 选项 → { 真点, 钩子 }
      for (const 选项 of ['硬闯', '净化']) {
        const 真点 = await 跑一条('真点', 选项);
        const 钩子 = await 跑一条('钩子', 选项);
        两路[选项] = { 真点, 钩子 };
        if (!真点 || !钩子) { bad('④b 摆不到侵蚀源旁边（20261013 第 2 层）'); continue; }

        /* 真点那条路：**不等任何人再点**，选完代价自己进战斗（旧代码在这里停在编队屏） */
        const 真点开局 = JSON.parse(真点.战斗前), 钩子开局 = JSON.parse(钩子.战斗前);
        if (真点.开着 && 真点.值们 && 真点.值们.join('/') === '硬闯/净化' && 真点.弹窗前.ctx === false &&
            真点.点钮.join() === '弹窗:' + 选项 && 真点.点格.join() === '去节点:' + 真点.k) {
          ok(`④b【${选项}】侵蚀源：真点「出击」→ 先弹窗、战斗没开（屏 ${真点.弹窗前.屏}、ctx ${真点.弹窗前.ctx}）；` +
            `真点「${选项}」→ 代价生效（源碳剩 ${真点.源碳}、代价 ${真点.代价}）`);
        } else bad(`④b【${选项}】弹窗那一段不对：` + JSON.stringify({ 开着: 真点.开着, 值们: 真点.值们, 弹窗前: 真点.弹窗前, 点钮: 真点.点钮 }));
        if (真点开局.ctx && 真点开局.屏 === '战斗') {
          ok(`④b【${选项}】★ 真点那条路**选完代价就自动进战斗**（不等任何人再点）：屏 = ${真点开局.屏}、ctx 非空` +
            `（我方 ${真点开局.我方} 台 / 敌方 ${真点开局.敌方} 台）—— 旧代码在这里停在**编队屏**`);
        } else bad(`④b【${选项}】★ 真点选完代价**没自动进战斗**：屏 ${真点开局.屏}、ctx ${真点开局.ctx}`);
        /* 战报链完整（弹窗 → 选代价 → 开打 → 结算） */
        if (真点.打.进战斗 && 真点.阶段 === '结算' && 真点.打.回合数 >= 1 && 真点.打.记录数 > 0) {
          ok(`④b【${选项}】这一场真的打完了：${真点.打.结果} / ${真点.打.回合数} 回合 / ${真点.打.记录数} 条记录（打完回到 ${真点.打.屏}）`);
        } else bad(`④b【${选项}】战斗没打完：` + JSON.stringify({ 阶段: 真点.阶段, ...真点.打 }));
        /* 同步钩子那条路：停在编队屏 → 点「开战」才进战斗（与改前逐字同路） */
        if (钩子.进编队屏 === '编队' && 钩子.点钮.join() === '开战' && 钩子开局.ctx && 钩子开局.屏 === '战斗') {
          ok(`④b【${选项}】同步钩子那条路照旧：选完代价 → **编队屏**（${钩子.进编队屏}）→ 点「开战」→ 战斗（与改前逐字同路）`);
        } else bad(`④b【${选项}】同步那条路变了：` + JSON.stringify({ 进编队屏: 钩子.进编队屏, 点钮: 钩子.点钮, 屏: 钩子开局.屏, ctx: 钩子开局.ctx }));
        /* ★ 两条路：开局局面 + 打到结算，**逐字相同** */
        if (真点.战斗前 === 钩子.战斗前) {
          ok(`④b【${选项}】★ 两条路的**开局局面逐字相同**：` + 真点.战斗前);
        } else bad(`④b【${选项}】两条路开局局面不一样：\n      真点 ${真点.战斗前}\n      钩子 ${钩子.战斗前}`);
        if (真点.打.文 === 钩子.打.文) {
          const j = JSON.parse(真点.打.文);
          ok(`④b【${选项}】★ 两条路**打到结算也逐字相同**（${j.结果} / ${j.回合数} 回合 / ${j.记录.length} 条记录 / 种子 ${j.种子}）`);
        } else bad(`④b【${选项}】两条路的战斗结果不一样：\n      真点 ${真点.打.文.slice(0, 300)}\n      钩子 ${钩子.打.文.slice(0, 300)}`);
      }

      /* ---- ④b-4 同种子同操作两遍**逐字相同**（真点那条路，两遍都打到结算） ---- */
      {
        const 跑一遍 = async () => {
          const k = 站到旁边(20261013, 2, '侵蚀源');
          点('去节点:' + k);
          点('弹窗:净化');
          await 一步(20);
          const 打 = 打到结算();
          return JSON.stringify({ 开局: 开局局面(), 战斗: 打.文, 日志: 肉鸽.RUN.日志.map(x => x.文本) });
        };
        const 甲 = await 跑一遍(), 乙 = await 跑一遍();
        if (甲 === 乙) ok('④b ★ 同种子（20261013）同操作（真点格子 + 真点「净化」+ 打完）两遍**逐字相同**' +
          `（${JSON.parse(甲).战斗.length} 字的战斗记录 / ${JSON.parse(甲).日志.length} 条日志）`);
        else bad('④b 同种子两遍不一样：\n      甲 ' + 甲.slice(0, 300) + '\n      乙 ' + 乙.slice(0, 300));
      }
    }

    /* ======================= ⑤ 两条路（`对话框钩子` 同步 vs 真点）逐字相同 ======================= */
    {
      const 跑 = async 用钩子 => {
        const k = 站到旁边(20261013, 2, '遗迹');
        const R = 肉鸽.RUN;
        if (用钩子) {
          界面.对话框钩子 = () => '交流';
          界面.动作('去节点:' + k);
          界面.对话框钩子 = null;
          await 一步(6);
        } else {
          点('去节点:' + k);
          点('弹窗:交流');
          await 一步(6);
        }
        return JSON.stringify({
          源碳: R.源碳, 耐久: R.耐久, 零件: (R.零件 || []).length, 已过: 格过没过(R, k),
          日志: R.日志.map(x => x.文本),
        });
      };
      const 钩子 = await 跑(true);
      const 真点 = await 跑(false);
      if (钩子 === 真点) {
        ok('⑤ 两条路**结果逐字相同**（`对话框钩子` 同步返回「交流」vs 真点弹窗「交流」）—— 钩子那条（测试 / 探针 / 录像重放）' +
          '一个字节都没动：' + JSON.parse(钩子).源碳 + ' 源碳 / ' + JSON.parse(钩子).零件 + ' 零件 / ' + JSON.parse(钩子).日志.length + ' 条日志');
      } else bad('⑤ 两条路不一样：\n      钩子   ' + 钩子 + '\n      真点   ' + 真点);
    }

    /* ======================= ⑥ 同种子同操作两遍逐字相同（真点那条路） ======================= */
    {
      const 跑一遍 = async () => {
        const k = 站到旁边(20261013, 2, '遗迹');
        const R = 肉鸽.RUN;
        点('去节点:' + k);
        点('弹窗:藤蔓');
        await 一步(6);
        return JSON.stringify({
          源碳: R.源碳, 耐久: R.耐久, 零件: (R.零件 || []).map(p => p.k), 已过: 格过没过(R, k),
          地图: JSON.stringify(R.地图), 日志: R.日志.map(t => t.文本),
        });
      };
      const 甲 = await 跑一遍(), 乙 = await 跑一遍();
      if (甲 === 乙) ok('⑥ 同种子（20261013）同操作（真点格子 + 真点「藤蔓」）两遍**逐字相同**（地图 / 状态 / 日志全一致）');
      else bad('⑥ 同种子两遍不一样：\n      甲 ' + 甲.slice(0, 200) + '\n      乙 ' + 乙.slice(0, 200));
    }

    /* ======================= ⑦ 边界：没有弹窗 / 没有 RUN 时不崩 ======================= */
    {
      const 回 = 界面.动作('弹窗:藤蔓');           // 此刻没有弹窗
      if (回 === '藤蔓') ok('⑦ 没有弹窗时点 `弹窗:<值>` 不崩、照旧返回那个值（`回答()` 对空弹窗是安全的）');
      else bad('⑦ 空弹窗时 `弹窗:<值>` 返回 ' + JSON.stringify(回));
      const 前 = 界面.弹窗;
      const 回2 = 界面.动作('弹窗', '交流');       // 两段式那条，同样没有弹窗
      if (回2 === '交流' && 界面.弹窗 === 前) ok('⑦ 两段式「弹窗」+ 参数、同样没有弹窗时也不崩（返回 ' + JSON.stringify(回2) + '）');
      else bad('⑦ 两段式空弹窗不对：' + JSON.stringify(回2));
      肉鸽.RUN = null; 肉鸽.进行中 = false;
      let 抛错 = null, 回3 = '（没跑）';
      try { 回3 = 界面.去遗迹(); } catch (e) { 抛错 = (e && e.message) || String(e); }
      if (抛错 == null && 回3 === null) ok('⑦ 没有 RUN 时 `去遗迹()` 返回 null、不崩（离线兜底那条路也没变）');
      else bad('⑦ 没有 RUN 时 `去遗迹()` 抛错 ' + JSON.stringify(抛错) + '、返回 ' + JSON.stringify(回3));
      界面.开屏('菜单');
      肉鸽.RUN = null; 肉鸽.进行中 = false;
    }

    /* ======================= ⑧ 全仓库所有含 ≥2 个 `:` 的 data-act：清单式断言（随代码增长） =======================
     * 真因（`src/js/80-界面.js` 的 `接线()`，改前那一句在 `:141`）：
     *     `const [动, 参] = String(t.getAttribute('data-act')).split(':')`
     *   —— **解构只取前两个元素**，含 ≥2 个 `:` 的值（`调参室:类型:精英`、`调参室:层:3`…）
     *   第三段起**全被丢掉**：`动作()` 收到 `('调参室', '类型')`，`调参室动作()` 再拆一次只剩空参数
     *   （`类型 = ''` / `层 = 0` / `场次 = 1`）→ 调参室那一屏**所有带参数的选项点了行为不对**
     *   （按钮画得出来、点得动，就是不算数 —— 与 2026-10-13 修掉的「弹窗族」同一族）。
     *   ⚠ **这不是 Node / `String.prototype.split` 的 bug**（界面线报错过一次，统筹判它诊断错了）：
     *     `'a:b:c'.split(':')` 老实给出三个元素，**全仓库没有一处 `split` 写错**；错的是**解构只要两个**。
     *   ⚠ 现在全仓库含 ≥2 个 `:` 的 `data-act` **只有调参室这一族**（29 个值 / 8 种形状）；
     *     4 段及以上（3 个冒号）现在**一个都没有** —— 修法对**任意段数**都成立（⑧-4 用合成值钉着）。
     * 这一段两层：
     *   ① **清单（会随代码增长）**：把能画出来的屏全画一遍、收齐所有 `data-act` 值；
     *      每一个含 ≥2 个 `:` 的值都必须能在下面 8 条**形状**里找到一条 ——
     *      新加一个这样的值却没写进清单 → 这一条**红**（这就是「随代码增长」）。
     *   ② **真点**：清单里每一个值都从**屏上真的画着的那颗按钮**、经 `#screen` 的 click 委托点一次，
     *      断言「派发到的 (动, 参)」+「该走的处理逻辑真的走了、参数完整」。 */
    {
      const M = G.调参室模型;
      /** 真派发一颗**屏上真的画着**的按钮（按整串比对，不拼正则 —— 值里有 `%` / `:` 也不怕）。
       *  `#screen` 与 `#ctrl` 两处都找（`回菜单` 这类是在 `#ctrl` 里的），落在哪个容器就用哪个容器的委托。
       *  `要画在屏上 = false` 用于合成值（⑧-4），只走委托、不要求屏上有它。 */
      const 派发 = (值, 要画在屏上 = true) => {
        const 有 = html => (String(html || '').match(/data-act="[^"]*"/g) || []).some(s => s === 'data-act="' + 值 + '"');
        const 在屏 = 有(屏文字()), 在控 = 有(page.byId.get('ctrl') && page.byId.get('ctrl').innerHTML);
        if (要画在屏上 && !在屏 && !在控) return { 画了: false };
        const 监听器 = 事件监听器(在控 && !在屏 ? 'ctrl' : 'screen');
        if (!监听器) return { 画了: 在屏 || 在控, 挂了: false };
        const 钮 = 补元素({
          tagName: 'BUTTON',
          getAttribute: k => (k === 'data-act' ? 值 : null),
          addEventListener() {}, removeEventListener() {},
        });
        const 记 = [];
        const 原 = 界面.动作.bind(界面);
        界面.动作 = (动, 参) => { 记.push([动, 参]); return 原(动, 参); };
        let 错 = null;
        try { 监听器({ target: 钮, preventDefault() {} }); } catch (e) { 错 = String((e && e.message) || e); }
        界面.动作 = 原;
        return { 画了: 在屏 || 在控, 挂了: true, 记, 错 };
      };
      const 设置快照 = () => JSON.stringify({
        层: M.设置.层, 类型: M.设置.类型, 条目: M.设置.条目, 方针: M.设置.方针, 场次: M.设置.场次,
        覆盖: Object.keys(M.设置.覆盖 || {}), Boss: Object.keys(M.设置.Boss || {}),
      });
      const 铺底 = 补 => {                          // 每一颗都从**干净**的设置起（免得上一颗串味）
        M.恢复默认();
        if (补) M.设(补);
        M.选中敌人键 = 'grunt';
        界面.动作('去调参室');
      };
      /* 8 条**形状** = 清单。`参` 是「委托该把什么当参传下去」的独立答案（不拿修好的那句代码算，避免自证）。 */
      const 形状 = [
        { 名: '调参室:层', 匹配: /^调参室:层:(\d+)$/, 参: m => '层:' + m[1], 铺: null,
          验: m => M.设置.层 === Number(m[1]) && M.设置.条目 === null, 说: '切到第 N 层（并把「具体编成条目」清回全部）' },
        { 名: '调参室:类型', 匹配: /^调参室:类型:(.+)$/, 参: m => '类型:' + m[1], 铺: null,
          验: m => M.设置.类型 === m[1] && M.设置.条目 === null, 说: '切节点类型（同样清条目）' },
        { 名: '调参室:条目', 匹配: /^调参室:条目:(\d+|全部)$/, 参: m => '条目:' + m[1], 铺: null,
          验: m => (m[1] === '全部' ? M.设置.条目 === null : M.设置.条目 === Number(m[1])), 说: '选具体编成条目（「全部」= null）' },
        { 名: '调参室:方针', 匹配: /^调参室:方针:(.+)$/, 参: m => '方针:' + m[1], 铺: null,
          验: m => M.设置.方针 === decodeURIComponent(m[1]), 说: '整场方针（值 percent-encoded，末尾不能再被截）' },
        { 名: '调参室:覆盖加上', 匹配: /^调参室:覆盖加上:(.+)$/, 参: m => '覆盖加上:' + m[1],
          铺: m => { M.选中敌人键 = m[1]; }, 验: m => !!(M.设置.覆盖 || {})[m[1]], 说: '给那台敌机加上按键覆盖' },
        { 名: '调参室:覆盖去掉', 匹配: /^调参室:覆盖去掉:(.+)$/, 参: m => '覆盖去掉:' + m[1],
          铺: m => { M.选中敌人键 = m[1]; M.设({ 覆盖: { [m[1]]: { HP倍率: 2, 装甲倍率: 1, 威力倍率: 1 } } }); },
          验: m => !((M.设置.覆盖 || {})[m[1]]), 说: '去掉那台敌机的按键覆盖（铺好的那一件）' },
        { 名: '调参室:Boss清', 匹配: /^调参室:Boss清:(.+)$/, 参: m => 'Boss清:' + m[1],
          铺: m => { M.设({ Boss: { [m[1]]: { 大技能间隔: 5 } } }); },
          验: m => !((M.设置.Boss || {})[m[1]]), 说: '那一台 Boss 恢复正式表（铺好的那一件）' },
        { 名: '调参室:场次', 匹配: /^调参室:场次:(\d+)$/, 参: m => '场次:' + m[1], 铺: null,
          验: m => M.设置.场次 === Number(m[1]), 说: '改场次' },
      ];
      const 拆 = 值 => 形状.map(x => ({ x, m: x.匹配.exec(值) })).find(y => y.m) || null;

      /* ---------- ⑧-1 收屏：把能画出来的屏全画一遍，收齐 data-act 值 ---------- */
      const 发现 = new Map();
      const 下拉值 = new Set();                  // `<select data-act="…">`（接线对它们传 `t.value`，与「参」无关）
      const 收屏 = 名 => {
        const html = 屏文字() + String((page.byId.get('ctrl') && page.byId.get('ctrl').innerHTML) || '');
        let 个 = 0;
        for (const t of html.matchAll(/data-act="([^"]*)"/g)) {
          个++;
          if (!发现.has(t[1])) 发现.set(t[1], new Set());
          发现.get(t[1]).add(名);
        }
        for (const t of html.matchAll(/<select[^>]*data-act="([^"]*)"/g)) 下拉值.add(t[1]);
        return 个;
      };
      const 屏单 = [];
      for (const s of ['菜单', '编队', '分队', '战斗记录', '录像']) { 界面.开屏(s); 屏单.push([s, 收屏(s)]); }
      /* 调参室三种状态（默认 / 铺了按键覆盖与 Boss / 换了「当前敌人键」）—— 覆盖去掉 与 Boss清 只在前一种下画 */
      M.恢复默认(); 界面.动作('去调参室'); 屏单.push(['调参室（默认）', 收屏('调参室')]);
      M.恢复默认();
      M.设({ 覆盖: { artillery: { HP倍率: 2, 装甲倍率: 1, 威力倍率: 1 } }, Boss: { bluefish: { 大技能间隔: 5 } } });
      界面.动作('去调参室'); 屏单.push(['调参室（有覆盖/Boss）', 收屏('调参室')]);
      M.选中敌人键 = 'grunt'; 界面.开屏('调参室'); 屏单.push(['调参室（选中 grunt）', 收屏('调参室')]);
      /* 一局肉鸽：各屏 + **每一种节点类型的大地图**（格菜单的 data-act 会跟着变） */
      {
        const k = 站到旁边(20261013, 2, '遗迹');
        if (k != null) {
          for (const s of ['大地图', '招募', '记录', '晋升', '奇遇', '黑市']) { 界面.开屏(s); 屏单.push([s, 收屏(s)]); }
          界面.动作('去零件'); 屏单.push(['零件', 收屏('零件')]);
          const R = 肉鸽.RUN;
          const 型 = new Set();
          for (let i = 0; i < 49; i++) {
            const n = R.地图.格[i];
            if (!n || 型.has(n.类型)) continue;
            型.add(n.类型);
            R.当前 = i;
            界面.开屏('大地图');
            屏单.push(['大地图·' + n.类型, 收屏('大地图·' + n.类型)]);
          }
        }
      }
      /* 战斗屏（真开一场）：`方针:` / `大招:` / `选单位:` 这些一条都不能少 */
      {
        const k = 站到旁边(20261013, 1, '作战');
        if (k != null) {
          点('去节点:' + k);
          if (界面.屏 === '编队') { 点('开战'); await 一步(6); }
          屏单.push([界面.屏, 收屏(界面.屏)]);
        }
      }
      const 全部值 = [...发现.keys()];
      const 多段 = 全部值.filter(v => (v.match(/:/g) || []).length >= 2).sort();
      const 没形状 = 多段.filter(v => !拆(v));
      ok(`⑧-1 收屏：画了 ${屏单.length} 屏、收齐 ${全部值.length} 个不同的 \`data-act\` 值` +
        `（其中含 ≥2 个 \`:\` 的 **${多段.length} 个**）—— 屏：` + 屏单.map(x => `${x[0]}(${x[1]})`).join(' / '));
      if (没形状.length === 0) {
        ok(`⑧-1 ★ 清单（随代码增长）：${多段.length} 个含 ≥2 个 \`:\` 的值**全部**落在 8 条形状里：` +
          形状.map(x => `${x.名}×${多段.filter(v => 拆(v).x === x).length}`).join(' / '));
      } else {
        bad(`⑧-1 ★ 出现**清单里没有**的含 ≥2 个 \`:\` 的 data-act（新加了这种值就要补进 ⑧ 的清单）：` +
          JSON.stringify(没形状));
      }

      /* ---------- ⑧-2 真点：清单里每一个值都经 #screen 的 click 委托点一次 ---------- */
      let 绿 = 0; const 红 = [];
      for (const 值 of 多段) {
        const 认 = 拆(值);
        if (!认) { 红.push([值, '清单里没有这种形状']); continue; }
        铺底();
        if (认.x.铺) 认.x.铺(认.m);
        界面.开屏('调参室');                      // 让这一颗按钮真的画出来
        const 前 = 设置快照();
        const r = 派发(值, true);
        const 对 = r.画了 && r.挂了 && !r.错 && r.记.length === 1 &&
          r.记[0][0] === '调参室' && r.记[0][1] === 认.x.参(认.m) && 认.x.验(认.m);
        if (对) 绿++;
        else 红.push([值, JSON.stringify({ 画了: r.画了, 记: r.记, 错: r.错, 前, 后: 设置快照() })]);
        console.log(`    ${对 ? '✓' : '✗'} ${值}`);
        console.log(`        派发 → ${r.记.length ? JSON.stringify(r.记[0]) : '（没派发到）'}` +
          `　期望参 = ${JSON.stringify(认.x.参(认.m))}　${认.x.说}`);
      }
      if (红.length === 0) {
        ok(`⑧-2 ★ 真点：${绿} / ${多段.length} 个含 ≥2 个 \`:\` 的 data-act **都走到了该走的处理逻辑、参数完整**` +
          `（旧代码在这里全都只派发成「动 + 子动作名」、参数被截断）`);
      } else {
        bad(`⑧-2 ★ 真点：${红.length} 个不对（绿 ${绿} / 共 ${多段.length}）：` + JSON.stringify(红.slice(0, 6)));
      }

      /* ---------- ⑧-3 没有 `:` 的值：参**恰好是 null**（不能变成 `''`，也不能变成 Number(null)=0） ---------- */
      {
        /* 每一条都从**画着这颗按钮的那一屏**起（`回菜单` 在菜单上当然没有，所以它从编队屏起） */
        const 三例 = [['回菜单', '编队', '菜单'], ['去调参室', '菜单', '调参室'], ['去编队', '菜单', '编队']];
        const 果 = 三例.map(([值, 起屏, 期望屏]) => {
          界面.开屏(起屏);
          const r = 派发(值, true);
          return { 值, 起屏, 期望屏, 参: r.记 && r.记.length ? r.记[0][1] : '（没派发）', 动: r.记 && r.记[0] ? r.记[0][0] : null, 屏: 界面.屏 };
        });
        if (果.every(x => x.动 === x.值 && x.参 === null && x.屏 === x.期望屏)) {
          ok('⑧-3 整键动作（`data-act` 里本来就没有 `:`）：参**恰好是 null**（不是空串、不是 undefined、不是 0），' +
            '行为照旧 —— ' + 果.map(x => `${x.值}→${x.屏}:${JSON.stringify(x.参)}`).join(' / '));
        } else bad('⑧-3 没有 `:` 的值参不对：' + JSON.stringify(果));
        /* 再钉一条「null 没有被 Number() 成 0」：`清空` 是整键动作，参是 null 时它照旧清空编队 */
        界面.开屏('编队'); 界面.默认五人队();
        const 人前 = 界面.编队.出击.length;
        const r清 = 派发('清空', true);
        if (人前 > 0 && 界面.编队.出击.length === 0 && r清.记[0][1] === null) {
          ok(`⑧-3 整键动作「清空」：参 = null、真的清空了编队（${人前} 台 → 0 台）`);
        } else bad('⑧-3 「清空」不对：' + JSON.stringify({ 人前, 后: 界面.编队.出击.length, 记: r清.记 }));
        /* `null` 与 `undefined` **唯一**的实现差别是 `Number(null) = 0`（`Number(undefined) = NaN`）——
           而 `放位 / 取回 / 大招 / 选单位 / 用券…` 这些动作恰恰把参 `Number()` 成**格子号**。
           所以再钉一条：**没有一个「没有 `:` 的按钮值」落在这类动作上**（落上去的全是带 `:` 的：
           `放位:0` / `大招:2`…）；`编成` / `调参选敌人键` 这两个没有 `:` 的名字是 `<select>`，
           接线对 SELECT 传的是 `t.value`，null 根本走不到 —— 单独豁免并写出来。 */
        const 数值参动作 = Object.keys(界面.动作表).filter(k => String(界面.动作表[k]).includes('Number(参)'));
        const 无冒号按钮 = 全部值.filter(v => !v.includes(':') && !下拉值.has(v));
        const 撞上 = 无冒号按钮.filter(v => 数值参动作.includes(v));
        if (撞上.length === 0) {
          ok(`⑧-3 ★ 没有冒号的按钮值（${无冒号按钮.length} 个）**一个都不落在** Number(参) 那些动作上` +
            `（${数值参动作.join(' / ')}）—— 所以「无参 = null」不会把 Number(null) = 0 当成合法的第 0 位；` +
            `名字里没有冒号的 编成 / 调参选敌人键 是 select（接线传 t.value，与参无关）`);
        } else bad('⑧-3 有「没有冒号的按钮」落在 Number(参) 的动作上（null 会变成 0）：' + JSON.stringify(撞上));
      }

      /* ---------- ⑧-4 任意段数：合成一个 **4 段**（3 个冒号）的值真派发一次 —— 证明不是「两段式特例补丁」 ---------- */
      {
        const r3 = 派发('调参室:方针:甲:乙', false);
        const r4 = 派发('弹窗:甲:乙:丙', false);
        if (r3.记.length === 1 && r3.记[0][0] === '调参室' && r3.记[0][1] === '方针:甲:乙' &&
            r4.记.length === 1 && r4.记[0][0] === '弹窗' && r4.记[0][1] === '甲:乙:丙') {
          ok('⑧-4 任意段数都保住：合成值 `调参室:方针:甲:乙` → `(\'调参室\', \'方针:甲:乙\')`、' +
            '`弹窗:甲:乙:丙` → `(\'弹窗\', \'甲:乙:丙\')`（第一批 `:` 之后的**所有**段都留着）');
        } else bad('⑧-4 多段合成值被截断了：' + JSON.stringify({ r3: r3.记, r4: r4.记 }));
      }

      /* ---------- ⑧-5 今天修的三处（弹窗族 / 遗迹 / 侵蚀源）**仍然好**：同一条真点路，断言派发串也是完整的 ---------- */
      {
        const 遗迹 = [];
        for (const 值 of ['藤蔓', '交流', '离开']) {
          const k = 站到旁边(20261013, 2, '遗迹');
          if (k == null) { 遗迹.push(null); continue; }
          const R = 肉鸽.RUN;
          const 前 = JSON.stringify({ 源碳: R.源碳, 耐久: R.耐久 });
          点('去节点:' + k);
          const 点钮 = 点('弹窗:' + 值);
          await 一步(6);
          遗迹.push({ 值, 记: 点钮.记, 清了: 界面.弹窗 === null, 后: JSON.stringify({ 源碳: R.源碳, 耐久: R.耐久 }) });
        }
        const 成 = 遗迹.filter(Boolean);
        const 三样都不同 = new Set(成.map(r => r.后)).size === 3;
        if (成.length === 3 && 成.every(r => r.记 && r.记.join() === '弹窗:' + r.值 && r.清了) && 三样都不同) {
          ok('⑧-5【弹窗族 / 遗迹】三个选项各真点一次，派发串都**完整**（`弹窗:藤蔓` / `弹窗:交流` / `弹窗:离开`）、弹窗都消失、三种结果互不相同：' +
            成.map(r => `${r.值}→${r.后}`).join('、'));
        } else bad('⑧-5 遗迹三选一的派发串不对：' + JSON.stringify(成));
        /* 侵蚀源（真点「净化」）：派发串 + 真的扣了源碳 */
        const N = G.肉鸽数值;
        let 侵 = null;
        for (const 种子 of [20261013, 20261015, 20261016]) {
          const k = 站到旁边(种子, 2, '侵蚀源');
          if (k == null) continue;
          const R = 肉鸽.RUN;
          R.源碳 = 40;
          点('去节点:' + k);
          const 点钮 = 点('弹窗:净化');
          await 一步(20);
          侵 = { 记: 点钮.记, 源碳: R.源碳, 代价: 肉鸽.侵蚀源代价() };
          break;
        }
        if (侵 && 侵.记.join() === '弹窗:净化' && 侵.源碳 === 40 - N.侵蚀源净化价 && 侵.代价 === '净化') {
          ok(`⑧-5【侵蚀源】真点「净化」派发串完整（\`弹窗:净化\`）、源碳 40 → ${侵.源碳}（−${N.侵蚀源净化价}）、代价 = 净化`);
        } else bad('⑧-5 侵蚀源「净化」那条不对：' + JSON.stringify(侵));
      }

      /* ---------- ⑧-6 `开新局` 是整键动作：参 = null 时照旧**现取时间**（`肉鸽.新的一局()` 的内部约定：
                      `(种子 >>> 0) || (Date.now() % 900000 + 100000)`，所以现取的种子落在 [100000, 1000000)） ---------- */
      {
        界面.动作('回菜单'); 界面.动作('去分队'); 界面.动作('选分队', '无');
        const r = 派发('开新局', true);
        const 种子 = 肉鸽.RUN ? 肉鸽.RUN.种子 : null;
        const 现取 = 种子 != null && Number.isInteger(种子) && 种子 >= 100000 && 种子 < 1000000;
        if (r.记[0][1] === null && 现取 && 肉鸽.RUN.分队 === '无') {
          ok(`⑧-6 整键动作「开新局」：参 = null（**不是空串**）→ 照旧现取时间当种子、真的开了一局` +
            `（种子 ${种子} 落在 [100000, 1000000) = 现取那一支；分队 = ${肉鸽.RUN.分队}）`);
        } else bad('⑧-6 「开新局」不对：' + JSON.stringify({ 记: r.记, 种子, 分队: 肉鸽.RUN && 肉鸽.RUN.分队 }));
      }
    }
  } catch (e) {
    bad('【26】断言里抛错：' + ((e && e.stack) || e));
  }
  __收尾一步();                            // ← 这一节收工
  末尾退出();                              // ← 全文件唯一的出口（到这里 [25]/[26] 的异步都跑完了）
});

/* ============================ 结果 ============================ */
/** [25]/[26] 的异步收尾计数（只记账，不退出 —— 见下面注释）。 */
function __收尾一步() {
  const n = Number(globalThis.__待收尾) || 0;
  globalThis.__待收尾 = n > 0 ? n - 1 : 0;
  /* ★ 这里**只记账、不退出**：
     · [25] 的收尾会先跑到 0（那时 [26] 的同步部分已经跑过、但 [26] 还没开工）——
       要是这里就 `process.exit`，[26] 一整段都不会跑（真实踩过一次）；
     · 退出只由 [26] 收工那一句 `末尾退出()` 负责。 */
}
function 末尾退出() {
  console.log(`\nERRS [${errs.join(' | ')}]`);
  console.log(fails ? `共 ${fails} 项失败` : '网格大地图测试全部通过');
  process.exit(fails ? 1 : 0);
}
/* ★ [26] 的断言在微任务里（真弹窗是异步的）—— `process.exit` 由那一节的回调里调 `末尾退出()`。
   这里只在 [26] 一节都没跑到时兜底。 */
/* 本文件同步部分到此跑完：[25] 那几条微任务这时都已经**排进队列**了 —— 把占位减掉。
   （[26] 自己在 wait 里等这个计数归 0 再开工；全部归 0 时由 __收尾一步() 调 末尾退出()。） */
globalThis.__同步部分跑完了 = true;
/* ★ 到此为止：[25] 那几条异步断言都已经**排进微任务队列**（它们的 __收尾一步() 会减计数），
   第 [26] 段也在队列里（它开工时给自己 +1）。所以这里**不能**直接退出 —— 退出由 [26] 收尾时调。 */
